INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C1','kor',5,2,'u5',1,'글에 드러나지 않은 내용 — 글에는 모든 것이 쓰여 있지 않아, 쓰여 있지 않은 까닭이나 마음도 단서로 짐작해 볼 수 있다',ARRAY['6국02-02 읽기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C2','kor',5,2,'u5',1,'추론의 뜻 — 글에 드러나지 않은 내용을 글의 단서나 자신의 경험·지식을 바탕으로 짐작하는 것',ARRAY['6국02-02 읽기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C3','kor',5,2,'u5',1,'생활 속 추론 — 말하지 않아도 표정·몸짓·주변 모습을 단서로 상황이나 마음을 짐작하는 일도 추론이다',ARRAY['6국02-02 읽기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C4','kor',5,2,'u5',1,'단원의 흐름 — 추론하며 읽는 방법 알기 → 글쓴이의 생각 파악하기 → 함축된 표현 이해하기 → 글쓴이의 의도 파악하기 → 실천하기',ARRAY['6국02-02 읽기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C5','kor',5,2,'u5',2,'드러난 사실부터 — 추론하기 전에 먼저 글에 드러난 사실을 정확하게 파악한다',ARRAY['6국02-02 읽기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C6','kor',5,2,'u5',2,'글의 단서로 추론하기 — 글 속 여러 단서를 함께 놓고 생각해 드러나지 않은 내용을 짐작한다',ARRAY['6국02-02 읽기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C7','kor',5,2,'u5',2,'경험·지식으로 추론하기 — 배운 지식이나 겪은 경험을 떠올려 글에 쓰여 있지 않은 내용을 짐작한다',ARRAY['6국02-02 읽기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C8','kor',5,2,'u5',2,'근거와 함께 말하기 — 「~라는 단서로 보아」, 「~을 배운 적이 있어서」처럼 짐작한 까닭을 함께 말한다',ARRAY['6국02-02 읽기']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C9','kor',5,2,'u5',2,'추론과 상상은 달라요 — 추론은 떠오르는 대로 지어내는 것이 아니라 단서와 경험·지식이라는 근거를 바탕으로 한다',ARRAY['6국02-02 읽기']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C10','kor',5,2,'u5',2,'짐작은 여럿일 수 있어요 — 근거가 있으면 친구와 짐작이 달라도 견주어 볼 수 있고, 정답 맞히기보다 짐작하는 과정이 중요하다',ARRAY['6국02-02 읽기']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C11','kor',5,2,'u5',4,'이야기 간추리기 — 사건을 다 늘어놓지 않고 중요한 장면만 골라 장면마다 인물의 행동과 변화를 한 문장으로 쓴다',ARRAY['6국02-01 읽기']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C12','kor',5,2,'u5',4,'생략된 내용 추론하기 — 쓰인 사건 사이에 빠진 까닭이나 마음을 글의 단서와 경험·지식으로 채워 읽는다',ARRAY['6국02-02 읽기']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C13','kor',5,2,'u5',4,'글쓴이의 생각 — 글을 통해 전하려는 생각으로, 글에 직접 쓰여 있지 않을 때가 많아 단서를 모아 짐작한다',ARRAY['6국02-01 읽기']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C14','kor',5,2,'u5',4,'글쓴이의 생각을 찾는 단서 — 인물의 말과 행동, 이야기 끝에 일어난 변화, 제목을 단서로 삼는다',ARRAY['6국02-01 읽기']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C15','kor',5,2,'u5',4,'인물의 마음과 분위기의 변화 — 장면마다 인물의 마음과 둘레의 분위기가 어떻게 달라지는지 살피며 읽는다',ARRAY['6국02-02 읽기']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C16','kor',5,2,'u5',7,'문단의 중심 내용 간추리기 — 문단마다 중심 문장을 찾아 간추리면 글 전체의 내용이 보인다',ARRAY['6국02-01 읽기']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C17','kor',5,2,'u5',7,'함축된 표현 — 뜻이 바로 드러나지 않고 숨겨져 있거나 하나의 표현에 여러 뜻이 담긴 표현',ARRAY['6국02-02 읽기']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C18','kor',5,2,'u5',7,'사전에서의 뜻과 글에서의 뜻 — 함축된 표현은 사전에서의 뜻에서 출발해 글의 흐름에 맞는 글에서의 뜻으로 넓혀 읽는다',ARRAY['6국02-02 읽기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C19','kor',5,2,'u5',7,'어색한 곳이 신호 — 사전 뜻대로 읽어 글의 흐름에 맞지 않고 어색한 곳이 숨은 뜻을 찾아야 할 자리이다',ARRAY['6국02-02 읽기']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C20','kor',5,2,'u5',7,'앞뒤 단서로 뜻 찾기 — 그 낱말 하나만 보지 않고 앞뒤 문장에서 숨은 뜻을 알려 주는 단서를 찾는다',ARRAY['6국02-02 읽기']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C21','kor',5,2,'u5',7,'경험·지식으로 숨은 뜻 찾기 — 그 낱말에 대해 알고 있는 것과 겪은 일을 떠올리면 숨은 뜻이 더 분명해진다',ARRAY['6국02-02 읽기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C22','kor',5,2,'u5',7,'함축된 표현의 좋은 점 — 짧은 표현에 여러 뜻을 담아 생각과 마음을 생생하고 깊게 전하고, 읽는 사람이 더 깊이 생각하게 한다',ARRAY['6국02-02 읽기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C23','kor',5,2,'u5',9,'사건의 차례대로 간추리기 — 이야기를 주요 장면 중심으로 일어난 차례대로 간추리면 흐름이 보인다',ARRAY['6국02-01 읽기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C24','kor',5,2,'u5',9,'글쓴이의 의도 — 글쓴이가 독자에게 전하고 싶은 생각이나 바람, 곧 글을 쓴 까닭으로 글의 소재와는 다르다',ARRAY['6국02-02 읽기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C25','kor',5,2,'u5',9,'상황에 따라 달라지는 숨은 뜻 — 같은 말이라도 누가, 어떤 상황에서 했는지에 따라 담긴 숨은 뜻이 달라진다',ARRAY['6국02-02 읽기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C26','kor',5,2,'u5',9,'맞세운 표현 — 앉다와 일어서다처럼 반대되는 말을 맞세워 뜻을 또렷하게 전하기도 한다',ARRAY['6국02-02 읽기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C27','kor',5,2,'u5',9,'글쓴이의 의도를 찾는 단서 — 글의 중심 내용, 인물의 말에 담긴 함축된 표현, 되풀이되는 장면을 단서로 짐작한다',ARRAY['6국02-02 읽기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C28','kor',5,2,'u5',9,'인물의 말과 글쓴이의 의도 — 인물의 말은 이야기 속 상황에서 나온 말이고 의도는 글 전체로 전하려는 생각이라, 둘이 정반대일 수도 있다',ARRAY['6국02-02 읽기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C29','kor',5,2,'u5',9,'해석은 글 속 근거에 맞게 — 해석은 사람마다 다를 수 있지만 글 속 근거와 맞아야 하고, 맞지 않는 해석은 다시 살핀다',ARRAY['6국02-02 읽기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C30','kor',5,2,'u5',12,'감정을 함축된 표현으로 — 감정을 느낄 때 겪는 몸과 마음의 변화를 빗대어 말하면 감정의 깊이와 빛깔까지 전해진다',ARRAY['6국02-02 읽기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C31','kor',5,2,'u5',12,'감정 카드의 약속 — 앞면에는 감정을 그림으로, 뒷면에는 감정 낱말 없이 함축된 표현으로 쓴다',ARRAY['6국02-02 읽기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C32','kor',5,2,'u5',12,'짐작하고 확인하기 — 친구의 마음을 짐작한 뒤 맞는지 물어보고, 다르면 친구의 설명을 귀 기울여 듣는다',ARRAY['6국02-02 읽기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C33','kor',5,2,'u5',12,'공감하는 말 — 짐작한 마음에 맞추어 친구를 놀리지 않고 마음을 알아주는 말을 건넨다',ARRAY['6국02-02 읽기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C34','kor',5,2,'u5',14,'추론하며 읽기의 쓰임 — 추론하며 읽으면 글에 쓰인 것 너머까지 읽을 수 있고, 이 힘은 뉴스·광고·영상을 볼 때에도 필요하다',ARRAY['6국02-02 읽기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C35','kor',5,2,'u5',14,'ㅂ 소리가 덧나는 낱말 — 두 낱말이 어울릴 때 ㅂ 소리가 덧나면 소리 나는 대로 적는다 — 볍씨 · 햅쌀 · 멥쌀 · 좁쌀 (기초 다지기)',ARRAY['기초 다지기(소리가 덧나는 낱말)']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u5-C36','kor',5,2,'u5',14,'ㅎ 소리가 덧나는 낱말 — 두 낱말이 어울릴 때 ㅎ 소리가 덧나면 소리 나는 대로 적는다 — 수탉 · 암탉 · 머리카락 · 안팎 · 살코기 (기초 다지기)',ARRAY['기초 다지기(소리가 덧나는 낱말)']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X01','kor',5,'u5',ARRAY['K5-2-u5-C1']::text[],'글에 쓰여 있지 않은 내용은 알 수 없으니 짐작하면 안 된다고 여긴다','단서로 짐작해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X02','kor',5,'u5',ARRAY['K5-2-u5-C2']::text[],'추론을 글에 쓰인 문장을 그대로 찾아 옮기는 일로 여긴다','쓰여 있지 않은 것을 짐작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X03','kor',5,'u5',ARRAY['K5-2-u5-C3']::text[],'추론은 글을 읽을 때만 하는 일이라 생활과는 관계없다고 여긴다','생활 속에서도 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X04','kor',5,'u5',ARRAY['K5-2-u5-C4']::text[],'단원에서 배우는 차례를 섞거나 배울 내용과 하는 일을 엇갈리게 잇는다','방법 → 생각 → 표현 → 의도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X05','kor',5,'u5',ARRAY['K5-2-u5-C5']::text[],'글에 드러난 사실을 확인하지 않고 바로 짐작부터 하거나 쓰여 있지 않은 것을 쓰여 있다고 여긴다','사실부터 정확히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X06','kor',5,'u5',ARRAY['K5-2-u5-C6']::text[],'단서 하나만 보고 서둘러 짐작하거나 짐작과 관계없는 문장을 단서로 고른다','여러 단서를 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X07','kor',5,'u5',ARRAY['K5-2-u5-C7','K5-2-u5-C21']::text[],'내 경험이나 지식은 글 읽기와 관계없다고 여겨 떠올리지 않는다','아는 것을 떠올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X08','kor',5,'u5',ARRAY['K5-2-u5-C8']::text[],'짐작한 내용만 말하고 왜 그렇게 생각했는지 근거를 말하지 않는다','까닭을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X09','kor',5,'u5',ARRAY['K5-2-u5-C9']::text[],'추론을 아무렇게나 상상하는 일로 여겨 근거 없이 떠오르는 대로 지어낸다','근거가 있어야 추론') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X10','kor',5,'u5',ARRAY['K5-2-u5-C10']::text[],'추론에는 정답이 하나뿐이라 친구와 짐작이 다르면 한쪽은 반드시 틀렸다고 여긴다','근거가 있으면 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X11','kor',5,'u5',ARRAY['K5-2-u5-C11']::text[],'이야기를 간추릴 때 작은 일까지 모두 늘어놓거나 중요하지 않은 장면을 고른다','중요한 장면만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X12','kor',5,'u5',ARRAY['K5-2-u5-C12']::text[],'쓰인 사건만 읽고 사건 사이에 빠진 까닭이나 마음은 알 필요가 없다고 여긴다','빠진 까닭을 채워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X13','kor',5,'u5',ARRAY['K5-2-u5-C13']::text[],'글쓴이의 생각은 마지막 문장에 그대로 쓰여 있어 그 문장만 찾으면 된다고 여긴다','단서를 모아 짐작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X14','kor',5,'u5',ARRAY['K5-2-u5-C14']::text[],'글쓴이의 생각을 짐작할 때 제목이나 이야기 끝의 변화를 살피지 않고 작은 사실 하나로 정한다','말 · 행동 · 변화 · 제목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X15','kor',5,'u5',ARRAY['K5-2-u5-C15']::text[],'인물의 마음이나 분위기가 처음부터 끝까지 같다고 여겨 달라지는 모습을 놓친다','장면마다 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X16','kor',5,'u5',ARRAY['K5-2-u5-C16']::text[],'문단의 중심 내용을 찾을 때 예를 든 문장이나 가장 긴 문장을 중심 문장으로 고른다','중심 문장을 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X17','kor',5,'u5',ARRAY['K5-2-u5-C17']::text[],'함축된 표현을 사실과 다른 틀린 말이나 거짓말로 여긴다','숨은 뜻을 담은 표현') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X18','kor',5,'u5',ARRAY['K5-2-u5-C18']::text[],'함축된 표현을 사전에 나온 뜻 그대로만 읽는다','글에서의 뜻으로 넓혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X19','kor',5,'u5',ARRAY['K5-2-u5-C19']::text[],'사전 뜻으로 읽어 어색한 곳이 있어도 그냥 지나친다','어색하면 멈춰요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X20','kor',5,'u5',ARRAY['K5-2-u5-C20']::text[],'앞뒤 문장을 살피지 않고 그 낱말 하나만 보고 뜻을 정한다','앞뒤 단서를 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X21','kor',5,'u5',ARRAY['K5-2-u5-C21']::text[],'함축된 표현의 숨은 뜻을 짐작할 때 그 낱말에 대해 아는 것과 관계없는 경험을 떠올린다','뜻과 닿는 경험') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X22','kor',5,'u5',ARRAY['K5-2-u5-C22']::text[],'함축된 표현은 뜻을 어렵게 만들 뿐이라 쓸 까닭이 없다고 여긴다','생생하고 깊게 전해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X23','kor',5,'u5',ARRAY['K5-2-u5-C23']::text[],'이야기를 간추릴 때 사건의 차례를 뒤섞는다','일어난 차례대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X24','kor',5,'u5',ARRAY['K5-2-u5-C24']::text[],'글쓴이의 의도를 글의 소재(무엇에 대한 글인지)와 같은 것으로 여긴다','글을 쓴 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X25','kor',5,'u5',ARRAY['K5-2-u5-C25']::text[],'같은 말은 누가 어떤 상황에서 해도 뜻이 늘 같다고 여겨 겉뜻만 읽는다','누가 · 어떤 상황에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X26','kor',5,'u5',ARRAY['K5-2-u5-C26']::text[],'반대되는 말을 맞세운 표현을 앞뒤가 맞지 않는 틀린 문장으로 여긴다','맞세워 강조해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X27','kor',5,'u5',ARRAY['K5-2-u5-C27']::text[],'글쓴이의 의도를 짐작할 때 되풀이되는 장면이나 함축된 표현 같은 단서를 살피지 않는다','중심 내용 · 표현 · 반복') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X28','kor',5,'u5',ARRAY['K5-2-u5-C28']::text[],'글쓴이의 의도는 이야기 속 인물이 한 말과 똑같다고 여긴다','인물의 말 ≠ 의도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X29','kor',5,'u5',ARRAY['K5-2-u5-C29']::text[],'해석은 사람마다 다르니 글 속 근거와 맞지 않아도 모두 알맞다고 여긴다','근거에 맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X30','kor',5,'u5',ARRAY['K5-2-u5-C30']::text[],'감정은 「기뻐」, 「슬퍼」처럼 바로 말해야만 알아들을 수 있다고 여기거나 빗댄 표현의 감정을 잘못 짝짓는다','빗대면 더 깊어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X31','kor',5,'u5',ARRAY['K5-2-u5-C31']::text[],'감정 카드 뒷면에 감정 낱말을 그대로 쓰거나 앞면과 뒷면에 담을 것을 바꾼다','앞 그림 · 뒤 함축') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X32','kor',5,'u5',ARRAY['K5-2-u5-C32']::text[],'친구의 마음을 짐작한 뒤 확인하지 않고 내 짐작이 맞다고 우긴다','물어보고 들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X33','kor',5,'u5',ARRAY['K5-2-u5-C33']::text[],'친구의 마음을 짐작만 하고 공감하는 말 없이 지나치거나 표현을 놀린다','마음을 알아주는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X34','kor',5,'u5',ARRAY['K5-2-u5-C34']::text[],'추론하며 읽기는 국어 시간의 글에만 필요하고 뉴스·광고·영상과는 관계없다고 여긴다','어디에서나 필요해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X35','kor',5,'u5',ARRAY['K5-2-u5-C35']::text[],'ㅂ 소리가 덧나는 낱말을 원래 모양대로 「벼씨」, 「해쌀」, 「메쌀」, 「조쌀」로 적는다','볍씨 · 햅쌀 · 멥쌀 · 좁쌀') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u5-X36','kor',5,'u5',ARRAY['K5-2-u5-C36']::text[],'ㅎ 소리가 덧나는 낱말을 원래 모양대로 「수닭」, 「암닭」, 「머리가락」, 「안밖」, 「살고기」로 적는다','수탉 · 암탉 · 안팎') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_basic#1','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C2',1,'mc','auto','글에 드러나지 않은 내용을 글의 단서나 자신의 경험, 지식을 바탕으로 짐작하는 것을 무엇이라고 하나요?',ARRAY['K5-2-u5-X02']::text[],false,'{"seq":1,"concept":"K5-2-u5-C2","difficulty":1,"kind":"mc","stem":"글에 드러나지 않은 내용을 글의 단서나 자신의 경험, 지식을 바탕으로 짐작하는 것을 무엇이라고 하나요?","options":[{"t":"추론","correct":true},{"t":"요약","mis":"K5-2-u5-X02"},{"t":"낭독","mis":"K5-2-u5-X02"},{"t":"토의","mis":"K5-2-u5-X02"}],"explanation":["글을 간추리는 일이에요.","소리 내어 읽는 일이에요.","단서로 짐작하며 읽는 것이 추론이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_basic#2','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C1',1,'mc','auto','「대장간」 소개 글에 드러난 내용은 어느 것인가요?',ARRAY['K5-2-u5-X09']::text[],false,'{"seq":2,"concept":"K5-2-u5-C1","difficulty":1,"kind":"mc","stem":"「대장간」 소개 글에 드러난 내용은 어느 것인가요?","options":[{"t":"달군 쇠붙이를 집게로 잡고 망치로 두드린다","correct":true},{"t":"만든 물건을 장터에 내다 판다","mis":"K5-2-u5-X09"},{"t":"대장간 사람들은 모두 한 가족이다","mis":"K5-2-u5-X09"},{"t":"대장간은 아침에만 문을 연다","mis":"K5-2-u5-X09"}],"explanation":["글에 쓰여 있지 않아요.","글에 쓰여 있지 않아요.","글에 그대로 나온 내용을 찾아요."],"asset":{"type":"passage","lines":["김홍도의 그림 「대장간」에는 좁은 마당에 여러 사람이 모여 있어요.","한 사람은 벌겋게 달군 쇠붙이를 집게로 꽉 잡고 있어요.","다른 사람들은 커다란 망치를 번갈아 높이 들어 올려요.","「땅! 땅!」 망치가 쇠를 때리는 소리가 귀에 울리는 것 같아요.","한쪽에서는 낫처럼 휘어진 쇠붙이를 숫돌에 쓱쓱 문질러요."],"title":"그림 「대장간」을 소개하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_basic#3','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C1',1,'ox','auto','글에 쓰여 있지 않은 내용도 글의 단서를 바탕으로 짐작할 수 있어요.',ARRAY['K5-2-u5-X01']::text[],false,'{"seq":3,"concept":"K5-2-u5-C1","difficulty":1,"kind":"ox","stem":"글에 쓰여 있지 않은 내용도 글의 단서를 바탕으로 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"글의 단서와 내가 아는 것을 함께 생각하면 짐작할 수 있기 때문에","correct":true},{"t":"글에 쓰여 있지 않으면 알 길이 없기 때문에","mis":"K5-2-u5-X01"}],"mis":"K5-2-u5-X01","explanation":["쓰여 있지 않아도 짐작해요.","단서가 길을 알려 줘요.","이것이 추론이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_basic#4','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C3',1,'mc','auto','짝이 아무 말도 하지 않았는데 무슨 일이 있었는지 짐작하게 하는 단서는 어느 것인가요?',ARRAY['K5-2-u5-X06']::text[],false,'{"seq":4,"concept":"K5-2-u5-C3","difficulty":1,"kind":"mc","stem":"짝이 아무 말도 하지 않았는데 무슨 일이 있었는지 짐작하게 하는 단서는 어느 것인가요?","options":[{"t":"무릎에 묻은 흙과 바람 빠진 공","correct":true},{"t":"짝이 앉은 자리의 위치","mis":"K5-2-u5-X06"},{"t":"쉬는 시간이 끝났다는 것","mis":"K5-2-u5-X06"},{"t":"창밖이 보인다는 것","mis":"K5-2-u5-X06"}],"explanation":["일과 관계가 적어요.","누구에게나 같은 일이에요.","흙과 공이 무슨 일이 있었는지 알려 줘요."],"asset":{"type":"passage","lines":["쉬는 시간이 끝나고 짝이 교실로 돌아왔어요.","짝은 아무 말 없이 자리에 앉아 창밖만 바라봐요.","무릎에는 흙이 묻어 있어요.","손에는 바람 빠진 공을 꼭 쥐고 있어요."],"title":"말없이 돌아온 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_basic#5','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C2',2,'mc','auto','「대장간」 소개 글로 보아 대장간은 무엇을 하는 곳이라고 짐작할 수 있나요?',ARRAY['K5-2-u5-X09','K5-2-u5-X06']::text[],false,'{"seq":5,"concept":"K5-2-u5-C2","difficulty":2,"kind":"mc","stem":"「대장간」 소개 글로 보아 대장간은 무엇을 하는 곳이라고 짐작할 수 있나요?","options":[{"t":"쇠로 낫이나 호미 같은 연장을 만드는 곳","correct":true},{"t":"그림을 그려 파는 곳","mis":"K5-2-u5-X09"},{"t":"쌀을 찧어 가루로 만드는 곳","mis":"K5-2-u5-X06"},{"t":"글을 베껴 쓰는 곳","mis":"K5-2-u5-X09"}],"explanation":["글과 맞지 않아요.","쇠를 다루는 모습과 맞지 않아요.","쇠를 두드리고 가는 모습이 단서예요."],"asset":{"type":"passage","lines":["김홍도의 그림 「대장간」에는 좁은 마당에 여러 사람이 모여 있어요.","한 사람은 벌겋게 달군 쇠붙이를 집게로 꽉 잡고 있어요.","다른 사람들은 커다란 망치를 번갈아 높이 들어 올려요.","「땅! 땅!」 망치가 쇠를 때리는 소리가 귀에 울리는 것 같아요.","한쪽에서는 낫처럼 휘어진 쇠붙이를 숫돌에 쓱쓱 문질러요."],"title":"그림 「대장간」을 소개하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_basic#6','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C6',2,'mc','auto','대장간이 연장을 만드는 곳이라고 짐작하게 한 단서로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X06']::text[],false,'{"seq":6,"concept":"K5-2-u5-C6","difficulty":2,"kind":"mc","stem":"대장간이 연장을 만드는 곳이라고 짐작하게 한 단서로 알맞은 것은 어느 것인가요?","options":[{"t":"낫처럼 휘어진 쇠붙이를 숫돌에 간다","correct":true},{"t":"그림을 그린 사람은 김홍도이다","mis":"K5-2-u5-X06"},{"t":"좁은 마당에 여러 사람이 모여 있다","mis":"K5-2-u5-X06"},{"t":"글쓴이가 그림을 오래 보았다","mis":"K5-2-u5-X06"}],"explanation":["누가 그렸는지는 쓰임과 관계없어요.","모인 것만으로는 알기 어려워요.","낫 모양 쇠를 가는 모습이 단서예요."],"asset":{"type":"passage","lines":["김홍도의 그림 「대장간」에는 좁은 마당에 여러 사람이 모여 있어요.","한 사람은 벌겋게 달군 쇠붙이를 집게로 꽉 잡고 있어요.","다른 사람들은 커다란 망치를 번갈아 높이 들어 올려요.","「땅! 땅!」 망치가 쇠를 때리는 소리가 귀에 울리는 것 같아요.","한쪽에서는 낫처럼 휘어진 쇠붙이를 숫돌에 쓱쓱 문질러요."],"title":"그림 「대장간」을 소개하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_basic#7','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C4',2,'match','auto','이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u5-C4","difficulty":2,"kind":"match","stem":"이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.","pairs":[{"l":"추론하며 읽는 방법","r":"단서와 경험·지식으로 짐작하기"},{"l":"함축된 표현","r":"숨은 뜻을 찾아 읽기"},{"l":"글쓴이의 의도","r":"글을 쓴 까닭 짐작하기"}],"mis":"K5-2-u5-X04","explanation":["짐작하는 방법부터 익혀요.","숨은 뜻을 찾아요.","글을 쓴 까닭까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_basic#8','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C7',2,'mc','auto','「낫과 호미는 쇠로 만든 농기구예요.」라는 생각은 추론의 어떤 바탕에 해당하나요?',ARRAY['K5-2-u5-X05','K5-2-u5-X07']::text[],false,'{"seq":8,"concept":"K5-2-u5-C7","difficulty":2,"kind":"mc","stem":"「낫과 호미는 쇠로 만든 농기구예요.」라는 생각은 추론의 어떤 바탕에 해당하나요?","options":[{"t":"내가 알고 있는 지식","correct":true},{"t":"글에 쓰인 문장","mis":"K5-2-u5-X05"},{"t":"글쓴이의 이름","mis":"K5-2-u5-X07"},{"t":"그림의 제목","mis":"K5-2-u5-X07"}],"explanation":["글에 쓰여 있지 않아요.","이름은 바탕이 아니에요.","내가 아는 것도 추론의 바탕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_basic#9','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C9',2,'error','auto','짝의 마음을 짐작한 친구들의 말이에요. 추론이라고 하기 어려운 말은 어느 것인가요?',ARRAY['K5-2-u5-X09','K5-2-u5-X08']::text[],false,'{"seq":9,"concept":"K5-2-u5-C9","difficulty":2,"kind":"error","stem":"짝의 마음을 짐작한 친구들의 말이에요. 추론이라고 하기 어려운 말은 어느 것인가요?","options":[{"t":"「짝은 아마 외계인을 만났을 거야.」","correct":true,"mis_target":"K5-2-u5-X09"},{"t":"「흙이 묻은 걸 보니 공을 차다 넘어졌나 봐.」","mis":"K5-2-u5-X08"},{"t":"「공이 바람 빠진 걸 보니 놀이가 잘 안 됐나 봐.」","mis":"K5-2-u5-X08"}],"explanation":["흙이라는 단서가 있어요.","공이라는 단서가 있어요.","근거 없이 지어낸 말은 추론이 아니에요."],"asset":{"type":"passage","lines":["쉬는 시간이 끝나고 짝이 교실로 돌아왔어요.","짝은 아무 말 없이 자리에 앉아 창밖만 바라봐요.","무릎에는 흙이 묻어 있어요.","손에는 바람 빠진 공을 꼭 쥐고 있어요."],"title":"말없이 돌아온 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_basic#10','kor',5,2,'u5','L01','g5_2_kor_u5_L01_basic','lesson_basic','K5-2-u5-C8',3,'mc','auto','짝의 마음을 짐작해 말할 때 가장 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u5-X08','K5-2-u5-X09','K5-2-u5-X01']::text[],false,'{"seq":10,"concept":"K5-2-u5-C8","difficulty":3,"kind":"mc","stem":"짝의 마음을 짐작해 말할 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「바람 빠진 공을 쥐고 있는 걸 보니, 놀이가 뜻대로 안 돼 속상한 것 같아.」","correct":true},{"t":"「그냥 그런 느낌이 들어.」","mis":"K5-2-u5-X08"},{"t":"「짝은 원래 늘 화가 나 있어.」","mis":"K5-2-u5-X09"},{"t":"「말을 안 했으니 아무것도 알 수 없어.」","mis":"K5-2-u5-X01"}],"explanation":["근거가 없어요.","단서와 관계없는 말이에요.","단서를 들어 짐작했어요."],"asset":{"type":"passage","lines":["쉬는 시간이 끝나고 짝이 교실로 돌아왔어요.","짝은 아무 말 없이 자리에 앉아 창밖만 바라봐요.","무릎에는 흙이 묻어 있어요.","손에는 바람 빠진 공을 꼭 쥐고 있어요."],"title":"말없이 돌아온 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_challenge#1','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C9',2,'ox','auto','추론은 아무렇게나 상상하는 것이라 근거가 없어도 돼요.',ARRAY['K5-2-u5-X09']::text[],false,'{"seq":1,"concept":"K5-2-u5-C9","difficulty":2,"kind":"ox","stem":"추론은 아무렇게나 상상하는 것이라 근거가 없어도 돼요.","answer":"X","reason_options":[{"t":"추론은 글의 단서나 경험·지식이라는 근거를 바탕으로 짐작하는 것이기 때문에","correct":true},{"t":"짐작은 사람마다 마음대로 해도 되기 때문에","mis":"K5-2-u5-X09"}],"mis":"K5-2-u5-X09","explanation":["근거가 있어야 해요.","마음대로 지어내는 것이 아니에요.","단서와 경험·지식이 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_challenge#2','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C3',2,'mc','auto','생활 속에서 추론한 예로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X02','K5-2-u5-X03']::text[],false,'{"seq":2,"concept":"K5-2-u5-C3","difficulty":2,"kind":"mc","stem":"생활 속에서 추론한 예로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"먹구름이 몰려오는 것을 보고 우산을 챙겼다","correct":true},{"t":"달력을 보고 오늘 날짜를 읽었다","mis":"K5-2-u5-X02"},{"t":"시간표에 적힌 과목을 그대로 읽었다","mis":"K5-2-u5-X02"},{"t":"추론은 글 읽을 때만 하므로 생활 속 예는 없다","mis":"K5-2-u5-X03"}],"explanation":["쓰인 것을 그대로 읽었어요.","쓰인 것을 그대로 읽었어요.","먹구름을 단서로 비를 짐작했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_challenge#3','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C10',3,'mc','auto','두 친구의 짐작을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u5-X10','K5-2-u5-X09','K5-2-u5-X01']::text[],false,'{"seq":3,"concept":"K5-2-u5-C10","difficulty":3,"kind":"mc","stem":"두 친구의 짐작을 바르게 말한 것은 어느 것인가요?","options":[{"t":"짐작은 하나가 아닐 수 있지만 어떤 단서를 근거로 했는지 말해야 한다","correct":true},{"t":"둘 가운데 하나는 반드시 틀렸다","mis":"K5-2-u5-X10"},{"t":"근거 없이 말해도 둘 다 맞다","mis":"K5-2-u5-X09"},{"t":"글에 쓰여 있지 않으니 둘 다 말하면 안 된다","mis":"K5-2-u5-X01"}],"explanation":["정답이 하나뿐인 것은 아니에요.","근거는 꼭 있어야 해요.","두 친구 모두 단서를 들었어요."],"asset":{"type":"speech","turns":[{"who":"예린","text":"대장간은 칼을 만드는 곳이야. 쇠를 두드려 날을 세우잖아."},{"who":"도윤","text":"대장간은 농기구를 만드는 곳이야. 낫처럼 휘어진 쇠를 갈고 있잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_challenge#4','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C2',3,'mc','auto','추론에 대한 설명으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X02','K5-2-u5-X09','K5-2-u5-X01']::text[],false,'{"seq":4,"concept":"K5-2-u5-C2","difficulty":3,"kind":"mc","stem":"추론에 대한 설명으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"글의 단서와 내 경험·지식을 함께 써서 쓰여 있지 않은 내용을 짐작하는 것","correct":true},{"t":"글에 쓰인 문장을 그대로 옮겨 적는 것","mis":"K5-2-u5-X02"},{"t":"글과 관계없이 떠오르는 대로 이야기를 지어내는 것","mis":"K5-2-u5-X09"},{"t":"글에 쓰여 있지 않은 내용은 모른다고 하는 것","mis":"K5-2-u5-X01"}],"explanation":["옮겨 적기는 추론이 아니에요.","근거 없는 상상이에요.","단서와 경험·지식으로 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_challenge#5','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C4',3,'mc','auto','이 단원에서 배우는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X04']::text[],false,'{"seq":5,"concept":"K5-2-u5-C4","difficulty":3,"kind":"mc","stem":"이 단원에서 배우는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"추론하며 읽는 방법 → 글쓴이의 생각 → 함축된 표현 → 글쓴이의 의도","correct":true},{"t":"글쓴이의 의도 → 함축된 표현 → 추론하며 읽는 방법 → 글쓴이의 생각","mis":"K5-2-u5-X04"},{"t":"함축된 표현 → 글쓴이의 의도 → 글쓴이의 생각 → 추론하며 읽는 방법","mis":"K5-2-u5-X04"},{"t":"글쓴이의 생각 → 추론하며 읽는 방법 → 글쓴이의 의도 → 함축된 표현","mis":"K5-2-u5-X04"}],"explanation":["의도는 나중이에요.","방법을 먼저 익혀요.","방법부터 익혀 의도까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_challenge#6','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C6',3,'error','auto','「대장간」 소개 글에서 친구들이 찾은 단서예요. 연장을 만드는 곳이라는 짐작의 단서로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u5-X06','K5-2-u5-X07']::text[],false,'{"seq":6,"concept":"K5-2-u5-C6","difficulty":3,"kind":"error","stem":"「대장간」 소개 글에서 친구들이 찾은 단서예요. 연장을 만드는 곳이라는 짐작의 단서로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「그림을 그린 사람은 김홍도이다.」","correct":true,"mis_target":"K5-2-u5-X06"},{"t":"「달군 쇠붙이를 망치로 두드린다.」","mis":"K5-2-u5-X07"},{"t":"「낫처럼 휘어진 쇠붙이를 숫돌에 간다.」","mis":"K5-2-u5-X07"}],"explanation":["쇠를 다루는 단서예요.","연장 모양의 단서예요.","그린 사람은 대장간의 쓰임과 관계없어요."],"asset":{"type":"passage","lines":["김홍도의 그림 「대장간」에는 좁은 마당에 여러 사람이 모여 있어요.","한 사람은 벌겋게 달군 쇠붙이를 집게로 꽉 잡고 있어요.","다른 사람들은 커다란 망치를 번갈아 높이 들어 올려요.","「땅! 땅!」 망치가 쇠를 때리는 소리가 귀에 울리는 것 같아요.","한쪽에서는 낫처럼 휘어진 쇠붙이를 숫돌에 쓱쓱 문질러요."],"title":"그림 「대장간」을 소개하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_challenge#7','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C7',3,'mc','auto','대장간 사람들이 쇠를 달구어 두드리는 까닭을 짐작할 때 도움이 되는 지식은 어느 것인가요?',ARRAY['K5-2-u5-X07']::text[],false,'{"seq":7,"concept":"K5-2-u5-C7","difficulty":3,"kind":"mc","stem":"대장간 사람들이 쇠를 달구어 두드리는 까닭을 짐작할 때 도움이 되는 지식은 어느 것인가요?","options":[{"t":"쇠는 뜨겁게 달구면 물러져 모양을 바꾸기 쉽다","correct":true},{"t":"쇠는 물에 넣으면 녹아 없어진다","mis":"K5-2-u5-X07"},{"t":"쇠는 차가울수록 잘 휘어진다","mis":"K5-2-u5-X07"},{"t":"쇠는 망치로 두드리면 가벼워진다","mis":"K5-2-u5-X07"}],"explanation":["바른 지식이 아니에요.","바른 지식이 아니에요.","바른 지식이 추론을 돕습니다."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_challenge#8','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C2',4,'essay','teacher','「대장간」 소개 글을 읽고 대장간이 무엇을 하는 곳인지 짐작해 쓰고, 그렇게 짐작한 단서와 내가 아는 것을 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u5-C2","difficulty":4,"kind":"essay","stem":"「대장간」 소개 글을 읽고 대장간이 무엇을 하는 곳인지 짐작해 쓰고, 그렇게 짐작한 단서와 내가 아는 것을 함께 쓰세요.","answer_guide":{"answer":"예: 대장간은 쇠로 낫이나 호미 같은 연장을 만드는 곳이다. 글에서 달군 쇠를 망치로 두드리고 낫처럼 휘어진 쇠를 숫돌에 간다는 단서를 찾았고, 낫과 호미가 쇠로 만든 농기구라는 것을 알고 있어서 그렇게 짐작했다.","scoring_points":["대장간의 쓰임을 짐작했는가","글의 단서를 썼는가","내가 아는 것을 함께 썼는가"]},"explanation":["짐작을 써요.","단서를 찾아요.","아는 것을 더해요."],"asset":{"type":"passage","lines":["김홍도의 그림 「대장간」에는 좁은 마당에 여러 사람이 모여 있어요.","한 사람은 벌겋게 달군 쇠붙이를 집게로 꽉 잡고 있어요.","다른 사람들은 커다란 망치를 번갈아 높이 들어 올려요.","「땅! 땅!」 망치가 쇠를 때리는 소리가 귀에 울리는 것 같아요.","한쪽에서는 낫처럼 휘어진 쇠붙이를 숫돌에 쓱쓱 문질러요."],"title":"그림 「대장간」을 소개하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_challenge#9','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C3',4,'essay','teacher','말하지 않아도 다른 사람의 마음이나 상황을 짐작한 경험을 하나 쓰고, 무엇을 단서로 짐작했는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u5-C3","difficulty":4,"kind":"essay","stem":"말하지 않아도 다른 사람의 마음이나 상황을 짐작한 경험을 하나 쓰고, 무엇을 단서로 짐작했는지 쓰세요.","answer_guide":{"answer":"예: 엄마가 퇴근하고 들어와 말없이 소파에 기대 눈을 감았다. 가방을 아무렇게나 내려놓고 어깨를 주무르는 모습을 단서로 오늘 일이 많아 무척 피곤하다고 짐작했다. 그래서 물 한 잔을 가져다드렸다.","scoring_points":["경험을 구체적으로 썼는가","단서를 썼는가","짐작한 마음이나 상황을 썼는가"]},"explanation":["경험을 떠올려요.","단서를 찾아요.","짐작을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L01_challenge#10','kor',5,2,'u5','L01','g5_2_kor_u5_L01_challenge','lesson_challenge','K5-2-u5-C8',4,'essay','teacher','「말없이 돌아온 짝」을 보고 짝에게 무슨 일이 있었는지 짐작해 쓰고, 「~을 보니 ~인 것 같다」 꼴로 근거를 밝혀 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u5-C8","difficulty":4,"kind":"essay","stem":"「말없이 돌아온 짝」을 보고 짝에게 무슨 일이 있었는지 짐작해 쓰고, 「~을 보니 ~인 것 같다」 꼴로 근거를 밝혀 쓰세요.","answer_guide":{"answer":"예: 무릎에 흙이 묻은 것을 보니 운동장에서 공을 차다 넘어진 것 같다. 바람 빠진 공을 꼭 쥐고 창밖만 보는 것을 보니 공이 망가져 놀이를 못 해서 속상한 것 같다.","scoring_points":["일어난 일을 짐작했는가","단서를 근거로 밝혔는가","정해진 꼴로 썼는가"]},"explanation":["짐작해요.","근거를 밝혀요.","꼴을 지켜요."],"asset":{"type":"passage","lines":["쉬는 시간이 끝나고 짝이 교실로 돌아왔어요.","짝은 아무 말 없이 자리에 앉아 창밖만 바라봐요.","무릎에는 흙이 묻어 있어요.","손에는 바람 빠진 공을 꼭 쥐고 있어요."],"title":"말없이 돌아온 짝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_basic#1','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C5',1,'mc','auto','로버트 훅은 현미경으로 본 것을 어떻게 했나요?',ARRAY['K5-2-u5-X05']::text[],false,'{"seq":1,"concept":"K5-2-u5-C5","difficulty":1,"kind":"mc","stem":"로버트 훅은 현미경으로 본 것을 어떻게 했나요?","options":[{"t":"커다란 그림으로 그려 책으로 펴냈다","correct":true},{"t":"편지로 써서 보냈다","mis":"K5-2-u5-X05"},{"t":"사진으로 찍어 걸었다","mis":"K5-2-u5-X05"},{"t":"아무에게도 보여 주지 않았다","mis":"K5-2-u5-X05"}],"explanation":["레이우엔훅이 한 일이에요.","글에 없어요.","그림을 그려 책으로 펴냈어요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_basic#2','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C5',1,'mc','auto','레이우엔훅이 현미경으로 들여다본 것은 무엇인가요?',ARRAY['K5-2-u5-X05']::text[],false,'{"seq":2,"concept":"K5-2-u5-C5","difficulty":1,"kind":"mc","stem":"레이우엔훅이 현미경으로 들여다본 것은 무엇인가요?","options":[{"t":"빗물 한 방울","correct":true},{"t":"벼룩","mis":"K5-2-u5-X05"},{"t":"깨알","mis":"K5-2-u5-X05"},{"t":"옷감","mis":"K5-2-u5-X05"}],"explanation":["로버트 훅이 그린 것이에요.","견주는 말로만 나와요.","빗물 한 방울을 들여다보았어요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_basic#3','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C6',1,'mc','auto','글에 드러나지 않은 내용을 짐작할 때 글에서 찾는 실마리를 무엇이라고 하나요?',ARRAY['K5-2-u5-X06']::text[],false,'{"seq":3,"concept":"K5-2-u5-C6","difficulty":1,"kind":"mc","stem":"글에 드러나지 않은 내용을 짐작할 때 글에서 찾는 실마리를 무엇이라고 하나요?","options":[{"t":"단서","correct":true},{"t":"제목","mis":"K5-2-u5-X06"},{"t":"차례","mis":"K5-2-u5-X06"},{"t":"쪽수","mis":"K5-2-u5-X06"}],"explanation":["제목도 단서가 될 수 있지만 실마리 모두를 가리키지는 않아요.","실마리가 아니에요.","짐작의 실마리를 단서라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_basic#4','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C8',1,'ox','auto','추론한 내용을 말할 때는 왜 그렇게 생각했는지 근거를 함께 말해야 해요.',ARRAY['K5-2-u5-X08']::text[],false,'{"seq":4,"concept":"K5-2-u5-C8","difficulty":1,"kind":"ox","stem":"추론한 내용을 말할 때는 왜 그렇게 생각했는지 근거를 함께 말해야 해요.","answer":"O","reason_options":[{"t":"근거가 있어야 짐작을 서로 견주어 보고 믿을 수 있기 때문에","correct":true},{"t":"짐작만 말해도 누구나 바로 알아듣기 때문에","mis":"K5-2-u5-X08"}],"mis":"K5-2-u5-X08","explanation":["근거가 필요해요.","짐작만으로는 견줄 수 없어요.","근거와 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_basic#5','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C6',2,'mc','auto','「로버트 훅의 현미경으로 무엇을 할 수 있게 되었나요?」에 대한 알맞은 짐작은 어느 것인가요?',ARRAY['K5-2-u5-X09','K5-2-u5-X01']::text[],false,'{"seq":5,"concept":"K5-2-u5-C6","difficulty":2,"kind":"mc","stem":"「로버트 훅의 현미경으로 무엇을 할 수 있게 되었나요?」에 대한 알맞은 짐작은 어느 것인가요?","options":[{"t":"작은 생물을 크고 자세하게 볼 수 있게 되었다","correct":true},{"t":"먼 별을 가까이 볼 수 있게 되었다","mis":"K5-2-u5-X09"},{"t":"벼룩을 크게 기를 수 있게 되었다","mis":"K5-2-u5-X09"},{"t":"글에 쓰여 있지 않아 알 수 없다","mis":"K5-2-u5-X01"}],"explanation":["글과 관계없어요.","그림이 컸을 뿐이에요.","벼룩 그림의 털과 마디가 단서예요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_basic#6','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C7',2,'mc','auto','레이우엔훅이 물방울 속에서 본 것이 「미생물」이라고 짐작할 때 바탕이 된 것은 어느 것인가요?',ARRAY['K5-2-u5-X05','K5-2-u5-X06','K5-2-u5-X09']::text[],false,'{"seq":6,"concept":"K5-2-u5-C7","difficulty":2,"kind":"mc","stem":"레이우엔훅이 물방울 속에서 본 것이 「미생물」이라고 짐작할 때 바탕이 된 것은 어느 것인가요?","options":[{"t":"과학 시간에 배운 지식","correct":true},{"t":"글에 쓰인 「미생물」이라는 낱말","mis":"K5-2-u5-X05"},{"t":"글쓴이가 붙인 제목","mis":"K5-2-u5-X06"},{"t":"아무 근거 없는 느낌","mis":"K5-2-u5-X09"}],"explanation":["글에는 그 낱말이 없어요.","제목만으로는 알 수 없어요.","배운 지식이 바탕이에요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_basic#7','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C7',2,'match','auto','추론한 말과 추론의 바탕을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u5-C7","difficulty":2,"kind":"match","stem":"추론한 말과 추론의 바탕을 알맞게 이으세요.","pairs":[{"l":"「벼룩의 털과 마디가 보였다니 작은 것을 크게 보여 주었을 거야.」","r":"글에서 찾은 단서"},{"l":"「물속 작은 생물을 배운 적이 있어서 미생물이라고 생각해.」","r":"내가 알고 있는 지식"},{"l":"「맑은 물을 마시고 배탈이 난 적이 있어서 무언가 살았을 거야.」","r":"내가 겪은 경험"}],"mis":"K5-2-u5-X07","explanation":["글 속 문장에서 출발했어요.","배운 것에서 출발했어요.","겪은 일에서 출발했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_basic#8','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C9',2,'error','auto','「현미경이 열어 준 작은 세상」을 읽고 짐작한 말이에요. 근거가 없어 추론이라고 하기 어려운 말은 어느 것인가요?',ARRAY['K5-2-u5-X09','K5-2-u5-X06','K5-2-u5-X07']::text[],false,'{"seq":8,"concept":"K5-2-u5-C9","difficulty":2,"kind":"error","stem":"「현미경이 열어 준 작은 세상」을 읽고 짐작한 말이에요. 근거가 없어 추론이라고 하기 어려운 말은 어느 것인가요?","options":[{"t":"「레이우엔훅은 빗물 속에서 물고기를 보았을 거야.」","correct":true,"mis_target":"K5-2-u5-X09"},{"t":"「물방울 속 생명체는 맨눈으로 보이지 않을 만큼 작았을 거야.」","mis":"K5-2-u5-X06"},{"t":"「사람들이 믿지 않은 까닭은 처음 듣는 이야기였기 때문일 거야.」","mis":"K5-2-u5-X07"}],"explanation":["현미경으로 보았다는 단서가 있어요.","경험·지식으로 짐작했어요.","물방울 속 물고기는 근거가 없어요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_basic#9','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C5',2,'mc','auto','추론하기 전에 먼저 해야 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X05','K5-2-u5-X08','K5-2-u5-X09']::text[],false,'{"seq":9,"concept":"K5-2-u5-C5","difficulty":2,"kind":"mc","stem":"추론하기 전에 먼저 해야 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"글에 드러난 사실을 정확하게 파악한다","correct":true},{"t":"글을 읽지 않고 제목만 보고 짐작한다","mis":"K5-2-u5-X05"},{"t":"친구의 짐작을 그대로 따라 쓴다","mis":"K5-2-u5-X08"},{"t":"떠오르는 대로 이야기를 지어낸다","mis":"K5-2-u5-X09"}],"explanation":["글부터 읽어요.","내 근거가 필요해요.","사실을 알아야 짐작할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_basic#10','kor',5,2,'u5','L02','g5_2_kor_u5_L02_basic','lesson_basic','K5-2-u5-C6',3,'mc','auto','「처음에는 믿는 사람이 거의 없었어요.」를 단서로 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X09','K5-2-u5-X06']::text[],false,'{"seq":10,"concept":"K5-2-u5-C6","difficulty":3,"kind":"mc","stem":"「처음에는 믿는 사람이 거의 없었어요.」를 단서로 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그때 사람들은 물방울 속에 생명체가 있다는 생각을 해 본 적이 없었다","correct":true},{"t":"레이우엔훅은 거짓말을 자주 했다","mis":"K5-2-u5-X09"},{"t":"편지가 중간에 없어졌다","mis":"K5-2-u5-X09"},{"t":"현미경은 그때 이미 집집마다 있었다","mis":"K5-2-u5-X06"}],"explanation":["근거가 없어요.","근거가 없어요.","처음 듣는 이야기라 믿기 어려웠을 거예요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_challenge#1','kor',5,2,'u5','L02','g5_2_kor_u5_L02_challenge','lesson_challenge','K5-2-u5-C10',2,'ox','auto','같은 글을 읽고 친구와 짐작이 다르면 둘 중 하나는 반드시 틀린 거예요.',ARRAY['K5-2-u5-X10']::text[],false,'{"seq":1,"concept":"K5-2-u5-C10","difficulty":2,"kind":"ox","stem":"같은 글을 읽고 친구와 짐작이 다르면 둘 중 하나는 반드시 틀린 거예요.","answer":"X","reason_options":[{"t":"근거가 있다면 짐작이 달라도 서로 견주어 볼 수 있기 때문에","correct":true},{"t":"추론에는 언제나 하나의 정답만 있기 때문에","mis":"K5-2-u5-X10"}],"mis":"K5-2-u5-X10","explanation":["달라도 괜찮아요.","근거로 견줘요.","정답보다 과정이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_challenge#2','kor',5,2,'u5','L02','g5_2_kor_u5_L02_challenge','lesson_challenge','K5-2-u5-C8',2,'mc','auto','추론한 내용을 근거와 함께 말한 것은 어느 것인가요?',ARRAY['K5-2-u5-X08','K5-2-u5-X01','K5-2-u5-X09']::text[],false,'{"seq":2,"concept":"K5-2-u5-C8","difficulty":2,"kind":"mc","stem":"추론한 내용을 근거와 함께 말한 것은 어느 것인가요?","options":[{"t":"「벼룩보다 훨씬 작은 생명체를 보았다는 단서로 보아, 레이우엔훅의 현미경이 더 정밀했을 거야.」","correct":true},{"t":"「레이우엔훅의 현미경이 더 좋았을 거야. 그냥 그래.」","mis":"K5-2-u5-X08"},{"t":"「글에 쓰여 있지 않으니 아무 말도 하면 안 돼.」","mis":"K5-2-u5-X01"},{"t":"「로버트 훅이 더 유명하니 그의 현미경이 더 좋았을 거야.」","mis":"K5-2-u5-X09"}],"explanation":["근거가 빠졌어요.","단서로 짐작할 수 있어요.","단서를 근거로 들었어요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_challenge#3','kor',5,2,'u5','L02','g5_2_kor_u5_L02_challenge','lesson_challenge','K5-2-u5-C10',3,'mc','auto','두 친구의 말을 바르게 견준 것은 어느 것인가요?',ARRAY['K5-2-u5-X01','K5-2-u5-X08','K5-2-u5-X10']::text[],false,'{"seq":3,"concept":"K5-2-u5-C10","difficulty":3,"kind":"mc","stem":"두 친구의 말을 바르게 견준 것은 어느 것인가요?","options":[{"t":"글에 직접 쓰여 있지 않아도 단서와 지식을 합치면 짐작할 수 있고, 근거를 함께 말해야 한다","correct":true},{"t":"글에 쓰여 있지 않으면 짐작해서는 안 된다","mis":"K5-2-u5-X01"},{"t":"근거가 없어도 먼저 말한 짐작이 맞다","mis":"K5-2-u5-X08"},{"t":"둘의 생각이 다르니 이 글은 읽을 필요가 없다","mis":"K5-2-u5-X10"}],"explanation":["단서로 짐작할 수 있어요.","근거가 필요해요.","다른 짐작은 견주어 볼 재료예요."],"asset":{"type":"speech","turns":[{"who":"시후","text":"레이우엔훅의 현미경이 로버트 훅의 현미경보다 더 정밀했을 거야."},{"who":"나연","text":"글에 그렇게 쓰여 있지 않으니 알 수 없어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_challenge#4','kor',5,2,'u5','L02','g5_2_kor_u5_L02_challenge','lesson_challenge','K5-2-u5-C7',3,'mc','auto','글에 「미생물」이라는 말이 없는데도 미생물이라고 짐작할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X05','K5-2-u5-X08','K5-2-u5-X09']::text[],false,'{"seq":4,"concept":"K5-2-u5-C7","difficulty":3,"kind":"mc","stem":"글에 「미생물」이라는 말이 없는데도 미생물이라고 짐작할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"글의 단서에 내가 배운 지식을 더해 생각했기 때문에","correct":true},{"t":"글에 그 말이 쓰여 있기 때문에","mis":"K5-2-u5-X05"},{"t":"친구가 그렇게 말했기 때문에","mis":"K5-2-u5-X08"},{"t":"아무렇게나 떠올렸기 때문에","mis":"K5-2-u5-X09"}],"explanation":["글에는 없어요.","내 근거가 있어야 해요.","단서와 지식을 함께 썼어요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_challenge#5','kor',5,2,'u5','L02','g5_2_kor_u5_L02_challenge','lesson_challenge','K5-2-u5-C5',3,'error','auto','「현미경이 열어 준 작은 세상」에 드러난 사실을 정리한 것이에요. 글에 드러난 사실이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u5-X05','K5-2-u5-X06']::text[],false,'{"seq":5,"concept":"K5-2-u5-C5","difficulty":3,"kind":"error","stem":"「현미경이 열어 준 작은 세상」에 드러난 사실을 정리한 것이에요. 글에 드러난 사실이 아닌 것은 어느 것인가요?","options":[{"t":"「로버트 훅과 레이우엔훅은 함께 현미경을 만들었다.」","correct":true,"mis_target":"K5-2-u5-X05"},{"t":"「로버트 훅은 본 것을 그림으로 그려 책으로 펴냈다.」","mis":"K5-2-u5-X06"},{"t":"「레이우엔훅은 빗물 한 방울을 들여다보았다.」","mis":"K5-2-u5-X06"}],"explanation":["글에 나와요.","글에 나와요.","두 사람은 따로 현미경을 만들었어요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_challenge#6','kor',5,2,'u5','L02','g5_2_kor_u5_L02_challenge','lesson_challenge','K5-2-u5-C9',3,'mc','auto','추론과 아무렇게나 상상하기의 다른 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X09','K5-2-u5-X10']::text[],false,'{"seq":6,"concept":"K5-2-u5-C9","difficulty":3,"kind":"mc","stem":"추론과 아무렇게나 상상하기의 다른 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"추론은 왜 그렇게 생각했는지 단서나 경험·지식을 근거로 말할 수 있다","correct":true},{"t":"추론은 글자 수가 더 많다","mis":"K5-2-u5-X09"},{"t":"상상은 맞고 추론은 틀리다","mis":"K5-2-u5-X10"},{"t":"둘은 다른 점이 없다","mis":"K5-2-u5-X09"}],"explanation":["길이와 관계없어요.","맞고 틀림의 문제가 아니에요.","근거가 있는지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_challenge#7','kor',5,2,'u5','L02','g5_2_kor_u5_L02_challenge','lesson_challenge','K5-2-u5-C6',3,'mc','auto','단서 하나만 보고 서둘러 짐작하지 않으려면 어떻게 해야 하나요?',ARRAY['K5-2-u5-X06','K5-2-u5-X08']::text[],false,'{"seq":7,"concept":"K5-2-u5-C6","difficulty":3,"kind":"mc","stem":"단서 하나만 보고 서둘러 짐작하지 않으려면 어떻게 해야 하나요?","options":[{"t":"여러 단서를 함께 놓고 짐작이 모든 단서와 맞는지 살핀다","correct":true},{"t":"처음 떠오른 짐작을 끝까지 고집한다","mis":"K5-2-u5-X06"},{"t":"단서는 하나만 찾으면 충분하다","mis":"K5-2-u5-X06"},{"t":"단서 없이 친구의 짐작을 따른다","mis":"K5-2-u5-X08"}],"explanation":["고칠 수 있어요.","여럿을 함께 봐요.","단서끼리 맞는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_challenge#8','kor',5,2,'u5','L02','g5_2_kor_u5_L02_challenge','lesson_challenge','K5-2-u5-C6',4,'essay','teacher','「현미경이 열어 준 작은 세상」에서 단서 두 개를 찾아 쓰고, 그 단서를 함께 생각해 짐작한 내용을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u5-C6","difficulty":4,"kind":"essay","stem":"「현미경이 열어 준 작은 세상」에서 단서 두 개를 찾아 쓰고, 그 단서를 함께 생각해 짐작한 내용을 쓰세요.","answer_guide":{"answer":"예: 「벼룩 그림에 털과 마디가 많다는 것에 놀랐다」와 「물방울 속에서 아주 작은 생명체들이 헤엄쳤다」를 함께 생각하면, 현미경은 맨눈으로 볼 수 없던 작은 것들을 크고 자세하게 보여 주어 사람들에게 새로운 세상을 알려 주었다고 짐작할 수 있다.","scoring_points":["단서 두 개를 찾았는가","두 단서를 함께 생각했는가","짐작한 내용을 썼는가"]},"explanation":["단서 둘을 찾아요.","함께 생각해요.","짐작을 써요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_challenge#9','kor',5,2,'u5','L02','g5_2_kor_u5_L02_challenge','lesson_challenge','K5-2-u5-C7',4,'essay','teacher','레이우엔훅의 이야기를 들은 사람들이 처음에 믿지 않은 까닭을 내 경험이나 지식을 바탕으로 짐작해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u5-C7","difficulty":4,"kind":"essay","stem":"레이우엔훅의 이야기를 들은 사람들이 처음에 믿지 않은 까닭을 내 경험이나 지식을 바탕으로 짐작해 쓰세요.","answer_guide":{"answer":"예: 맨눈으로는 물방울 속에 아무것도 보이지 않으니, 직접 보지 못한 사람들은 그런 생명체가 있다는 말을 믿기 어려웠을 것이다. 나도 동생이 처음 보는 곤충 이야기를 할 때 직접 보기 전까지는 믿지 않은 적이 있다.","scoring_points":["믿지 않은 까닭을 짐작했는가","경험이나 지식을 썼는가","글의 내용과 이어 썼는가"]},"explanation":["까닭을 짐작해요.","경험이나 지식을 써요.","글과 이어요."],"asset":{"type":"passage","lines":["아주 오래전, 영국의 과학자 로버트 훅은 직접 만든 현미경으로","작은 생물을 들여다보고, 본 것을 커다란 그림으로 그려 책으로 펴냈어요.","책에 실린 벼룩 그림은 접힌 종이를 펼쳐야 다 보일 만큼 컸어요.","사람들은 깨알보다 작은 벌레에 털과 마디가 많다는 것에 놀랐어요.","몇 해 뒤, 네덜란드의 옷감 상인 레이우엔훅도 손수 현미경을 만들었어요.","그는 빗물 한 방울을 들여다보다가 눈을 떼지 못했어요.","맑아 보이던 물방울 속에서 아주 작은 생명체들이 바쁘게 헤엄쳤거든요.","그가 본 것을 편지로 알렸지만, 처음에는 믿는 사람이 거의 없었어요."],"title":"현미경이 열어 준 작은 세상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L02_challenge#10','kor',5,2,'u5','L02','g5_2_kor_u5_L02_challenge','lesson_challenge','K5-2-u5-C10',4,'essay','teacher','추론하며 읽을 때 정답을 맞히는 것보다 짐작하는 과정이 중요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u5-C10","difficulty":4,"kind":"essay","stem":"추론하며 읽을 때 정답을 맞히는 것보다 짐작하는 과정이 중요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 추론은 글에 쓰여 있지 않은 내용을 짐작하는 것이라 사람마다 짐작이 다를 수 있다. 어떤 단서와 경험·지식으로 생각했는지 과정을 말하면 친구와 견주어 보며 더 깊이 읽을 수 있고, 짐작이 틀렸을 때 어디서 달라졌는지도 알 수 있다.","scoring_points":["짐작이 다를 수 있음을 썼는가","과정을 말하면 좋은 점을 썼는가","까닭이 분명한가"]},"explanation":["짐작은 여럿일 수 있어요.","과정을 나눠요.","까닭을 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_basic#1','kor',5,2,'u5','L04','g5_2_kor_u5_L04_basic','lesson_basic','K5-2-u5-C11',1,'mc','auto','이야기를 간추릴 때 알맞은 방법은 어느 것인가요?',ARRAY['K5-2-u5-X11']::text[],false,'{"seq":1,"concept":"K5-2-u5-C11","difficulty":1,"kind":"mc","stem":"이야기를 간추릴 때 알맞은 방법은 어느 것인가요?","options":[{"t":"중요한 장면만 골라 장면마다 한 문장으로 쓴다","correct":true},{"t":"일어난 일을 하나도 빠짐없이 모두 쓴다","mis":"K5-2-u5-X11"},{"t":"마음에 드는 장면 하나만 길게 쓴다","mis":"K5-2-u5-X11"},{"t":"인물 이름만 차례대로 쓴다","mis":"K5-2-u5-X11"}],"explanation":["너무 길어져요.","뼈대가 보이지 않아요.","중요한 장면을 한 문장씩 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_basic#2','kor',5,2,'u5','L04','g5_2_kor_u5_L04_basic','lesson_basic','K5-2-u5-C12',1,'mc','auto','시간 통장에서 한 칸을 더하는 때는 언제인가요?',ARRAY['K5-2-u5-X05']::text[],false,'{"seq":2,"concept":"K5-2-u5-C12","difficulty":1,"kind":"mc","stem":"시간 통장에서 한 칸을 더하는 때는 언제인가요?","options":[{"t":"남을 위해 한 시간 일했을 때","correct":true},{"t":"도움을 한 시간 받았을 때","mis":"K5-2-u5-X05"},{"t":"빵을 사 먹었을 때","mis":"K5-2-u5-X05"},{"t":"이사를 떠날 때","mis":"K5-2-u5-X05"}],"explanation":["그때는 한 칸을 빼요.","글에 없어요.","남을 위해 일하면 한 칸 더해요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_basic#3','kor',5,2,'u5','L04','g5_2_kor_u5_L04_basic','lesson_basic','K5-2-u5-C13',1,'mc','auto','글을 통해 글쓴이가 독자에게 전하려는 생각을 무엇이라고 하나요?',ARRAY['K5-2-u5-X14','K5-2-u5-X13']::text[],false,'{"seq":3,"concept":"K5-2-u5-C13","difficulty":1,"kind":"mc","stem":"글을 통해 글쓴이가 독자에게 전하려는 생각을 무엇이라고 하나요?","options":[{"t":"글쓴이의 생각","correct":true},{"t":"글의 제목","mis":"K5-2-u5-X14"},{"t":"등장인물","mis":"K5-2-u5-X14"},{"t":"글의 길이","mis":"K5-2-u5-X13"}],"explanation":["제목은 단서일 뿐이에요.","이야기 속 사람이에요.","전하려는 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_basic#4','kor',5,2,'u5','L04','g5_2_kor_u5_L04_basic','lesson_basic','K5-2-u5-C13',1,'ox','auto','글쓴이의 생각은 언제나 글의 마지막 문장에 그대로 쓰여 있어요.',ARRAY['K5-2-u5-X13']::text[],false,'{"seq":4,"concept":"K5-2-u5-C13","difficulty":1,"kind":"ox","stem":"글쓴이의 생각은 언제나 글의 마지막 문장에 그대로 쓰여 있어요.","answer":"X","reason_options":[{"t":"직접 쓰여 있지 않은 경우가 많아 여러 단서를 모아 짐작해야 하기 때문에","correct":true},{"t":"마지막 문장만 읽으면 글쓴이의 생각을 다 알 수 있기 때문에","mis":"K5-2-u5-X13"}],"mis":"K5-2-u5-X13","explanation":["그대로 쓰여 있지 않을 때가 많아요.","단서를 모아요.","짐작해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_basic#5','kor',5,2,'u5','L04','g5_2_kor_u5_L04_basic','lesson_basic','K5-2-u5-C15',2,'mc','auto','이야기 처음과 끝에서 달빛 마을의 모습은 어떻게 달라졌나요?',ARRAY['K5-2-u5-X15','K5-2-u5-X05']::text[],false,'{"seq":5,"concept":"K5-2-u5-C15","difficulty":2,"kind":"mc","stem":"이야기 처음과 끝에서 달빛 마을의 모습은 어떻게 달라졌나요?","options":[{"t":"조용하던 골목에 다시 웃음소리가 들렸다","correct":true},{"t":"처음부터 끝까지 똑같이 조용했다","mis":"K5-2-u5-X15"},{"t":"웃음소리가 들리던 골목이 조용해졌다","mis":"K5-2-u5-X15"},{"t":"마을 사람들이 모두 이사를 떠났다","mis":"K5-2-u5-X05"}],"explanation":["달라졌어요.","차례가 거꾸로예요.","골목이 되살아났어요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_basic#6','kor',5,2,'u5','L04','g5_2_kor_u5_L04_basic','lesson_basic','K5-2-u5-C12',2,'mc','auto','공책에 「시간 통장」이라는 이름을 붙인 까닭으로 알맞은 짐작은 어느 것인가요?',ARRAY['K5-2-u5-X09','K5-2-u5-X06','K5-2-u5-X12']::text[],false,'{"seq":6,"concept":"K5-2-u5-C12","difficulty":2,"kind":"mc","stem":"공책에 「시간 통장」이라는 이름을 붙인 까닭으로 알맞은 짐작은 어느 것인가요?","options":[{"t":"시간을 돈처럼 모으고 쓰는 방법이라서","correct":true},{"t":"공책을 은행에서 사 와서","mis":"K5-2-u5-X09"},{"t":"시계를 고치는 사람이 만들어서","mis":"K5-2-u5-X06"},{"t":"글에 쓰여 있지 않으니 알 필요가 없어서","mis":"K5-2-u5-X12"}],"explanation":["근거가 없어요.","단서와 맞지 않아요.","더하고 빼는 단서와 통장 지식을 합쳐요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_basic#7','kor',5,2,'u5','L04','g5_2_kor_u5_L04_basic','lesson_basic','K5-2-u5-C11',2,'match','auto','이야기의 부분과 간추린 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u5-C11","difficulty":2,"kind":"match","stem":"이야기의 부분과 간추린 내용을 알맞게 이으세요.","pairs":[{"l":"처음","r":"공장이 문을 닫아 마을이 어려워졌다"},{"l":"가운데","r":"마을 사람들이 시간 통장으로 재주를 나누었다"},{"l":"끝","r":"닫혔던 가게가 열리고 골목이 되살아났다"}],"mis":"K5-2-u5-X23","explanation":["어려움으로 시작해요.","나눔이 이어져요.","골목이 되살아나요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_basic#8','kor',5,2,'u5','L04','g5_2_kor_u5_L04_basic','lesson_basic','K5-2-u5-C14',2,'mc','auto','글쓴이의 생각을 짐작할 때 살펴볼 단서로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u5-X14']::text[],false,'{"seq":8,"concept":"K5-2-u5-C14","difficulty":2,"kind":"mc","stem":"글쓴이의 생각을 짐작할 때 살펴볼 단서로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글에 나오는 낱말의 수","correct":true},{"t":"인물의 말과 행동","mis":"K5-2-u5-X14"},{"t":"이야기 끝에 일어난 변화","mis":"K5-2-u5-X14"},{"t":"글의 제목","mis":"K5-2-u5-X14"}],"explanation":["살펴볼 단서예요.","살펴볼 단서예요.","낱말 수는 생각과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_basic#9','kor',5,2,'u5','L04','g5_2_kor_u5_L04_basic','lesson_basic','K5-2-u5-C15',2,'error','auto','하린이의 마음을 짐작한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u5-X15','K5-2-u5-X07','K5-2-u5-X06']::text[],false,'{"seq":9,"concept":"K5-2-u5-C15","difficulty":2,"kind":"error","stem":"하린이의 마음을 짐작한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「하린이는 처음부터 끝까지 마음이 하나도 달라지지 않았을 거야.」","correct":true,"mis_target":"K5-2-u5-X15"},{"t":"「엄마가 목도리를 건넬 때 하린이는 걱정되었을 거야.」","mis":"K5-2-u5-X07"},{"t":"「동생을 도우면서 하린이는 뿌듯했을 거야.」","mis":"K5-2-u5-X06"}],"explanation":["어려운 마을 상황이 단서예요.","도운 일이 단서예요.","장면마다 마음이 달라져요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_basic#10','kor',5,2,'u5','L04','g5_2_kor_u5_L04_basic','lesson_basic','K5-2-u5-C14',3,'mc','auto','제목 「골목을 다시 웃게 한 시간 통장」에서 짐작할 수 있는 글쓴이의 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X14','K5-2-u5-X13']::text[],false,'{"seq":10,"concept":"K5-2-u5-C14","difficulty":3,"kind":"mc","stem":"제목 「골목을 다시 웃게 한 시간 통장」에서 짐작할 수 있는 글쓴이의 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 재주와 시간을 나누면 어려운 마을도 다시 살아날 수 있다","correct":true},{"t":"시계는 꼭 빵집에서 고쳐야 한다","mis":"K5-2-u5-X14"},{"t":"공장이 없으면 마을은 되살아날 수 없다","mis":"K5-2-u5-X14"},{"t":"통장은 은행에서만 쓰는 것이다","mis":"K5-2-u5-X13"}],"explanation":["작은 사실 하나예요.","이야기 끝과 맞지 않아요.","「다시 웃게 한」이 무엇이 돌아왔는지 알려 줘요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_challenge#1','kor',5,2,'u5','L04','g5_2_kor_u5_L04_challenge','lesson_challenge','K5-2-u5-C11',2,'ox','auto','이야기를 간추릴 때는 작은 일까지 모두 써야 해요.',ARRAY['K5-2-u5-X11']::text[],false,'{"seq":1,"concept":"K5-2-u5-C11","difficulty":2,"kind":"ox","stem":"이야기를 간추릴 때는 작은 일까지 모두 써야 해요.","answer":"X","reason_options":[{"t":"중요한 장면만 골라 인물의 행동과 변화를 써야 뼈대가 잘 보이기 때문에","correct":true},{"t":"하나라도 빠뜨리면 간추린 것이 아니기 때문에","mis":"K5-2-u5-X11"}],"mis":"K5-2-u5-X11","explanation":["다 쓰지 않아요.","중요한 장면만 골라요.","뼈대가 보이게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_challenge#2','kor',5,2,'u5','L04','g5_2_kor_u5_L04_challenge','lesson_challenge','K5-2-u5-C12',2,'mc','auto','이야기에 쓰여 있지 않지만 짐작할 수 있는 내용은 어느 것인가요?',ARRAY['K5-2-u5-X09','K5-2-u5-X05']::text[],false,'{"seq":2,"concept":"K5-2-u5-C12","difficulty":2,"kind":"mc","stem":"이야기에 쓰여 있지 않지만 짐작할 수 있는 내용은 어느 것인가요?","options":[{"t":"마을 사람들이 서로를 믿고 도움을 주고받게 되었다","correct":true},{"t":"하린이가 받아쓰기 시험에서 일등을 했다","mis":"K5-2-u5-X09"},{"t":"빵집 아주머니가 은행에서 일했다","mis":"K5-2-u5-X09"},{"t":"시간 통장은 하린이가 만들었다","mis":"K5-2-u5-X05"}],"explanation":["근거가 없어요.","근거가 없어요.","서로 돕는 장면이 단서예요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_challenge#3','kor',5,2,'u5','L04','g5_2_kor_u5_L04_challenge','lesson_challenge','K5-2-u5-C13',3,'mc','auto','「골목에 웃음소리가 들렸다」라는 마지막 부분에 대한 설명으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X13','K5-2-u5-X14','K5-2-u5-X09']::text[],false,'{"seq":3,"concept":"K5-2-u5-C13","difficulty":3,"kind":"mc","stem":"「골목에 웃음소리가 들렸다」라는 마지막 부분에 대한 설명으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마을의 모습을 보여 줄 뿐, 글쓴이의 생각은 여러 단서를 모아 짐작해야 한다","correct":true},{"t":"이 부분이 글쓴이의 생각을 그대로 말한 것이다","mis":"K5-2-u5-X13"},{"t":"이 부분은 이야기와 관계없다","mis":"K5-2-u5-X14"},{"t":"웃음소리는 지어낸 것이라 읽지 않아도 된다","mis":"K5-2-u5-X09"}],"explanation":["장면을 보여 줄 뿐이에요.","중요한 변화예요.","단서를 모아 짐작해요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_challenge#4','kor',5,2,'u5','L04','g5_2_kor_u5_L04_challenge','lesson_challenge','K5-2-u5-C10',3,'mc','auto','두 친구가 짐작한 글쓴이의 생각을 바르게 견준 것은 어느 것인가요?',ARRAY['K5-2-u5-X10','K5-2-u5-X08']::text[],false,'{"seq":4,"concept":"K5-2-u5-C10","difficulty":3,"kind":"mc","stem":"두 친구가 짐작한 글쓴이의 생각을 바르게 견준 것은 어느 것인가요?","options":[{"t":"서로 다른 단서를 근거로 삼았으니 둘 다 근거와 함께 말할 수 있다","correct":true},{"t":"먼저 말한 친구의 생각만 맞다","mis":"K5-2-u5-X10"},{"t":"생각이 다르니 둘 다 틀렸다","mis":"K5-2-u5-X10"},{"t":"근거는 말하지 않아도 된다","mis":"K5-2-u5-X08"}],"explanation":["먼저 말했다고 맞는 것이 아니에요.","달라도 괜찮아요.","근거와 함께 견줘요."],"asset":{"type":"speech","turns":[{"who":"하윤","text":"글쓴이는 돈보다 사람 사이의 믿음이 더 중요하다고 말하고 싶었을 거야. 서로 믿고 시간을 주고받았잖아."},{"who":"서진","text":"글쓴이는 어려울 때 새로운 방법을 생각해 내는 지혜를 말하고 싶었을 거야. 시간을 돈처럼 썼잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_challenge#5','kor',5,2,'u5','L04','g5_2_kor_u5_L04_challenge','lesson_challenge','K5-2-u5-C11',3,'error','auto','시간 통장 이야기를 간추린 것이에요. 간추린 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u5-X11','K5-2-u5-X23']::text[],false,'{"seq":5,"concept":"K5-2-u5-C11","difficulty":3,"kind":"error","stem":"시간 통장 이야기를 간추린 것이에요. 간추린 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「빵집 벽시계는 동그랗고 바늘이 둘이었다.」","correct":true,"mis_target":"K5-2-u5-X11"},{"t":"「공장이 문을 닫아 마을이 어려워졌다.」","mis":"K5-2-u5-X23"},{"t":"「사람들이 시간 통장으로 서로 도왔다.」","mis":"K5-2-u5-X23"}],"explanation":["중요한 장면이에요.","중요한 장면이에요.","작은 꾸밈은 간추리지 않아요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_challenge#6','kor',5,2,'u5','L04','g5_2_kor_u5_L04_challenge','lesson_challenge','K5-2-u5-C15',3,'mc','auto','빵집에서 낯선 장면을 본 뒤 하린이의 마음은 어떻게 달라졌을지 짐작한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X15','K5-2-u5-X09','K5-2-u5-X06']::text[],false,'{"seq":6,"concept":"K5-2-u5-C15","difficulty":3,"kind":"mc","stem":"빵집에서 낯선 장면을 본 뒤 하린이의 마음은 어떻게 달라졌을지 짐작한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"걱정하던 마음에 희망이 조금 생겼을 것이다","correct":true},{"t":"마음은 아무 변화가 없었을 것이다","mis":"K5-2-u5-X15"},{"t":"빵을 못 사서 화가 났을 것이다","mis":"K5-2-u5-X09"},{"t":"이사를 가고 싶어졌을 것이다","mis":"K5-2-u5-X06"}],"explanation":["장면이 바뀌면 마음도 달라져요.","근거가 없어요.","빵을 바꾸는 모습이 희망의 단서예요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_challenge#7','kor',5,2,'u5','L04','g5_2_kor_u5_L04_challenge','lesson_challenge','K5-2-u5-C14',3,'mc','auto','「글쓴이는 나눔이 소중하다고 생각한다」고 짐작할 때 근거로 삼기에 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X14']::text[],false,'{"seq":7,"concept":"K5-2-u5-C14","difficulty":3,"kind":"mc","stem":"「글쓴이는 나눔이 소중하다고 생각한다」고 짐작할 때 근거로 삼기에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"재주와 시간을 나누자 가게가 다시 열리고 웃음소리가 들렸다는 이야기 끝의 변화","correct":true},{"t":"하린이 엄마가 목도리를 가지고 있었다는 것","mis":"K5-2-u5-X14"},{"t":"공장이 컸다는 것","mis":"K5-2-u5-X14"},{"t":"빵집에 벽시계가 있었다는 것","mis":"K5-2-u5-X14"}],"explanation":["작은 사실 하나예요.","생각과 이어지지 않아요.","이야기 끝의 변화가 근거예요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_challenge#8','kor',5,2,'u5','L04','g5_2_kor_u5_L04_challenge','lesson_challenge','K5-2-u5-C11',4,'essay','teacher','「골목을 다시 웃게 한 시간 통장」을 처음, 가운데, 끝 세 장면으로 나누어 장면마다 한 문장으로 간추려 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u5-C11","difficulty":4,"kind":"essay","stem":"「골목을 다시 웃게 한 시간 통장」을 처음, 가운데, 끝 세 장면으로 나누어 장면마다 한 문장으로 간추려 쓰세요.","answer_guide":{"answer":"예: 처음 — 공장이 문을 닫자 달빛 마을은 일자리가 줄고 골목이 조용해졌다. 가운데 — 마을 사람들은 시간 통장에 이름을 올리고 서로의 재주를 나누었다. 끝 — 계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸다.","scoring_points":["세 장면으로 나누었는가","장면마다 한 문장으로 썼는가","중요한 내용만 골랐는가"]},"explanation":["세 장면이에요.","한 문장씩 써요.","중요한 것만 골라요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_challenge#9','kor',5,2,'u5','L04','g5_2_kor_u5_L04_challenge','lesson_challenge','K5-2-u5-C12',4,'essay','teacher','시간 통장이 마을을 다시 살아나게 할 수 있었던 까닭을 글의 단서와 내 경험이나 지식을 바탕으로 짐작해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u5-C12","difficulty":4,"kind":"essay","stem":"시간 통장이 마을을 다시 살아나게 할 수 있었던 까닭을 글의 단서와 내 경험이나 지식을 바탕으로 짐작해 쓰세요.","answer_guide":{"answer":"예: 돈이 없어도 저마다 가진 재주로 서로 도울 수 있었기 때문이다. 글에서 시계를 고쳐 주고 빵을 받고, 엄마가 뜨개질을 가르친 단서를 찾았다. 나도 친구에게 줄넘기를 가르쳐 주고 수학 문제를 배운 적이 있는데, 서로 도우니 둘 다 좋아졌다.","scoring_points":["까닭을 짐작했는가","글의 단서를 썼는가","경험이나 지식을 썼는가"]},"explanation":["까닭을 짐작해요.","단서를 써요.","경험을 더해요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L04_challenge#10','kor',5,2,'u5','L04','g5_2_kor_u5_L04_challenge','lesson_challenge','K5-2-u5-C13',4,'essay','teacher','「골목을 다시 웃게 한 시간 통장」에서 글쓴이가 전하려는 생각을 내 말로 쓰고, 그렇게 짐작한 단서를 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u5-C13","difficulty":4,"kind":"essay","stem":"「골목을 다시 웃게 한 시간 통장」에서 글쓴이가 전하려는 생각을 내 말로 쓰고, 그렇게 짐작한 단서를 두 가지 쓰세요.","answer_guide":{"answer":"예: 어려울 때 서로 가진 재주와 시간을 나누면 함께 이겨 낼 수 있다는 생각이다. 단서는 제목의 「다시 웃게 한」이라는 말과, 사람들이 서로 도운 뒤 가게가 다시 열리고 웃음소리가 들렸다는 이야기 끝의 변화이다.","scoring_points":["글쓴이의 생각을 내 말로 썼는가","단서 두 가지를 썼는가","단서와 생각이 이어지는가"]},"explanation":["내 말로 써요.","단서 둘이에요.","이어지게 써요."],"asset":{"type":"passage","lines":["달빛 마을은 큰 공장이 문을 닫은 뒤로 일자리가 줄었어요.","이사를 떠나는 집이 늘고, 골목은 조용해졌어요.","빵집에서는 이웃 할아버지가 벽시계를 고쳐 주고 빵을 받아 갔어요.","아주머니가 공책을 보여 주었어요. 「시간 통장이야.」","「남을 위해 한 시간 일하면 한 칸 더하고, 도움을 받으면 한 칸 빼.」","하린이네도 이름을 올렸어요. 엄마는 뜨개질을 가르쳤어요.","하린이는 옆집 동생의 받아쓰기를 도왔어요.","계절이 두 번 바뀌자 닫혔던 가게가 열리고 골목에 웃음소리가 들렸어요."],"title":"골목을 다시 웃게 한 시간 통장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_basic#1','kor',5,2,'u5','L07','g5_2_kor_u5_L07_basic','lesson_basic','K5-2-u5-C17',1,'mc','auto','뜻이 바로 드러나지 않고 숨겨져 있거나 하나의 표현에 여러 뜻이 담긴 표현을 무엇이라고 하나요?',ARRAY['K5-2-u5-X17']::text[],false,'{"seq":1,"concept":"K5-2-u5-C17","difficulty":1,"kind":"mc","stem":"뜻이 바로 드러나지 않고 숨겨져 있거나 하나의 표현에 여러 뜻이 담긴 표현을 무엇이라고 하나요?","options":[{"t":"함축된 표현","correct":true},{"t":"흉내 내는 말","mis":"K5-2-u5-X17"},{"t":"높임 표현","mis":"K5-2-u5-X17"},{"t":"순화어","mis":"K5-2-u5-X17"}],"explanation":["소리나 모양을 흉내 내요.","웃어른을 높여요.","숨은 뜻이 담긴 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_basic#2','kor',5,2,'u5','L07','g5_2_kor_u5_L07_basic','lesson_basic','K5-2-u5-C18',1,'mc','auto','「등대」의 사전에서의 뜻은 무엇인가요?',ARRAY['K5-2-u5-X18']::text[],false,'{"seq":2,"concept":"K5-2-u5-C18","difficulty":1,"kind":"mc","stem":"「등대」의 사전에서의 뜻은 무엇인가요?","options":[{"t":"배에 길을 알려 주는 불빛 탑","correct":true},{"t":"책을 빌려주는 곳","mis":"K5-2-u5-X18"},{"t":"궁금한 것을 찾는 사람","mis":"K5-2-u5-X18"},{"t":"바닷가 모래밭","mis":"K5-2-u5-X18"}],"explanation":["글에서의 뜻과 섞였어요.","뜻이 달라요.","사전 뜻은 불빛 탑이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_basic#3','kor',5,2,'u5','L07','g5_2_kor_u5_L07_basic','lesson_basic','K5-2-u5-C16',1,'mc','auto','문단의 중심 내용을 간추릴 때 먼저 찾는 것은 무엇인가요?',ARRAY['K5-2-u5-X16']::text[],false,'{"seq":3,"concept":"K5-2-u5-C16","difficulty":1,"kind":"mc","stem":"문단의 중심 내용을 간추릴 때 먼저 찾는 것은 무엇인가요?","options":[{"t":"중심 문장","correct":true},{"t":"가장 긴 문장","mis":"K5-2-u5-X16"},{"t":"예를 든 문장","mis":"K5-2-u5-X16"},{"t":"맨 처음 낱말","mis":"K5-2-u5-X16"}],"explanation":["길이와 관계없어요.","뒷받침하는 문장이에요.","중심 문장을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_basic#4','kor',5,2,'u5','L07','g5_2_kor_u5_L07_basic','lesson_basic','K5-2-u5-C17',1,'ox','auto','함축된 표현은 사실과 다르니 틀린 말이에요.',ARRAY['K5-2-u5-X17']::text[],false,'{"seq":4,"concept":"K5-2-u5-C17","difficulty":1,"kind":"ox","stem":"함축된 표현은 사실과 다르니 틀린 말이에요.","answer":"X","reason_options":[{"t":"숨은 뜻을 담아 생각이나 마음을 더 깊이 전하는 표현이기 때문에","correct":true},{"t":"도서관은 진짜 탑이 아니니 거짓말이기 때문에","mis":"K5-2-u5-X17"}],"mis":"K5-2-u5-X17","explanation":["틀린 말이 아니에요.","숨은 뜻이 있어요.","깊이 전하는 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_basic#5','kor',5,2,'u5','L07','g5_2_kor_u5_L07_basic','lesson_basic','K5-2-u5-C18',2,'mc','auto','「도서관은 우리 모두의 등대예요.」에서 「등대」의 글에서의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X18','K5-2-u5-X20','K5-2-u5-X21']::text[],false,'{"seq":5,"concept":"K5-2-u5-C18","difficulty":2,"kind":"mc","stem":"「도서관은 우리 모두의 등대예요.」에서 「등대」의 글에서의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"알고 싶은 것을 찾아갈 길을 밝혀 주는 곳","correct":true},{"t":"바닷가에 서 있는 불빛 탑","mis":"K5-2-u5-X18"},{"t":"밤에만 문을 여는 곳","mis":"K5-2-u5-X20"},{"t":"배를 고치는 곳","mis":"K5-2-u5-X21"}],"explanation":["사전 뜻이에요.","앞뒤 단서와 맞지 않아요.","헤매는 사람에게 길을 밝혀 줘요."],"asset":{"type":"passage","lines":["옛날에는 책을 손으로 한 글자씩 베껴 써서 책을 가진 사람이 적었어요.","인쇄술이 발달하자 글을 읽는 사람이 크게 늘었어요.","책은 사람과 사람의 생각을 잇는 징검다리가 되었지요.","오늘날 도서관은 누구나 돈을 내지 않고 책을 빌릴 수 있는 곳이에요.","궁금한 것이 생겨 헤매는 사람에게 도서관은 멀리서도 보이는 불빛이에요.","도서관은 우리 모두의 등대예요.","책장을 넘기면 가 보지 못한 나라와 만나 보지 못한 사람의 삶이 펼쳐져요.","책은 세상을 내다보는 창문이에요."],"title":"도서관, 모두의 등대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_basic#6','kor',5,2,'u5','L07','g5_2_kor_u5_L07_basic','lesson_basic','K5-2-u5-C20',2,'mc','auto','「징검다리」의 숨은 뜻을 짐작하게 하는 단서로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X20']::text[],false,'{"seq":6,"concept":"K5-2-u5-C20","difficulty":2,"kind":"mc","stem":"「징검다리」의 숨은 뜻을 짐작하게 하는 단서로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람과 사람의 생각을 잇는","correct":true},{"t":"손으로 한 글자씩 베껴 써서","mis":"K5-2-u5-X20"},{"t":"돈을 내지 않고","mis":"K5-2-u5-X20"},{"t":"가 보지 못한 나라","mis":"K5-2-u5-X20"}],"explanation":["다른 문장의 내용이에요.","다른 문장의 내용이에요.","바로 앞 말이 단서예요."],"asset":{"type":"passage","lines":["옛날에는 책을 손으로 한 글자씩 베껴 써서 책을 가진 사람이 적었어요.","인쇄술이 발달하자 글을 읽는 사람이 크게 늘었어요.","책은 사람과 사람의 생각을 잇는 징검다리가 되었지요.","오늘날 도서관은 누구나 돈을 내지 않고 책을 빌릴 수 있는 곳이에요.","궁금한 것이 생겨 헤매는 사람에게 도서관은 멀리서도 보이는 불빛이에요.","도서관은 우리 모두의 등대예요.","책장을 넘기면 가 보지 못한 나라와 만나 보지 못한 사람의 삶이 펼쳐져요.","책은 세상을 내다보는 창문이에요."],"title":"도서관, 모두의 등대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_basic#7','kor',5,2,'u5','L07','g5_2_kor_u5_L07_basic','lesson_basic','K5-2-u5-C18',2,'match','auto','함축된 표현과 글에서의 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u5-C18","difficulty":2,"kind":"match","stem":"함축된 표현과 글에서의 뜻을 알맞게 이으세요.","pairs":[{"l":"징검다리","r":"사람들의 생각을 이어 주는 것"},{"l":"등대","r":"알고 싶은 것을 찾아갈 길을 밝혀 주는 곳"},{"l":"창문","r":"가 보지 못한 세상을 보여 주는 것"}],"mis":"K5-2-u5-X18","explanation":["생각을 이어요.","길을 밝혀요.","세상을 보여 줘요."],"asset":{"type":"passage","lines":["옛날에는 책을 손으로 한 글자씩 베껴 써서 책을 가진 사람이 적었어요.","인쇄술이 발달하자 글을 읽는 사람이 크게 늘었어요.","책은 사람과 사람의 생각을 잇는 징검다리가 되었지요.","오늘날 도서관은 누구나 돈을 내지 않고 책을 빌릴 수 있는 곳이에요.","궁금한 것이 생겨 헤매는 사람에게 도서관은 멀리서도 보이는 불빛이에요.","도서관은 우리 모두의 등대예요.","책장을 넘기면 가 보지 못한 나라와 만나 보지 못한 사람의 삶이 펼쳐져요.","책은 세상을 내다보는 창문이에요."],"title":"도서관, 모두의 등대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_basic#8','kor',5,2,'u5','L07','g5_2_kor_u5_L07_basic','lesson_basic','K5-2-u5-C19',2,'mc','auto','「책은 세상을 내다보는 창문이에요.」를 사전 뜻 그대로 읽으면 어색한 까닭은 무엇인가요?',ARRAY['K5-2-u5-X19']::text[],false,'{"seq":8,"concept":"K5-2-u5-C19","difficulty":2,"kind":"mc","stem":"「책은 세상을 내다보는 창문이에요.」를 사전 뜻 그대로 읽으면 어색한 까닭은 무엇인가요?","options":[{"t":"책은 벽에 낸 진짜 창이 아니기 때문에","correct":true},{"t":"책에는 글자가 없기 때문에","mis":"K5-2-u5-X19"},{"t":"창문이라는 낱말이 너무 길기 때문에","mis":"K5-2-u5-X19"},{"t":"어색한 곳이 없어 그냥 넘어가도 되기 때문에","mis":"K5-2-u5-X19"}],"explanation":["틀린 까닭이에요.","길이와 관계없어요.","어색한 곳에서 숨은 뜻을 찾아요."],"asset":{"type":"passage","lines":["옛날에는 책을 손으로 한 글자씩 베껴 써서 책을 가진 사람이 적었어요.","인쇄술이 발달하자 글을 읽는 사람이 크게 늘었어요.","책은 사람과 사람의 생각을 잇는 징검다리가 되었지요.","오늘날 도서관은 누구나 돈을 내지 않고 책을 빌릴 수 있는 곳이에요.","궁금한 것이 생겨 헤매는 사람에게 도서관은 멀리서도 보이는 불빛이에요.","도서관은 우리 모두의 등대예요.","책장을 넘기면 가 보지 못한 나라와 만나 보지 못한 사람의 삶이 펼쳐져요.","책은 세상을 내다보는 창문이에요."],"title":"도서관, 모두의 등대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_basic#9','kor',5,2,'u5','L07','g5_2_kor_u5_L07_basic','lesson_basic','K5-2-u5-C21',2,'mc','auto','「등대」의 숨은 뜻을 짐작할 때 도움이 되는 경험이나 지식은 어느 것인가요?',ARRAY['K5-2-u5-X21']::text[],false,'{"seq":9,"concept":"K5-2-u5-C21","difficulty":2,"kind":"mc","stem":"「등대」의 숨은 뜻을 짐작할 때 도움이 되는 경험이나 지식은 어느 것인가요?","options":[{"t":"등대는 밤바다에서 배가 길을 잃지 않게 불을 비춘다","correct":true},{"t":"등대는 하얀색으로 칠한다","mis":"K5-2-u5-X21"},{"t":"등대는 아주 무겁다","mis":"K5-2-u5-X21"},{"t":"등대는 두 글자로 된 낱말이다","mis":"K5-2-u5-X21"}],"explanation":["뜻과 닿지 않아요.","뜻과 닿지 않아요.","길을 밝히는 쓰임이 숨은 뜻과 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_basic#10','kor',5,2,'u5','L07','g5_2_kor_u5_L07_basic','lesson_basic','K5-2-u5-C22',3,'mc','auto','글쓴이가 「도서관은 책을 빌리는 곳이에요.」라고만 쓰지 않고 「도서관은 우리 모두의 등대예요.」라고 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X22','K5-2-u5-X18']::text[],false,'{"seq":10,"concept":"K5-2-u5-C22","difficulty":3,"kind":"mc","stem":"글쓴이가 「도서관은 책을 빌리는 곳이에요.」라고만 쓰지 않고 「도서관은 우리 모두의 등대예요.」라고 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"도서관이 사람들에게 주는 도움을 더 깊고 생생하게 전하려고","correct":true},{"t":"읽는 사람이 뜻을 모르게 하려고","mis":"K5-2-u5-X22"},{"t":"도서관이 바닷가에 있다는 것을 알리려고","mis":"K5-2-u5-X18"},{"t":"문장을 길게 만들려고","mis":"K5-2-u5-X22"}],"explanation":["숨기려는 것이 아니에요.","사전 뜻으로 읽었어요.","깊고 생생하게 전해요."],"asset":{"type":"passage","lines":["옛날에는 책을 손으로 한 글자씩 베껴 써서 책을 가진 사람이 적었어요.","인쇄술이 발달하자 글을 읽는 사람이 크게 늘었어요.","책은 사람과 사람의 생각을 잇는 징검다리가 되었지요.","오늘날 도서관은 누구나 돈을 내지 않고 책을 빌릴 수 있는 곳이에요.","궁금한 것이 생겨 헤매는 사람에게 도서관은 멀리서도 보이는 불빛이에요.","도서관은 우리 모두의 등대예요.","책장을 넘기면 가 보지 못한 나라와 만나 보지 못한 사람의 삶이 펼쳐져요.","책은 세상을 내다보는 창문이에요."],"title":"도서관, 모두의 등대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_challenge#1','kor',5,2,'u5','L07','g5_2_kor_u5_L07_challenge','lesson_challenge','K5-2-u5-C18',2,'ox','auto','함축된 표현은 사전에 나온 뜻 그대로 읽으면 돼요.',ARRAY['K5-2-u5-X18']::text[],false,'{"seq":1,"concept":"K5-2-u5-C18","difficulty":2,"kind":"ox","stem":"함축된 표현은 사전에 나온 뜻 그대로 읽으면 돼요.","answer":"X","reason_options":[{"t":"사전 뜻에서 출발해 글의 흐름에 맞는 숨은 뜻을 찾아야 하기 때문에","correct":true},{"t":"사전에 나온 뜻이 언제나 글에서의 뜻과 같기 때문에","mis":"K5-2-u5-X18"}],"mis":"K5-2-u5-X18","explanation":["그대로 읽으면 어색해요.","글에서의 뜻을 찾아요.","사전 뜻에서 출발해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_challenge#2','kor',5,2,'u5','L07','g5_2_kor_u5_L07_challenge','lesson_challenge','K5-2-u5-C16',2,'mc','auto','「도서관, 모두의 등대」 전체의 중심 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X16','K5-2-u5-X18']::text[],false,'{"seq":2,"concept":"K5-2-u5-C16","difficulty":2,"kind":"mc","stem":"「도서관, 모두의 등대」 전체의 중심 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"책과 도서관은 사람들의 생각을 잇고 길을 밝히며 세상을 보여 준다","correct":true},{"t":"옛날에는 책을 손으로 베껴 썼다","mis":"K5-2-u5-X16"},{"t":"도서관은 돈을 내지 않는다","mis":"K5-2-u5-X16"},{"t":"창문은 세상을 내다보는 곳이다","mis":"K5-2-u5-X18"}],"explanation":["한 부분의 내용이에요.","한 부분의 내용이에요.","중심 문장들을 모아요."],"asset":{"type":"passage","lines":["옛날에는 책을 손으로 한 글자씩 베껴 써서 책을 가진 사람이 적었어요.","인쇄술이 발달하자 글을 읽는 사람이 크게 늘었어요.","책은 사람과 사람의 생각을 잇는 징검다리가 되었지요.","오늘날 도서관은 누구나 돈을 내지 않고 책을 빌릴 수 있는 곳이에요.","궁금한 것이 생겨 헤매는 사람에게 도서관은 멀리서도 보이는 불빛이에요.","도서관은 우리 모두의 등대예요.","책장을 넘기면 가 보지 못한 나라와 만나 보지 못한 사람의 삶이 펼쳐져요.","책은 세상을 내다보는 창문이에요."],"title":"도서관, 모두의 등대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_challenge#3','kor',5,2,'u5','L07','g5_2_kor_u5_L07_challenge','lesson_challenge','K5-2-u5-C17',3,'mc','auto','두 친구의 해석을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u5-X10','K5-2-u5-X09','K5-2-u5-X18']::text[],false,'{"seq":3,"concept":"K5-2-u5-C17","difficulty":3,"kind":"mc","stem":"두 친구의 해석을 바르게 말한 것은 어느 것인가요?","options":[{"t":"함축된 표현의 뜻은 하나가 아닐 수 있지만 글의 흐름과 근거에 맞아야 한다","correct":true},{"t":"한 표현에는 뜻이 오직 하나뿐이라 한쪽은 틀렸다","mis":"K5-2-u5-X10"},{"t":"근거가 없어도 떠오르는 대로 읽으면 된다","mis":"K5-2-u5-X09"},{"t":"사전 뜻이 아니니 둘 다 틀렸다","mis":"K5-2-u5-X18"}],"explanation":["여러 뜻이 담길 수 있어요.","근거가 필요해요.","두 친구 모두 근거를 들었어요."],"asset":{"type":"speech","turns":[{"who":"은우","text":"「모두의 등대」는 누구나 길을 찾을 수 있는 곳이라는 뜻이야. 헤매는 사람이라는 말이 있잖아."},{"who":"채원","text":"나는 어두운 마음을 밝혀 주는 곳이라고 읽었어. 등대는 깜깜한 밤바다를 밝히니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_challenge#4','kor',5,2,'u5','L07','g5_2_kor_u5_L07_challenge','lesson_challenge','K5-2-u5-C20',3,'error','auto','「창문」의 숨은 뜻을 짐작한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u5-X20','K5-2-u5-X21']::text[],false,'{"seq":4,"concept":"K5-2-u5-C20","difficulty":3,"kind":"error","stem":"「창문」의 숨은 뜻을 짐작한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「창문이라는 낱말 하나만 보면 되니 앞뒤 문장은 읽지 않아도 돼.」","correct":true,"mis_target":"K5-2-u5-X20"},{"t":"「가 보지 못한 나라와 만난다는 앞 문장이 단서야.」","mis":"K5-2-u5-X21"},{"t":"「창문으로 바깥을 내다본 경험을 떠올리면 뜻이 보여.」","mis":"K5-2-u5-X21"}],"explanation":["앞뒤 단서를 썼어요.","경험을 썼어요.","앞뒤 문장을 함께 봐야 해요."],"asset":{"type":"passage","lines":["옛날에는 책을 손으로 한 글자씩 베껴 써서 책을 가진 사람이 적었어요.","인쇄술이 발달하자 글을 읽는 사람이 크게 늘었어요.","책은 사람과 사람의 생각을 잇는 징검다리가 되었지요.","오늘날 도서관은 누구나 돈을 내지 않고 책을 빌릴 수 있는 곳이에요.","궁금한 것이 생겨 헤매는 사람에게 도서관은 멀리서도 보이는 불빛이에요.","도서관은 우리 모두의 등대예요.","책장을 넘기면 가 보지 못한 나라와 만나 보지 못한 사람의 삶이 펼쳐져요.","책은 세상을 내다보는 창문이에요."],"title":"도서관, 모두의 등대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_challenge#5','kor',5,2,'u5','L07','g5_2_kor_u5_L07_challenge','lesson_challenge','K5-2-u5-C19',3,'mc','auto','함축된 표현을 찾으며 읽을 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u5-X19','K5-2-u5-X17','K5-2-u5-X18']::text[],false,'{"seq":5,"concept":"K5-2-u5-C19","difficulty":3,"kind":"mc","stem":"함축된 표현을 찾으며 읽을 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"사전 뜻으로 읽어 어색한 곳을 숨은 뜻을 찾을 자리로 여기고 멈추어 생각한다","correct":true},{"t":"어색한 곳은 건너뛰고 빨리 읽는다","mis":"K5-2-u5-X19"},{"t":"어색한 문장은 글쓴이가 틀린 것이라 여긴다","mis":"K5-2-u5-X17"},{"t":"모든 낱말을 사전 뜻으로만 외운다","mis":"K5-2-u5-X18"}],"explanation":["지나치면 숨은 뜻을 놓쳐요.","틀린 말이 아니에요.","어색함이 신호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_challenge#6','kor',5,2,'u5','L07','g5_2_kor_u5_L07_challenge','lesson_challenge','K5-2-u5-C22',3,'mc','auto','함축된 표현을 쓰면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X22','K5-2-u5-X17']::text[],false,'{"seq":6,"concept":"K5-2-u5-C22","difficulty":3,"kind":"mc","stem":"함축된 표현을 쓰면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"짧은 표현에 여러 뜻을 담아 읽는 사람이 더 깊이 생각하게 한다","correct":true},{"t":"뜻을 어렵게 만들어 읽는 사람을 헷갈리게 한다","mis":"K5-2-u5-X22"},{"t":"글자 수를 늘려 글을 길게 만든다","mis":"K5-2-u5-X22"},{"t":"사실을 틀리게 바꾸어 말한다","mis":"K5-2-u5-X17"}],"explanation":["헷갈리게 하려는 것이 아니에요.","길이와 관계없어요.","깊이 생각하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_challenge#7','kor',5,2,'u5','L07','g5_2_kor_u5_L07_challenge','lesson_challenge','K5-2-u5-C21',3,'mc','auto','「징검다리」의 숨은 뜻을 짐작할 때 가장 도움이 되는 경험은 어느 것인가요?',ARRAY['K5-2-u5-X21']::text[],false,'{"seq":7,"concept":"K5-2-u5-C21","difficulty":3,"kind":"mc","stem":"「징검다리」의 숨은 뜻을 짐작할 때 가장 도움이 되는 경험은 어느 것인가요?","options":[{"t":"냇물에 놓인 돌을 밟고 건너편으로 건너간 경험","correct":true},{"t":"다리 위에서 사진을 찍은 경험","mis":"K5-2-u5-X21"},{"t":"돌멩이로 탑을 쌓아 본 경험","mis":"K5-2-u5-X21"},{"t":"징검다리 그림을 색칠한 경험","mis":"K5-2-u5-X21"}],"explanation":["잇는 쓰임과 멀어요.","잇는 쓰임과 멀어요.","건너편으로 이어 준 경험이 뜻과 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_challenge#8','kor',5,2,'u5','L07','g5_2_kor_u5_L07_challenge','lesson_challenge','K5-2-u5-C18',4,'essay','teacher','「도서관, 모두의 등대」에서 함축된 표현 하나를 골라 사전에서의 뜻과 글에서의 뜻을 각각 쓰고, 글에서의 뜻을 짐작하게 한 단서를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u5-C18","difficulty":4,"kind":"essay","stem":"「도서관, 모두의 등대」에서 함축된 표현 하나를 골라 사전에서의 뜻과 글에서의 뜻을 각각 쓰고, 글에서의 뜻을 짐작하게 한 단서를 쓰세요.","answer_guide":{"answer":"예: 「창문」 — 사전에서의 뜻은 바깥을 내다볼 수 있게 벽에 낸 문이다. 글에서의 뜻은 가 보지 못한 세상과 사람들의 삶을 보여 주는 것이다. 「책장을 넘기면 가 보지 못한 나라와 만나 보지 못한 사람의 삶이 펼쳐져요.」라는 앞 문장이 단서이다.","scoring_points":["표현을 하나 골랐는가","사전에서의 뜻과 글에서의 뜻을 썼는가","단서를 썼는가"]},"explanation":["하나를 골라요.","두 뜻을 써요.","단서를 밝혀요."],"asset":{"type":"passage","lines":["옛날에는 책을 손으로 한 글자씩 베껴 써서 책을 가진 사람이 적었어요.","인쇄술이 발달하자 글을 읽는 사람이 크게 늘었어요.","책은 사람과 사람의 생각을 잇는 징검다리가 되었지요.","오늘날 도서관은 누구나 돈을 내지 않고 책을 빌릴 수 있는 곳이에요.","궁금한 것이 생겨 헤매는 사람에게 도서관은 멀리서도 보이는 불빛이에요.","도서관은 우리 모두의 등대예요.","책장을 넘기면 가 보지 못한 나라와 만나 보지 못한 사람의 삶이 펼쳐져요.","책은 세상을 내다보는 창문이에요."],"title":"도서관, 모두의 등대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_challenge#9','kor',5,2,'u5','L07','g5_2_kor_u5_L07_challenge','lesson_challenge','K5-2-u5-C16',4,'essay','teacher','「도서관, 모두의 등대」를 읽고 글쓴이가 책과 도서관에 대해 말한 내용을 세 가지로 간추려 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u5-C16","difficulty":4,"kind":"essay","stem":"「도서관, 모두의 등대」를 읽고 글쓴이가 책과 도서관에 대해 말한 내용을 세 가지로 간추려 쓰세요.","answer_guide":{"answer":"예: 첫째, 인쇄술이 발달해 책은 사람들의 생각을 잇는 징검다리가 되었다. 둘째, 도서관은 누구나 돈을 내지 않고 책을 빌릴 수 있어 모두에게 길을 밝혀 주는 등대이다. 셋째, 책은 가 보지 못한 세상을 보여 주는 창문이다.","scoring_points":["세 가지로 나누었는가","중심 내용을 간추렸는가","함축된 표현의 뜻을 살렸는가"]},"explanation":["세 가지예요.","중심 내용이에요.","숨은 뜻을 살려요."],"asset":{"type":"passage","lines":["옛날에는 책을 손으로 한 글자씩 베껴 써서 책을 가진 사람이 적었어요.","인쇄술이 발달하자 글을 읽는 사람이 크게 늘었어요.","책은 사람과 사람의 생각을 잇는 징검다리가 되었지요.","오늘날 도서관은 누구나 돈을 내지 않고 책을 빌릴 수 있는 곳이에요.","궁금한 것이 생겨 헤매는 사람에게 도서관은 멀리서도 보이는 불빛이에요.","도서관은 우리 모두의 등대예요.","책장을 넘기면 가 보지 못한 나라와 만나 보지 못한 사람의 삶이 펼쳐져요.","책은 세상을 내다보는 창문이에요."],"title":"도서관, 모두의 등대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L07_challenge#10','kor',5,2,'u5','L07','g5_2_kor_u5_L07_challenge','lesson_challenge','K5-2-u5-C22',4,'essay','teacher','「등대」나 「창문」처럼 다른 것에 빗댄 함축된 표현을 넣어 우리 학교 도서실을 소개하는 문장을 두 개 쓰고, 표현에 담은 뜻을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u5-C22","difficulty":4,"kind":"essay","stem":"「등대」나 「창문」처럼 다른 것에 빗댄 함축된 표현을 넣어 우리 학교 도서실을 소개하는 문장을 두 개 쓰고, 표현에 담은 뜻을 쓰세요.","answer_guide":{"answer":"예: 「우리 학교 도서실은 생각이 자라는 텃밭이에요.」 — 책을 읽으며 생각이 쑥쑥 자란다는 뜻이다. 「도서실 책장은 보물 상자예요.」 — 책마다 새로운 이야기와 지식이 숨어 있다는 뜻이다.","scoring_points":["빗댄 표현 두 개를 썼는가","도서실을 소개하는 문장인가","담은 뜻을 썼는가"]},"explanation":["두 문장을 써요.","도서실을 소개해요.","뜻을 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_basic#1','kor',5,2,'u5','L09','g5_2_kor_u5_L09_basic','lesson_basic','K5-2-u5-C24',1,'mc','auto','글쓴이가 독자에게 전하고 싶은 생각이나 바람을 무엇이라고 하나요?',ARRAY['K5-2-u5-X24','K5-2-u5-X28']::text[],false,'{"seq":1,"concept":"K5-2-u5-C24","difficulty":1,"kind":"mc","stem":"글쓴이가 독자에게 전하고 싶은 생각이나 바람을 무엇이라고 하나요?","options":[{"t":"글쓴이의 의도","correct":true},{"t":"글의 소재","mis":"K5-2-u5-X24"},{"t":"인물의 말","mis":"K5-2-u5-X28"},{"t":"글의 차례","mis":"K5-2-u5-X24"}],"explanation":["무엇에 대한 글인지예요.","이야기 속 말이에요.","글을 쓴 까닭이 의도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_basic#2','kor',5,2,'u5','L09','g5_2_kor_u5_L09_basic','lesson_basic','K5-2-u5-C23',1,'mc','auto','「조용한 한마디」에서 가장 먼저 일어난 일은 무엇인가요?',ARRAY['K5-2-u5-X23']::text[],false,'{"seq":2,"concept":"K5-2-u5-C23","difficulty":1,"kind":"mc","stem":"「조용한 한마디」에서 가장 먼저 일어난 일은 무엇인가요?","options":[{"t":"로자 파크스가 운전사의 말에도 자리를 비키지 않았다","correct":true},{"t":"법원이 자리를 나누는 것이 잘못이라고 판단했다","mis":"K5-2-u5-X23"},{"t":"사람들이 비 오는 날에도 걸었다","mis":"K5-2-u5-X23"},{"t":"이웃들이 걸어서 가자고 말했다","mis":"K5-2-u5-X23"}],"explanation":["맨 나중 일이에요.","뒤에 일어난 일이에요.","로자의 거절에서 시작해요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_basic#3','kor',5,2,'u5','L09','g5_2_kor_u5_L09_basic','lesson_basic','K5-2-u5-C25',1,'mc','auto','로자 파크스의 「아니요.」에 담긴 숨은 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X25']::text[],false,'{"seq":3,"concept":"K5-2-u5-C25","difficulty":1,"kind":"mc","stem":"로자 파크스의 「아니요.」에 담긴 숨은 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"부당한 차별에는 따르지 않겠다","correct":true},{"t":"버스에서 내리고 싶다","mis":"K5-2-u5-X25"},{"t":"운전사의 말을 못 들었다","mis":"K5-2-u5-X25"},{"t":"자리가 마음에 들지 않는다","mis":"K5-2-u5-X25"}],"explanation":["겉으로만 읽었어요.","상황과 맞지 않아요.","차별하는 상황이 단서예요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_basic#4','kor',5,2,'u5','L09','g5_2_kor_u5_L09_basic','lesson_basic','K5-2-u5-C28',1,'ox','auto','글쓴이의 의도는 이야기 속 인물이 한 말과 언제나 똑같아요.',ARRAY['K5-2-u5-X28']::text[],false,'{"seq":4,"concept":"K5-2-u5-C28","difficulty":1,"kind":"ox","stem":"글쓴이의 의도는 이야기 속 인물이 한 말과 언제나 똑같아요.","answer":"X","reason_options":[{"t":"인물의 말은 이야기 속 상황에서 나온 말이고, 의도는 글 전체로 전하려는 생각이기 때문에","correct":true},{"t":"인물의 말을 글쓴이가 썼으니 둘은 늘 같기 때문에","mis":"K5-2-u5-X28"}],"mis":"K5-2-u5-X28","explanation":["같지 않을 수 있어요.","글 전체를 봐요.","정반대일 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_basic#5','kor',5,2,'u5','L09','g5_2_kor_u5_L09_basic','lesson_basic','K5-2-u5-C25',2,'mc','auto','이웃들이 한 말에 담긴 숨은 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X25','K5-2-u5-X18']::text[],false,'{"seq":5,"concept":"K5-2-u5-C25","difficulty":2,"kind":"mc","stem":"이웃들이 한 말에 담긴 숨은 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"불편해도 함께 맞서겠다는 마음은 흔들리지 않는다","correct":true},{"t":"걸으면 학교에 늦는다","mis":"K5-2-u5-X25"},{"t":"버스보다 걷기가 빠르다","mis":"K5-2-u5-X25"},{"t":"마음이 느려서 걱정이다","mis":"K5-2-u5-X18"}],"explanation":["겉뜻만 읽었어요.","글과 맞지 않아요.","걷기로 함께 맞선 상황이 단서예요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_basic#6','kor',5,2,'u5','L09','g5_2_kor_u5_L09_basic','lesson_basic','K5-2-u5-C26',2,'mc','auto','마지막 문장에서 서로 반대되는 말을 맞세운 것은 어느 것인가요?',ARRAY['K5-2-u5-X26']::text[],false,'{"seq":6,"concept":"K5-2-u5-C26","difficulty":2,"kind":"mc","stem":"마지막 문장에서 서로 반대되는 말을 맞세운 것은 어느 것인가요?","options":[{"t":"앉다와 일어서다","correct":true},{"t":"로자와 세상","mis":"K5-2-u5-X26"},{"t":"그날과 시작","mis":"K5-2-u5-X26"},{"t":"있었다와 했다","mis":"K5-2-u5-X26"}],"explanation":["반대되는 말이 아니에요.","반대되는 말이 아니에요.","앉다와 일어서다가 맞서요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_basic#7','kor',5,2,'u5','L09','g5_2_kor_u5_L09_basic','lesson_basic','K5-2-u5-C27',2,'mc','auto','글쓴이의 의도를 짐작하는 단서로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u5-X27']::text[],false,'{"seq":7,"concept":"K5-2-u5-C27","difficulty":2,"kind":"mc","stem":"글쓴이의 의도를 짐작하는 단서로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글을 쓴 종이의 크기","correct":true},{"t":"글의 중심 내용","mis":"K5-2-u5-X27"},{"t":"인물의 말에 담긴 함축된 표현","mis":"K5-2-u5-X27"},{"t":"되풀이되는 장면","mis":"K5-2-u5-X27"}],"explanation":["의도의 단서예요.","의도의 단서예요.","종이 크기는 의도와 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_basic#8','kor',5,2,'u5','L09','g5_2_kor_u5_L09_basic','lesson_basic','K5-2-u5-C25',2,'match','auto','인물의 말과 숨은 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u5-C25","difficulty":2,"kind":"match","stem":"인물의 말과 숨은 뜻을 알맞게 이으세요.","pairs":[{"l":"운전사 — 「여기서는 늘 그래 왔잖소.」","r":"오래된 차별을 당연하게 여기는 생각"},{"l":"로자 — 「아니요.」","r":"차별에 따르지 않겠다는 굳은 마음"},{"l":"이웃 — 「우리 마음까지 늦지는 않아요.」","r":"불편을 견디며 함께 맞서겠다는 뜻"}],"mis":"K5-2-u5-X25","explanation":["차별을 당연하게 여겨요.","굳은 마음이에요.","함께 맞서요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_basic#9','kor',5,2,'u5','L09','g5_2_kor_u5_L09_basic','lesson_basic','K5-2-u5-C23',2,'error','auto','「조용한 한마디」의 사건을 늘어놓은 것이에요. 차례가 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u5-X23','K5-2-u5-X24']::text[],false,'{"seq":9,"concept":"K5-2-u5-C23","difficulty":2,"kind":"error","stem":"「조용한 한마디」의 사건을 늘어놓은 것이에요. 차례가 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「법이 바뀜 → 로자가 경찰서로 감 → 걷기 운동」","correct":true,"mis_target":"K5-2-u5-X23"},{"t":"「로자가 자리를 비키지 않음 → 경찰서 → 걷기 운동 → 법이 바뀜」","mis":"K5-2-u5-X24"},{"t":"「차별하는 버스 → 로자의 거절 → 이웃들의 걷기」","mis":"K5-2-u5-X24"}],"explanation":["차례에 맞아요.","차례에 맞아요.","법이 바뀐 것은 맨 끝이에요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_basic#10','kor',5,2,'u5','L09','g5_2_kor_u5_L09_basic','lesson_basic','K5-2-u5-C24',3,'mc','auto','「조용한 한마디」에서 글쓴이의 의도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X24','K5-2-u5-X28']::text[],false,'{"seq":10,"concept":"K5-2-u5-C24","difficulty":3,"kind":"mc","stem":"「조용한 한마디」에서 글쓴이의 의도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작고 조용한 용기가 잘못된 차별을 바꾸는 큰 변화를 이끌 수 있다","correct":true},{"t":"버스는 걷기보다 편리하다","mis":"K5-2-u5-X24"},{"t":"운전사의 말처럼 늘 해 오던 대로 해야 한다","mis":"K5-2-u5-X28"},{"t":"경찰서는 무서운 곳이다","mis":"K5-2-u5-X24"}],"explanation":["소재에 머물렀어요.","인물의 말과 의도를 섞었어요.","마지막 문장과 장면이 단서예요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_challenge#1','kor',5,2,'u5','L09','g5_2_kor_u5_L09_challenge','lesson_challenge','K5-2-u5-C25',2,'ox','auto','같은 말이라도 누가 어떤 상황에서 했는지에 따라 숨은 뜻이 달라질 수 있어요.',ARRAY['K5-2-u5-X25']::text[],false,'{"seq":1,"concept":"K5-2-u5-C25","difficulty":2,"kind":"ox","stem":"같은 말이라도 누가 어떤 상황에서 했는지에 따라 숨은 뜻이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"말한 사람과 상황이 단서가 되어 뜻을 바꾸기 때문에","correct":true},{"t":"같은 말은 언제나 사전 뜻 그대로이기 때문에","mis":"K5-2-u5-X25"}],"mis":"K5-2-u5-X25","explanation":["상황이 단서예요.","누가 했는지도 봐요.","숨은 뜻이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_challenge#2','kor',5,2,'u5','L09','g5_2_kor_u5_L09_challenge','lesson_challenge','K5-2-u5-C26',2,'mc','auto','「앉다」와 「일어서다」를 맞세운 마지막 문장에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X26','K5-2-u5-X18']::text[],false,'{"seq":2,"concept":"K5-2-u5-C26","difficulty":2,"kind":"mc","stem":"「앉다」와 「일어서다」를 맞세운 마지막 문장에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"반대되는 말을 맞세워 작은 행동이 큰 변화를 이끌었다는 뜻을 전한다","correct":true},{"t":"앞뒤가 맞지 않는 틀린 문장이다","mis":"K5-2-u5-X26"},{"t":"로자가 실제로 일어섰다는 뜻이다","mis":"K5-2-u5-X18"},{"t":"세상이 버스에서 일어섰다는 뜻이다","mis":"K5-2-u5-X18"}],"explanation":["틀린 문장이 아니에요.","겉뜻으로 읽었어요.","맞세워 뜻을 또렷하게 해요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_challenge#3','kor',5,2,'u5','L09','g5_2_kor_u5_L09_challenge','lesson_challenge','K5-2-u5-C29',3,'mc','auto','두 친구의 말을 글 속 근거와 견주어 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u5-X29','K5-2-u5-X28','K5-2-u5-X13']::text[],false,'{"seq":3,"concept":"K5-2-u5-C29","difficulty":3,"kind":"mc","stem":"두 친구의 말을 글 속 근거와 견주어 바르게 말한 것은 어느 것인가요?","options":[{"t":"법원의 판단과 마지막 문장을 보면 잘못된 차별은 바뀌어야 한다는 쪽이 글의 근거에 맞다","correct":true},{"t":"해석은 사람마다 다르니 글의 근거와 맞지 않아도 둘 다 똑같이 알맞다","mis":"K5-2-u5-X29"},{"t":"운전사의 말이 글쓴이의 생각이다","mis":"K5-2-u5-X28"},{"t":"글쓴이의 의도는 알 수 없으니 생각하지 않는다","mis":"K5-2-u5-X13"}],"explanation":["근거와 맞아야 해요.","인물의 말과 의도를 섞었어요.","글 속 근거에 맞는 쪽을 찾아요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"글쓴이는 법을 어긴 로자가 잘못했다는 것을 알려 주려고 이 글을 썼어."},{"who":"수아","text":"글쓴이는 잘못된 차별은 바뀌어야 한다는 것을 말하고 싶었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_challenge#4','kor',5,2,'u5','L09','g5_2_kor_u5_L09_challenge','lesson_challenge','K5-2-u5-C27',3,'mc','auto','「사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.」가 글쓴이의 의도를 짐작하는 데 도움이 되는 까닭은 무엇인가요?',ARRAY['K5-2-u5-X27','K5-2-u5-X24']::text[],false,'{"seq":4,"concept":"K5-2-u5-C27","difficulty":3,"kind":"mc","stem":"「사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.」가 글쓴이의 의도를 짐작하는 데 도움이 되는 까닭은 무엇인가요?","options":[{"t":"함께 오래 견딘 사람들의 굳은 마음을 거듭 보여 주기 때문에","correct":true},{"t":"날씨를 알려 주는 문장이기 때문에","mis":"K5-2-u5-X27"},{"t":"신발 가게를 소개하는 문장이기 때문에","mis":"K5-2-u5-X24"},{"t":"의도와 관계없는 장면이기 때문에","mis":"K5-2-u5-X27"}],"explanation":["겉뜻만 읽었어요.","소재와 섞었어요.","되풀이되는 장면이 단서예요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_challenge#5','kor',5,2,'u5','L09','g5_2_kor_u5_L09_challenge','lesson_challenge','K5-2-u5-C28',3,'error','auto','「조용한 한마디」를 읽고 나눈 말이에요. 글쓴이의 의도를 잘못 짐작한 말은 어느 것인가요?',ARRAY['K5-2-u5-X28','K5-2-u5-X27']::text[],false,'{"seq":5,"concept":"K5-2-u5-C28","difficulty":3,"kind":"error","stem":"「조용한 한마디」를 읽고 나눈 말이에요. 글쓴이의 의도를 잘못 짐작한 말은 어느 것인가요?","options":[{"t":"「운전사가 늘 그래 왔다고 했으니, 글쓴이도 하던 대로 하자고 말하는 거야.」","correct":true,"mis_target":"K5-2-u5-X28"},{"t":"「작은 용기가 세상을 바꿀 수 있다고 말하는 것 같아.」","mis":"K5-2-u5-X27"},{"t":"「차별은 함께 힘을 모아 바꿀 수 있다고 말하는 것 같아.」","mis":"K5-2-u5-X27"}],"explanation":["알맞게 짐작했어요.","알맞게 짐작했어요.","인물의 말이 곧 의도는 아니에요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_challenge#6','kor',5,2,'u5','L09','g5_2_kor_u5_L09_challenge','lesson_challenge','K5-2-u5-C24',3,'mc','auto','「조용한 한마디」의 소재와 글쓴이의 의도를 바르게 구별한 것은 어느 것인가요?',ARRAY['K5-2-u5-X24','K5-2-u5-X28']::text[],false,'{"seq":6,"concept":"K5-2-u5-C24","difficulty":3,"kind":"mc","stem":"「조용한 한마디」의 소재와 글쓴이의 의도를 바르게 구별한 것은 어느 것인가요?","options":[{"t":"소재는 버스에서 있었던 일이고, 의도는 작은 용기가 차별을 바꿀 수 있다는 생각이다","correct":true},{"t":"소재와 의도는 같은 말이다","mis":"K5-2-u5-X24"},{"t":"의도는 버스에서 있었던 일이다","mis":"K5-2-u5-X24"},{"t":"소재도 의도도 운전사의 말이다","mis":"K5-2-u5-X28"}],"explanation":["둘은 달라요.","그것은 소재예요.","소재와 의도를 갈라 봐요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_challenge#7','kor',5,2,'u5','L09','g5_2_kor_u5_L09_challenge','lesson_challenge','K5-2-u5-C23',3,'mc','auto','이야기를 주요 장면 중심으로 차례대로 간추리면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X23']::text[],false,'{"seq":7,"concept":"K5-2-u5-C23","difficulty":3,"kind":"mc","stem":"이야기를 주요 장면 중심으로 차례대로 간추리면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사건의 흐름이 보여 함축된 표현과 글쓴이의 의도를 짐작하기 쉬워진다","correct":true},{"t":"글을 다시 읽지 않아도 되어 빨리 끝난다","mis":"K5-2-u5-X23"},{"t":"인물의 말을 모두 외울 수 있다","mis":"K5-2-u5-X23"},{"t":"장면의 차례를 마음대로 바꿀 수 있다","mis":"K5-2-u5-X23"}],"explanation":["간추리기는 읽기를 돕는 일이에요.","외우기가 목적이 아니에요.","흐름이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_challenge#8','kor',5,2,'u5','L09','g5_2_kor_u5_L09_challenge','lesson_challenge','K5-2-u5-C25',4,'essay','teacher','「조용한 한마디」에서 인물의 말 하나를 골라 겉으로 드러난 뜻과 숨은 뜻을 각각 쓰고, 숨은 뜻을 짐작한 단서를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u5-C25","difficulty":4,"kind":"essay","stem":"「조용한 한마디」에서 인물의 말 하나를 골라 겉으로 드러난 뜻과 숨은 뜻을 각각 쓰고, 숨은 뜻을 짐작한 단서를 쓰세요.","answer_guide":{"answer":"예: 로자의 「아니요.」 — 겉뜻은 자리를 비키지 않겠다는 말이다. 숨은 뜻은 피부색으로 사람을 나누는 부당한 차별에는 따르지 않겠다는 굳은 마음이다. 피부색에 따라 자리가 나뉘어 있었다는 상황과 버스 안이 얼음처럼 굳었다는 장면이 단서이다.","scoring_points":["말을 하나 골랐는가","겉뜻과 숨은 뜻을 썼는가","단서를 썼는가"]},"explanation":["말을 골라요.","두 뜻을 써요.","단서를 밝혀요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_challenge#9','kor',5,2,'u5','L09','g5_2_kor_u5_L09_challenge','lesson_challenge','K5-2-u5-C24',4,'essay','teacher','「조용한 한마디」에서 글쓴이의 의도를 한 문장으로 쓰고, 그렇게 짐작한 단서를 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u5-C24","difficulty":4,"kind":"essay","stem":"「조용한 한마디」에서 글쓴이의 의도를 한 문장으로 쓰고, 그렇게 짐작한 단서를 두 가지 쓰세요.","answer_guide":{"answer":"예: 작고 조용한 용기라도 여럿이 함께하면 잘못된 차별을 바꿀 수 있다. 단서는 사람들이 비 오는 날에도 밑창이 닳아도 걸었다는 장면과, 「앉아 있었을 뿐이지만 세상은 일어서기 시작했어요」라는 마지막 문장이다.","scoring_points":["의도를 한 문장으로 썼는가","단서 두 가지를 썼는가","단서와 의도가 이어지는가"]},"explanation":["한 문장이에요.","단서 둘이에요.","이어지게 써요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L09_challenge#10','kor',5,2,'u5','L09','g5_2_kor_u5_L09_challenge','lesson_challenge','K5-2-u5-C29',4,'essay','teacher','「법이라고 다 옳을까?」를 「조용한 한마디」와 이어 생각해 보고, 잘못된 규칙을 바꾸는 바른 방법을 내 생각으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u5-C29","difficulty":4,"kind":"essay","stem":"「법이라고 다 옳을까?」를 「조용한 한마디」와 이어 생각해 보고, 잘못된 규칙을 바꾸는 바른 방법을 내 생각으로 쓰세요.","answer_guide":{"answer":"예: 법이나 규칙도 사람이 만든 것이라 잘못될 수 있다. 「조용한 한마디」에서 사람들은 폭력을 쓰지 않고 함께 걷는 방법으로 뜻을 모았고, 끝내 법원이 잘못을 바로잡았다. 잘못된 규칙은 무시하기보다 까닭을 밝히고 여럿이 힘을 모아 바른 절차로 바꾸어야 한다고 생각한다.","scoring_points":["글의 내용과 이어 생각했는가","바꾸는 바른 방법을 썼는가","내 생각에 근거가 있는가"]},"explanation":["글과 이어요.","바른 방법을 써요.","근거를 들어요."],"asset":{"type":"passage","lines":["아주 오래전 미국의 한 도시에서는 피부색에 따라 버스 자리가 나뉘어 있었어요.","운전사가 로자 파크스에게 소리쳤어요. 「자리를 비켜요. 여기서는 늘 그래 왔잖소.」","로자는 조용히 말했어요. 「아니요.」 버스 안이 얼음처럼 굳었어요.","로자가 경찰서로 끌려간 날 밤, 이웃들이 말했어요.","「걸어서 가면 조금 늦을 뿐, 우리 마음까지 늦지는 않아요.」","사람들은 비 오는 날에도, 밑창이 닳아도 걸었어요.","마침내 법원은 피부색으로 자리를 나누는 것이 잘못이라고 판단했어요.","로자는 앉아 있었을 뿐이지만, 그날 세상은 일어서기 시작했어요."],"title":"조용한 한마디"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_basic#1','kor',5,2,'u5','L12','g5_2_kor_u5_L12_basic','lesson_basic','K5-2-u5-C30',1,'mc','auto','카드 ㉮의 표현이 나타내는 감정은 무엇인가요?',ARRAY['K5-2-u5-X30']::text[],false,'{"seq":1,"concept":"K5-2-u5-C30","difficulty":1,"kind":"mc","stem":"카드 ㉮의 표현이 나타내는 감정은 무엇인가요?","options":[{"t":"기쁨","correct":true},{"t":"슬픔","mis":"K5-2-u5-X30"},{"t":"화남","mis":"K5-2-u5-X30"},{"t":"무서움","mis":"K5-2-u5-X30"}],"explanation":["먹구름 쪽 감정이에요.","끓는 주전자 쪽 감정이에요.","풍선이 둥실 떠오르는 마음이에요."],"asset":{"type":"passage","lines":["카드 ㉮ — 마음속에 풍선이 둥실 떠올랐어.","카드 ㉯ — 마음에 먹구름이 잔뜩 끼었어.","카드 ㉰ — 심장이 쿵 하고 내려앉았어.","카드 ㉱ — 가슴속에서 주전자가 펄펄 끓어."],"title":"친구들이 만든 감정 카드 뒷면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_basic#2','kor',5,2,'u5','L12','g5_2_kor_u5_L12_basic','lesson_basic','K5-2-u5-C30',1,'mc','auto','카드 ㉰의 표현이 나타내는 감정은 무엇인가요?',ARRAY['K5-2-u5-X30']::text[],false,'{"seq":2,"concept":"K5-2-u5-C30","difficulty":1,"kind":"mc","stem":"카드 ㉰의 표현이 나타내는 감정은 무엇인가요?","options":[{"t":"놀람","correct":true},{"t":"기쁨","mis":"K5-2-u5-X30"},{"t":"졸림","mis":"K5-2-u5-X30"},{"t":"배고픔","mis":"K5-2-u5-X30"}],"explanation":["떠오르는 마음이 아니에요.","몸의 상태예요.","심장이 쿵 내려앉는 마음이에요."],"asset":{"type":"passage","lines":["카드 ㉮ — 마음속에 풍선이 둥실 떠올랐어.","카드 ㉯ — 마음에 먹구름이 잔뜩 끼었어.","카드 ㉰ — 심장이 쿵 하고 내려앉았어.","카드 ㉱ — 가슴속에서 주전자가 펄펄 끓어."],"title":"친구들이 만든 감정 카드 뒷면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_basic#3','kor',5,2,'u5','L12','g5_2_kor_u5_L12_basic','lesson_basic','K5-2-u5-C31',1,'mc','auto','감정 카드 뒷면에 감정을 쓰는 약속으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X31']::text[],false,'{"seq":3,"concept":"K5-2-u5-C31","difficulty":1,"kind":"mc","stem":"감정 카드 뒷면에 감정을 쓰는 약속으로 알맞은 것은 어느 것인가요?","options":[{"t":"감정 낱말 없이 함축된 표현으로 쓴다","correct":true},{"t":"기쁘다, 슬프다 같은 감정 낱말만 쓴다","mis":"K5-2-u5-X31"},{"t":"그림만 그리고 아무것도 쓰지 않는다","mis":"K5-2-u5-X31"},{"t":"친구 이름을 쓴다","mis":"K5-2-u5-X31"}],"explanation":["약속과 달라요.","그림은 앞면이에요.","빗대어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_basic#4','kor',5,2,'u5','L12','g5_2_kor_u5_L12_basic','lesson_basic','K5-2-u5-C32',1,'ox','auto','친구의 감정 카드를 보고 마음을 짐작한 뒤에는 친구에게 맞는지 물어보면 좋아요.',ARRAY['K5-2-u5-X32']::text[],false,'{"seq":4,"concept":"K5-2-u5-C32","difficulty":1,"kind":"ox","stem":"친구의 감정 카드를 보고 마음을 짐작한 뒤에는 친구에게 맞는지 물어보면 좋아요.","answer":"O","reason_options":[{"t":"함축된 표현은 여러 뜻으로 읽힐 수 있어 친구의 설명을 들어야 하기 때문에","correct":true},{"t":"내 짐작이 언제나 맞기 때문에","mis":"K5-2-u5-X32"}],"mis":"K5-2-u5-X32","explanation":["여러 뜻이 있을 수 있어요.","물어보고 들어요.","확인하면 더 잘 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_basic#5','kor',5,2,'u5','L12','g5_2_kor_u5_L12_basic','lesson_basic','K5-2-u5-C30',2,'mc','auto','카드 ㉱를 쓴 친구의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X30']::text[],false,'{"seq":5,"concept":"K5-2-u5-C30","difficulty":2,"kind":"mc","stem":"카드 ㉱를 쓴 친구의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"몹시 화가 났다","correct":true},{"t":"마음이 편안하다","mis":"K5-2-u5-X30"},{"t":"배가 고프다","mis":"K5-2-u5-X30"},{"t":"잠이 온다","mis":"K5-2-u5-X30"}],"explanation":["끓는 모습과 맞지 않아요.","몸의 상태예요.","펄펄 끓는 주전자가 화난 마음이에요."],"asset":{"type":"passage","lines":["카드 ㉮ — 마음속에 풍선이 둥실 떠올랐어.","카드 ㉯ — 마음에 먹구름이 잔뜩 끼었어.","카드 ㉰ — 심장이 쿵 하고 내려앉았어.","카드 ㉱ — 가슴속에서 주전자가 펄펄 끓어."],"title":"친구들이 만든 감정 카드 뒷면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_basic#6','kor',5,2,'u5','L12','g5_2_kor_u5_L12_basic','lesson_basic','K5-2-u5-C30',2,'mc','auto','「슬퍼.」보다 「마음에 먹구름이 잔뜩 끼었어.」라고 말할 때 좋은 점은 무엇인가요?',ARRAY['K5-2-u5-X30','K5-2-u5-X22']::text[],false,'{"seq":6,"concept":"K5-2-u5-C30","difficulty":2,"kind":"mc","stem":"「슬퍼.」보다 「마음에 먹구름이 잔뜩 끼었어.」라고 말할 때 좋은 점은 무엇인가요?","options":[{"t":"마음의 모습이 그림처럼 그려져 감정의 깊이까지 전해진다","correct":true},{"t":"뜻을 아무도 알 수 없게 된다","mis":"K5-2-u5-X30"},{"t":"말이 짧아진다","mis":"K5-2-u5-X30"},{"t":"읽는 사람이 헷갈리기만 한다","mis":"K5-2-u5-X22"}],"explanation":["짐작할 수 있어요.","길이와 관계없어요.","깊이까지 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_basic#7','kor',5,2,'u5','L12','g5_2_kor_u5_L12_basic','lesson_basic','K5-2-u5-C30',2,'match','auto','감정 카드의 표현과 감정을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u5-C30","difficulty":2,"kind":"match","stem":"감정 카드의 표현과 감정을 알맞게 이으세요.","pairs":[{"l":"마음속에 풍선이 둥실 떠올랐어","r":"기쁨"},{"l":"마음에 먹구름이 잔뜩 끼었어","r":"슬픔"},{"l":"가슴속에서 주전자가 펄펄 끓어","r":"화남"}],"mis":"K5-2-u5-X30","explanation":["떠오르는 마음이에요.","어두운 마음이에요.","끓어오르는 마음이에요."],"asset":{"type":"passage","lines":["카드 ㉮ — 마음속에 풍선이 둥실 떠올랐어.","카드 ㉯ — 마음에 먹구름이 잔뜩 끼었어.","카드 ㉰ — 심장이 쿵 하고 내려앉았어.","카드 ㉱ — 가슴속에서 주전자가 펄펄 끓어."],"title":"친구들이 만든 감정 카드 뒷면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_basic#8','kor',5,2,'u5','L12','g5_2_kor_u5_L12_basic','lesson_basic','K5-2-u5-C33',2,'mc','auto','카드 ㉯를 쓴 친구에게 건넬 공감하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X18','K5-2-u5-X33']::text[],false,'{"seq":8,"concept":"K5-2-u5-C33","difficulty":2,"kind":"mc","stem":"카드 ㉯를 쓴 친구에게 건넬 공감하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「마음이 많이 무거웠구나. 무슨 일이 있었는지 들어 줄게.」","correct":true},{"t":"「먹구름? 하늘 이야기야?」","mis":"K5-2-u5-X18"},{"t":"「그 정도로 뭘 그래.」","mis":"K5-2-u5-X33"},{"t":"「나는 기분 좋은데.」","mis":"K5-2-u5-X33"}],"explanation":["겉뜻으로만 읽었어요.","마음을 가볍게 여겼어요.","마음을 알아주는 말이에요."],"asset":{"type":"passage","lines":["카드 ㉮ — 마음속에 풍선이 둥실 떠올랐어.","카드 ㉯ — 마음에 먹구름이 잔뜩 끼었어.","카드 ㉰ — 심장이 쿵 하고 내려앉았어.","카드 ㉱ — 가슴속에서 주전자가 펄펄 끓어."],"title":"친구들이 만든 감정 카드 뒷면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_basic#9','kor',5,2,'u5','L12','g5_2_kor_u5_L12_basic','lesson_basic','K5-2-u5-C31',2,'error','auto','감정 카드 뒷면에 쓴 문장이에요. 약속에 맞지 않는 것은 어느 것인가요?',ARRAY['K5-2-u5-X31','K5-2-u5-X30']::text[],false,'{"seq":9,"concept":"K5-2-u5-C31","difficulty":2,"kind":"error","stem":"감정 카드 뒷면에 쓴 문장이에요. 약속에 맞지 않는 것은 어느 것인가요?","options":[{"t":"「오늘 나는 정말 기뻤어.」","correct":true,"mis_target":"K5-2-u5-X31"},{"t":"「발걸음에 날개가 달린 것 같았어.」","mis":"K5-2-u5-X30"},{"t":"「마음에 봄바람이 살랑 불었어.」","mis":"K5-2-u5-X30"}],"explanation":["빗대어 썼어요.","빗대어 썼어요.","감정 낱말을 그대로 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_basic#10','kor',5,2,'u5','L12','g5_2_kor_u5_L12_basic','lesson_basic','K5-2-u5-C32',3,'mc','auto','친구의 감정 카드를 보고 한 짐작이 친구의 마음과 달랐을 때 가장 알맞은 행동은 어느 것인가요?',ARRAY['K5-2-u5-X32','K5-2-u5-X33']::text[],false,'{"seq":10,"concept":"K5-2-u5-C32","difficulty":3,"kind":"mc","stem":"친구의 감정 카드를 보고 한 짐작이 친구의 마음과 달랐을 때 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"친구의 설명을 귀 기울여 듣고 짐작을 고친다","correct":true},{"t":"내 짐작이 맞다고 우긴다","mis":"K5-2-u5-X32"},{"t":"카드를 돌려주고 말을 하지 않는다","mis":"K5-2-u5-X33"},{"t":"친구가 표현을 잘못 썼다고 놀린다","mis":"K5-2-u5-X33"}],"explanation":["우기지 않아요.","말을 이어 가요.","듣고 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_challenge#1','kor',5,2,'u5','L12','g5_2_kor_u5_L12_challenge','lesson_challenge','K5-2-u5-C31',2,'ox','auto','감정 카드 뒷면에는 감정을 나타내는 낱말을 그대로 써야 해요.',ARRAY['K5-2-u5-X30']::text[],false,'{"seq":1,"concept":"K5-2-u5-C31","difficulty":2,"kind":"ox","stem":"감정 카드 뒷면에는 감정을 나타내는 낱말을 그대로 써야 해요.","answer":"X","reason_options":[{"t":"감정 낱말 대신 빗대어 나타내야 친구가 단서로 마음을 짐작할 수 있기 때문에","correct":true},{"t":"감정 낱말을 써야만 친구가 알아들을 수 있기 때문에","mis":"K5-2-u5-X30"}],"mis":"K5-2-u5-X30","explanation":["그대로 쓰지 않아요.","빗대어 써요.","친구가 짐작할 기회를 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_challenge#2','kor',5,2,'u5','L12','g5_2_kor_u5_L12_challenge','lesson_challenge','K5-2-u5-C30',2,'mc','auto','사람이 감정을 함축된 표현으로 나타낼 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X30','K5-2-u5-X17']::text[],false,'{"seq":2,"concept":"K5-2-u5-C30","difficulty":2,"kind":"mc","stem":"사람이 감정을 함축된 표현으로 나타낼 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"감정을 느낄 때 겪는 몸과 마음의 변화를 다른 것에 빗댈 수 있기 때문에","correct":true},{"t":"감정에는 이름이 없기 때문에","mis":"K5-2-u5-X30"},{"t":"함축된 표현은 거짓말이기 때문에","mis":"K5-2-u5-X17"},{"t":"감정은 언제나 하나뿐이기 때문에","mis":"K5-2-u5-X30"}],"explanation":["감정 낱말도 있어요.","거짓말이 아니에요.","몸과 마음의 변화를 빗대요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_challenge#3','kor',5,2,'u5','L12','g5_2_kor_u5_L12_challenge','lesson_challenge','K5-2-u5-C32',3,'mc','auto','두 친구의 짐작을 듣고 할 수 있는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X32','K5-2-u5-X18','K5-2-u5-X10']::text[],false,'{"seq":3,"concept":"K5-2-u5-C32","difficulty":3,"kind":"mc","stem":"두 친구의 짐작을 듣고 할 수 있는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 뜻으로 읽힐 수 있으니 그림과 상황을 더 살피고 친구에게 물어본다","correct":true},{"t":"먼저 말한 짐작이 맞다","mis":"K5-2-u5-X32"},{"t":"차갑다는 말은 추위를 나타낼 뿐이다","mis":"K5-2-u5-X18"},{"t":"짐작이 다르니 카드를 버린다","mis":"K5-2-u5-X10"}],"explanation":["먼저 말했다고 맞지 않아요.","겉뜻으로만 읽었어요.","물어보면 알 수 있어요."],"asset":{"type":"speech","turns":[{"who":"민준","text":"「마음이 얼음처럼 차가워졌어.」라니, 화가 났구나."},{"who":"소율","text":"나는 서운했다고 짐작했어. 마음이 식어 버린 것 같잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_challenge#4','kor',5,2,'u5','L12','g5_2_kor_u5_L12_challenge','lesson_challenge','K5-2-u5-C33',3,'mc','auto','친구의 마음을 짐작한 뒤 공감하는 말을 건넬 때 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X33']::text[],false,'{"seq":4,"concept":"K5-2-u5-C33","difficulty":3,"kind":"mc","stem":"친구의 마음을 짐작한 뒤 공감하는 말을 건넬 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「~해서 ~한 마음이었구나.」처럼 짐작한 까닭과 마음을 함께 말한다","correct":true},{"t":"친구의 표현이 틀렸다고 고쳐 준다","mis":"K5-2-u5-X33"},{"t":"짐작만 하고 아무 말 없이 지나간다","mis":"K5-2-u5-X33"},{"t":"내 기분 이야기만 길게 한다","mis":"K5-2-u5-X33"}],"explanation":["틀린 표현이 아니에요.","말을 건네요.","마음을 알아줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_challenge#5','kor',5,2,'u5','L12','g5_2_kor_u5_L12_challenge','lesson_challenge','K5-2-u5-C30',3,'error','auto','기쁜 마음을 나타낸 문장이에요. 함축된 표현이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u5-X30','K5-2-u5-X31']::text[],false,'{"seq":5,"concept":"K5-2-u5-C30","difficulty":3,"kind":"error","stem":"기쁜 마음을 나타낸 문장이에요. 함축된 표현이 아닌 것은 어느 것인가요?","options":[{"t":"「오늘은 기분이 아주 좋았다.」","correct":true,"mis_target":"K5-2-u5-X30"},{"t":"「마음속에 해바라기가 활짝 피었어.」","mis":"K5-2-u5-X31"},{"t":"「발끝까지 햇살이 차오르는 것 같았어.」","mis":"K5-2-u5-X31"}],"explanation":["빗대어 썼어요.","빗대어 썼어요.","감정을 바로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_challenge#6','kor',5,2,'u5','L12','g5_2_kor_u5_L12_challenge','lesson_challenge','K5-2-u5-C31',3,'mc','auto','감정 카드의 앞면과 뒷면에 담을 것을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u5-X31']::text[],false,'{"seq":6,"concept":"K5-2-u5-C31","difficulty":3,"kind":"mc","stem":"감정 카드의 앞면과 뒷면에 담을 것을 바르게 말한 것은 어느 것인가요?","options":[{"t":"앞면에는 감정을 그림으로, 뒷면에는 그 감정을 함축된 표현으로","correct":true},{"t":"앞면에는 감정 낱말을, 뒷면에는 친구 이름을","mis":"K5-2-u5-X31"},{"t":"앞면과 뒷면 모두 감정 낱말만","mis":"K5-2-u5-X31"},{"t":"앞면은 비우고 뒷면에는 그림만","mis":"K5-2-u5-X31"}],"explanation":["약속과 달라요.","빗대지 않았어요.","앞은 그림, 뒤는 함축된 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_challenge#7','kor',5,2,'u5','L12','g5_2_kor_u5_L12_challenge','lesson_challenge','K5-2-u5-C32',3,'mc','auto','친구의 감정 카드로 마음을 짐작할 때 쓰는 단서를 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u5-X32','K5-2-u5-X09']::text[],false,'{"seq":7,"concept":"K5-2-u5-C32","difficulty":3,"kind":"mc","stem":"친구의 감정 카드로 마음을 짐작할 때 쓰는 단서를 바르게 말한 것은 어느 것인가요?","options":[{"t":"카드의 그림과 함축된 표현에 내 경험을 더한다","correct":true},{"t":"카드의 크기와 종이 색","mis":"K5-2-u5-X32"},{"t":"친구 이름의 글자 수","mis":"K5-2-u5-X32"},{"t":"단서 없이 떠오르는 대로","mis":"K5-2-u5-X09"}],"explanation":["마음과 관계없어요.","마음과 관계없어요.","그림과 표현이 단서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_challenge#8','kor',5,2,'u5','L12','g5_2_kor_u5_L12_challenge','lesson_challenge','K5-2-u5-C30',4,'essay','teacher','어제나 오늘 내가 느낀 감정 하나를 골라 감정 낱말을 쓰지 않고 함축된 표현으로 쓰고, 그 표현을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u5-C30","difficulty":4,"kind":"essay","stem":"어제나 오늘 내가 느낀 감정 하나를 골라 감정 낱말을 쓰지 않고 함축된 표현으로 쓰고, 그 표현을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 「발표를 마치자 어깨에 얹혀 있던 돌덩이가 데굴데굴 굴러 내려갔어.」 — 발표 전에는 마음이 무겁다가 끝나고 나니 홀가분했는데, 무거운 돌이 굴러떨어지는 모습이 그 마음과 닮아서 골랐다.","scoring_points":["감정 낱말 없이 썼는가","함축된 표현을 썼는가","고른 까닭을 썼는가"]},"explanation":["감정 낱말 없이요.","빗대어 써요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_challenge#9','kor',5,2,'u5','L12','g5_2_kor_u5_L12_challenge','lesson_challenge','K5-2-u5-C32',4,'essay','teacher','「마음이 얼음처럼 차가워졌어.」라는 카드를 받았을 때 친구의 마음을 짐작해 쓰고, 짐작을 확인하기 위해 친구에게 할 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u5-C32","difficulty":4,"kind":"essay","stem":"「마음이 얼음처럼 차가워졌어.」라는 카드를 받았을 때 친구의 마음을 짐작해 쓰고, 짐작을 확인하기 위해 친구에게 할 말을 쓰세요.","answer_guide":{"answer":"예: 친구가 누군가에게 서운했거나 마음이 상했을 것 같다. 「혹시 누구한테 서운한 일이 있었어? 내가 짐작한 게 맞는지 이야기해 줄래?」라고 묻겠다.","scoring_points":["마음을 짐작했는가","확인하는 말을 썼는가","친구의 설명을 들으려는 태도가 드러나는가"]},"explanation":["짐작해요.","물어봐요.","들으려 해요."],"asset":{"type":"speech","turns":[{"who":"민준","text":"「마음이 얼음처럼 차가워졌어.」라니, 화가 났구나."},{"who":"소율","text":"나는 서운했다고 짐작했어. 마음이 식어 버린 것 같잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_L12_challenge#10','kor',5,2,'u5','L12','g5_2_kor_u5_L12_challenge','lesson_challenge','K5-2-u5-C33',4,'essay','teacher','요즘 힘들어 보이는 친구를 떠올려 함축된 표현을 넣은 짧은 응원 편지를 쓰고, 그 표현에 담은 뜻을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u5-C33","difficulty":4,"kind":"essay","stem":"요즘 힘들어 보이는 친구를 떠올려 함축된 표현을 넣은 짧은 응원 편지를 쓰고, 그 표현에 담은 뜻을 쓰세요.","answer_guide":{"answer":"예: 「지민아, 요즘 네 마음에 비가 오는 것 같아 걱정돼. 그래도 비가 그치면 무지개가 뜨잖아. 내가 우산이 되어 줄게.」 — 「우산이 되어 준다」는 힘든 때 곁에서 지켜 주겠다는 뜻이다.","scoring_points":["응원 편지를 썼는가","함축된 표현을 넣었는가","담은 뜻을 썼는가"]},"explanation":["편지를 써요.","빗댄 표현을 넣어요.","뜻을 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#1','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C2',1,'mc','auto','글의 단서나 경험, 지식을 바탕으로 글에 드러나지 않은 내용을 짐작하는 것은 어느 것인가요?',ARRAY['K5-2-u5-X02']::text[],false,'{"seq":1,"concept":"K5-2-u5-C2","difficulty":1,"kind":"mc","stem":"글의 단서나 경험, 지식을 바탕으로 글에 드러나지 않은 내용을 짐작하는 것은 어느 것인가요?","options":[{"t":"추론","correct":true},{"t":"낭송","mis":"K5-2-u5-X02"},{"t":"요약","mis":"K5-2-u5-X02"},{"t":"필사","mis":"K5-2-u5-X02"}],"explanation":["소리 내어 읊어요.","간추려요.","짐작하며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#2','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C35',1,'mc','auto','「벼」와 「씨」가 어울린 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K5-2-u5-X35']::text[],false,'{"seq":2,"concept":"K5-2-u5-C35","difficulty":1,"kind":"mc","stem":"「벼」와 「씨」가 어울린 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"볍씨","correct":true},{"t":"벼씨","mis":"K5-2-u5-X35"},{"t":"볍시","mis":"K5-2-u5-X35"},{"t":"벼시","mis":"K5-2-u5-X35"}],"explanation":["ㅂ 소리가 빠졌어요.","「씨」가 바뀌었어요.","ㅂ 소리가 덧나 볍씨예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#3','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C17',1,'mc','auto','뜻이 숨겨져 있거나 여러 뜻이 담긴 표현을 무엇이라고 하는지 고르세요.',ARRAY['K5-2-u5-X17']::text[],false,'{"seq":3,"concept":"K5-2-u5-C17","difficulty":1,"kind":"mc","stem":"뜻이 숨겨져 있거나 여러 뜻이 담긴 표현을 무엇이라고 하는지 고르세요.","options":[{"t":"함축된 표현","correct":true},{"t":"꾸며 주는 말","mis":"K5-2-u5-X17"},{"t":"높임 표현","mis":"K5-2-u5-X17"},{"t":"흉내 내는 말","mis":"K5-2-u5-X17"}],"explanation":["뜻을 꾸며 줄 뿐이에요.","웃어른을 높여요.","숨은 뜻이 담긴 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#4','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C24',1,'mc','auto','글쓴이가 글을 쓴 까닭, 곧 독자에게 전하고 싶은 생각이나 바람은 어느 것인가요?',ARRAY['K5-2-u5-X24']::text[],false,'{"seq":4,"concept":"K5-2-u5-C24","difficulty":1,"kind":"mc","stem":"글쓴이가 글을 쓴 까닭, 곧 독자에게 전하고 싶은 생각이나 바람은 어느 것인가요?","options":[{"t":"글쓴이의 의도","correct":true},{"t":"글의 제목","mis":"K5-2-u5-X24"},{"t":"글의 소재","mis":"K5-2-u5-X24"},{"t":"글의 길이","mis":"K5-2-u5-X24"}],"explanation":["제목은 단서일 뿐이에요.","무엇에 대한 글인지예요.","글을 쓴 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#5','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C5',1,'mc','auto','「골목의 화분」에서 할머니가 날마다 한 일은 무엇인가요?',ARRAY['K5-2-u5-X05']::text[],false,'{"seq":5,"concept":"K5-2-u5-C5","difficulty":1,"kind":"mc","stem":"「골목의 화분」에서 할머니가 날마다 한 일은 무엇인가요?","options":[{"t":"대문 앞에 화분을 하나씩 내놓았다","correct":true},{"t":"골목 담벼락에 그림을 그렸다","mis":"K5-2-u5-X05"},{"t":"이웃에게 꽃을 팔았다","mis":"K5-2-u5-X05"},{"t":"화분을 모두 집 안으로 들였다","mis":"K5-2-u5-X05"}],"explanation":["글에 없어요.","글에 없어요.","화분을 하나씩 내놓았어요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#6','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C30',1,'mc','auto','「발걸음에 날개가 달린 것 같아.」가 나타내는 감정은 무엇인가요?',ARRAY['K5-2-u5-X30']::text[],false,'{"seq":6,"concept":"K5-2-u5-C30","difficulty":1,"kind":"mc","stem":"「발걸음에 날개가 달린 것 같아.」가 나타내는 감정은 무엇인가요?","options":[{"t":"신남","correct":true},{"t":"지침","mis":"K5-2-u5-X30"},{"t":"슬픔","mis":"K5-2-u5-X30"},{"t":"무서움","mis":"K5-2-u5-X30"}],"explanation":["무거운 마음과 반대예요.","가라앉은 마음이 아니에요.","가볍게 날 듯한 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#7','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C4',1,'match','auto','이 단원에서 배운 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u5-C4","difficulty":1,"kind":"match","stem":"이 단원에서 배운 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"추론","r":"드러나지 않은 내용 짐작하기"},{"l":"함축된 표현","r":"숨은 뜻이 담긴 표현"},{"l":"글쓴이의 의도","r":"글쓴이가 글을 쓴 까닭"}],"mis":"K5-2-u5-X04","explanation":["짐작이에요.","숨은 뜻이에요.","글을 쓴 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#8','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C5',1,'mc','auto','「텃밭의 빈 의자」에서 할아버지가 날마다 한 일은 무엇인가요?',ARRAY['K5-2-u5-X05']::text[],false,'{"seq":8,"concept":"K5-2-u5-C5","difficulty":1,"kind":"mc","stem":"「텃밭의 빈 의자」에서 할아버지가 날마다 한 일은 무엇인가요?","options":[{"t":"의자에 앉아 아이들이 심은 상추를 바라보았다","correct":true},{"t":"상추를 뽑아 팔았다","mis":"K5-2-u5-X05"},{"t":"의자를 새로 만들었다","mis":"K5-2-u5-X05"},{"t":"아이들에게 쪽지를 썼다","mis":"K5-2-u5-X05"}],"explanation":["글에 없어요.","글에 없어요.","쪽지는 아이들이 썼어요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#9','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C18',2,'mc','auto','「회색 골목이 이제는 계절마다 옷을 갈아입어요.」에서 「옷을 갈아입어요」의 글에서의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X18','K5-2-u5-X20']::text[],false,'{"seq":9,"concept":"K5-2-u5-C18","difficulty":2,"kind":"mc","stem":"「회색 골목이 이제는 계절마다 옷을 갈아입어요.」에서 「옷을 갈아입어요」의 글에서의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"계절마다 피는 꽃이 바뀌어 골목의 모습이 달라진다","correct":true},{"t":"골목 사람들이 새 옷을 산다","mis":"K5-2-u5-X18"},{"t":"골목에 옷 가게가 생겼다","mis":"K5-2-u5-X18"},{"t":"골목이 다시 회색이 되었다","mis":"K5-2-u5-X20"}],"explanation":["사전 뜻으로 읽었어요.","사전 뜻으로 읽었어요.","꽃 화분이 단서예요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#10','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C13',2,'mc','auto','「골목의 화분」에서 글쓴이가 전하려는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X14','K5-2-u5-X13']::text[],false,'{"seq":10,"concept":"K5-2-u5-C13","difficulty":2,"kind":"mc","stem":"「골목의 화분」에서 글쓴이가 전하려는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작은 일이라도 꾸준히 실천하면 큰 변화를 만들 수 있다","correct":true},{"t":"화분은 대문 앞에만 두어야 한다","mis":"K5-2-u5-X14"},{"t":"회색 골목은 바뀔 수 없다","mis":"K5-2-u5-X13"},{"t":"꽃은 할머니만 가꿀 수 있다","mis":"K5-2-u5-X13"}],"explanation":["작은 사실 하나예요.","이야기 끝과 맞지 않아요.","꾸준한 실천이 골목을 바꿨어요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#11','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C35',2,'mc','auto','두 낱말이 어울릴 때 ㅂ 소리가 덧나는 낱말로만 묶은 것은 어느 것인가요?',ARRAY['K5-2-u5-X36','K5-2-u5-X35']::text[],false,'{"seq":11,"concept":"K5-2-u5-C35","difficulty":2,"kind":"mc","stem":"두 낱말이 어울릴 때 ㅂ 소리가 덧나는 낱말로만 묶은 것은 어느 것인가요?","options":[{"t":"볍씨, 멥쌀, 좁쌀","correct":true},{"t":"수탉, 안팎, 살코기","mis":"K5-2-u5-X36"},{"t":"볍씨, 머리카락, 암탉","mis":"K5-2-u5-X35"},{"t":"햅쌀, 안팎, 좁쌀","mis":"K5-2-u5-X35"}],"explanation":["ㅎ 소리가 덧나요.","ㅎ 소리가 섞였어요.","ㅂ 소리가 덧나는 낱말이에요."],"asset":{"type":"passage","lines":["벼 + 씨 → 볍씨 · 해 + 쌀 → 햅쌀 · 메 + 쌀 → 멥쌀 · 조 + 쌀 → 좁쌀","수 + 닭 → 수탉 · 암 + 닭 → 암탉","머리 + 가락 → 머리카락 · 안 + 밖 → 안팎 · 살 + 고기 → 살코기"],"title":"두 낱말이 어울릴 때 소리가 덧나는 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#12','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C7',2,'mc','auto','아이들이 의자 위에 쪽지를 놓은 까닭을 짐작할 때 도움이 되는 경험은 어느 것인가요?',ARRAY['K5-2-u5-X07']::text[],false,'{"seq":12,"concept":"K5-2-u5-C7","difficulty":2,"kind":"mc","stem":"아이들이 의자 위에 쪽지를 놓은 까닭을 짐작할 때 도움이 되는 경험은 어느 것인가요?","options":[{"t":"아픈 친구에게 빨리 나으라고 편지를 써 본 경험","correct":true},{"t":"쪽지 시험을 본 경험","mis":"K5-2-u5-X07"},{"t":"의자를 옮겨 본 경험","mis":"K5-2-u5-X07"},{"t":"상추를 먹어 본 경험","mis":"K5-2-u5-X07"}],"explanation":["뜻과 닿지 않아요.","뜻과 닿지 않아요.","마음을 전한 경험이 닿아요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#13','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C25',2,'mc','auto','아이들이 쓴 「할아버지, 상추가 할아버지를 기다려요.」에 담긴 숨은 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X18','K5-2-u5-X25']::text[],false,'{"seq":13,"concept":"K5-2-u5-C25","difficulty":2,"kind":"mc","stem":"아이들이 쓴 「할아버지, 상추가 할아버지를 기다려요.」에 담긴 숨은 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리가 할아버지를 보고 싶어 기다려요","correct":true},{"t":"상추가 말을 할 수 있어요","mis":"K5-2-u5-X18"},{"t":"상추를 빨리 뽑아 주세요","mis":"K5-2-u5-X25"},{"t":"할아버지가 상추를 싫어해요","mis":"K5-2-u5-X25"}],"explanation":["겉뜻으로 읽었어요.","상황과 맞지 않아요.","쪽지를 쓴 아이들의 마음이에요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#14','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C27',2,'mc','auto','글쓴이의 의도를 짐작할 때 살펴볼 단서를 모두 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u5-X27','K5-2-u5-X28']::text[],false,'{"seq":14,"concept":"K5-2-u5-C27","difficulty":2,"kind":"mc","stem":"글쓴이의 의도를 짐작할 때 살펴볼 단서를 모두 바르게 말한 것은 어느 것인가요?","options":[{"t":"글의 중심 내용, 함축된 표현, 되풀이되는 장면","correct":true},{"t":"글자 크기, 쪽수, 그림 색","mis":"K5-2-u5-X27"},{"t":"글쓴이 이름, 나이, 사는 곳","mis":"K5-2-u5-X27"},{"t":"인물 한 명이 한 말 하나","mis":"K5-2-u5-X28"}],"explanation":["글의 겉모습이에요.","글 밖의 것이에요.","세 가지 단서를 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#15','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C11',2,'mc','auto','「텃밭의 빈 의자」를 간추린 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X11','K5-2-u5-X09']::text[],false,'{"seq":15,"concept":"K5-2-u5-C11","difficulty":2,"kind":"mc","stem":"「텃밭의 빈 의자」를 간추린 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"의자가 비자 아이들이 할아버지를 걱정하며 쪽지를 놓았고, 돌아온 할아버지는 쪽지를 읽으며 감동했다","correct":true},{"t":"텃밭 끝에 낡은 나무 의자가 하나 있었다","mis":"K5-2-u5-X11"},{"t":"상추에 물을 주는 방법을 알려 주는 이야기이다","mis":"K5-2-u5-X11"},{"t":"할아버지가 모자를 잃어버렸다","mis":"K5-2-u5-X09"}],"explanation":["한 장면뿐이에요.","이야기와 맞지 않아요.","중요한 장면을 이었어요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#16','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C33',2,'mc','auto','친구가 「가슴속에서 작은 북이 둥둥 울려.」라는 카드를 냈어요. 건넬 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X33','K5-2-u5-X18']::text[],false,'{"seq":16,"concept":"K5-2-u5-C33","difficulty":2,"kind":"mc","stem":"친구가 「가슴속에서 작은 북이 둥둥 울려.」라는 카드를 냈어요. 건넬 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「발표를 앞두고 많이 떨렸구나. 잘할 수 있을 거야.」","correct":true},{"t":"「떨 일이 뭐 있어.」","mis":"K5-2-u5-X33"},{"t":"「너 얼굴 빨개졌다!」","mis":"K5-2-u5-X33"},{"t":"「북은 음악실에 있어.」","mis":"K5-2-u5-X18"}],"explanation":["마음을 가볍게 여겼어요.","놀리는 말이에요.","마음을 알아주는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#17','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C24',3,'mc','auto','「텃밭의 빈 의자」에서 글쓴이의 의도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X24','K5-2-u5-X09']::text[],false,'{"seq":17,"concept":"K5-2-u5-C24","difficulty":3,"kind":"mc","stem":"「텃밭의 빈 의자」에서 글쓴이의 의도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로를 생각하는 작은 관심이 사람의 마음을 따뜻하게 한다","correct":true},{"t":"상추는 날마다 물을 주어야 잘 자란다","mis":"K5-2-u5-X24"},{"t":"낡은 의자는 바꾸어야 한다","mis":"K5-2-u5-X24"},{"t":"비 오는 날에는 밖에 나가면 안 된다","mis":"K5-2-u5-X09"}],"explanation":["소재에 머물렀어요.","소재에 머물렀어요.","쪽지와 해가 난 장면이 단서예요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#18','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C25',3,'mc','auto','이웃이 까닭을 묻자 할머니가 웃기만 한 장면에서 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X25','K5-2-u5-X09']::text[],false,'{"seq":18,"concept":"K5-2-u5-C25","difficulty":3,"kind":"mc","stem":"이웃이 까닭을 묻자 할머니가 웃기만 한 장면에서 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니는 말보다 꾸준한 실천으로 마음을 보여 주려 했을 것이다","correct":true},{"t":"할머니는 이웃의 말을 못 들었다","mis":"K5-2-u5-X25"},{"t":"할머니는 이웃을 싫어했다","mis":"K5-2-u5-X09"},{"t":"웃었으니 아무 뜻도 없다","mis":"K5-2-u5-X25"}],"explanation":["상황과 맞지 않아요.","근거가 없어요.","웃음에도 뜻이 담겨요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#19','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C32',3,'mc','auto','「마음에 바람이 숭숭 들어와.」라는 카드를 보고 할 행동으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X18','K5-2-u5-X32','K5-2-u5-X33']::text[],false,'{"seq":19,"concept":"K5-2-u5-C32","difficulty":3,"kind":"mc","stem":"「마음에 바람이 숭숭 들어와.」라는 카드를 보고 할 행동으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"허전하거나 쓸쓸한 마음인지 짐작한 뒤 친구에게 물어 확인한다","correct":true},{"t":"바람이 분다는 날씨 이야기로 여긴다","mis":"K5-2-u5-X18"},{"t":"짐작만 하고 내 생각을 친구에게 우긴다","mis":"K5-2-u5-X32"},{"t":"카드가 이상하다고 놀린다","mis":"K5-2-u5-X33"}],"explanation":["겉뜻으로 읽었어요.","우기지 않아요.","짐작하고 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#20','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C34',3,'mc','auto','과자 광고에 「한 입이면 온 가족이 웃어요!」라는 말이 있어요. 추론하며 볼 때 가장 알맞은 생각은 어느 것인가요?',ARRAY['K5-2-u5-X34','K5-2-u5-X18','K5-2-u5-X22']::text[],false,'{"seq":20,"concept":"K5-2-u5-C34","difficulty":3,"kind":"mc","stem":"과자 광고에 「한 입이면 온 가족이 웃어요!」라는 말이 있어요. 추론하며 볼 때 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"과자를 사게 하려는 만든 사람의 의도가 담겨 있으니 말 그대로 믿기 전에 따져 본다","correct":true},{"t":"광고는 글이 아니라서 추론할 필요가 없다","mis":"K5-2-u5-X34"},{"t":"한 입 먹으면 정말 모두 웃는다","mis":"K5-2-u5-X18"},{"t":"광고 문구는 다 거짓이니 아무것도 읽지 않는다","mis":"K5-2-u5-X22"}],"explanation":["광고도 추론하며 봐요.","겉뜻 그대로 믿었어요.","의도를 짐작하며 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#21','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C28',3,'mc','auto','이야기 속 인물이 「늘 하던 대로 해야지.」라고 말했지만 이야기 끝에서 세상이 바뀌었어요. 글쓴이의 의도에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X28','K5-2-u5-X27','K5-2-u5-X13']::text[],false,'{"seq":21,"concept":"K5-2-u5-C28","difficulty":3,"kind":"mc","stem":"이야기 속 인물이 「늘 하던 대로 해야지.」라고 말했지만 이야기 끝에서 세상이 바뀌었어요. 글쓴이의 의도에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"인물의 말이 바뀌어야 할 생각이었음을 보여 주려 했을 수 있다","correct":true},{"t":"인물의 말이 곧 글쓴이의 의도이다","mis":"K5-2-u5-X28"},{"t":"끝에서 바뀐 것은 의도와 관계없다","mis":"K5-2-u5-X27"},{"t":"의도는 알 수 없으니 생각하지 않는다","mis":"K5-2-u5-X13"}],"explanation":["같지 않을 수 있어요.","끝의 변화가 단서예요.","정반대일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#22','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C21',3,'mc','auto','함축된 표현의 뜻을 짐작하는 방법을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u5-X18','K5-2-u5-X20','K5-2-u5-X07']::text[],false,'{"seq":22,"concept":"K5-2-u5-C21","difficulty":3,"kind":"mc","stem":"함축된 표현의 뜻을 짐작하는 방법을 바르게 말한 것은 어느 것인가요?","options":[{"t":"사전에서의 뜻에서 출발해 앞뒤 단서와 내 경험·지식으로 글에서의 뜻을 찾는다","correct":true},{"t":"사전 뜻만 찾아 그대로 쓴다","mis":"K5-2-u5-X18"},{"t":"그 낱말 하나만 보고 떠오르는 대로 정한다","mis":"K5-2-u5-X20"},{"t":"경험은 떠올리지 않고 글자 모양만 본다","mis":"K5-2-u5-X07"}],"explanation":["사전 뜻에서 멈췄어요.","앞뒤를 봐요.","세 가지를 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#23','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C1',4,'essay','teacher','「텃밭의 빈 의자」에서 할아버지가 한동안 나오지 않은 까닭을 짐작해 쓰고, 짐작의 근거가 된 글의 단서와 내 경험이나 지식을 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u5-C1","difficulty":4,"kind":"essay","stem":"「텃밭의 빈 의자」에서 할아버지가 한동안 나오지 않은 까닭을 짐작해 쓰고, 짐작의 근거가 된 글의 단서와 내 경험이나 지식을 함께 쓰세요.","answer_guide":{"answer":"예: 할아버지는 몸이 아파 한동안 쉬셨을 것 같다. 의자가 비고 늘 쓰던 모자도 보이지 않다가 며칠 뒤 다시 돌아왔다는 단서가 있다. 우리 할머니도 감기로 며칠 동안 산책을 나오지 못하신 적이 있어서 그렇게 짐작했다.","scoring_points":["까닭을 짐작했는가","글의 단서를 썼는가","경험이나 지식을 썼는가"]},"explanation":["짐작해요.","단서를 써요.","경험을 더해요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#24','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C13',4,'essay','teacher','「골목의 화분」에서 글쓴이의 생각을 내 말로 쓰고, 그 생각을 내 생활에서 실천할 방법을 한 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u5-C13","difficulty":4,"kind":"essay","stem":"「골목의 화분」에서 글쓴이의 생각을 내 말로 쓰고, 그 생각을 내 생활에서 실천할 방법을 한 가지 쓰세요.","answer_guide":{"answer":"예: 작은 일이라도 꾸준히 하면 둘레가 바뀐다는 생각이다. 나는 날마다 아침에 교실 창문을 열고 화분에 물을 주는 일을 꾸준히 해서 우리 반을 더 상쾌하게 만들겠다.","scoring_points":["글쓴이의 생각을 내 말로 썼는가","실천 방법을 썼는가","방법이 생각과 이어지는가"]},"explanation":["내 말로 써요.","실천 방법이에요.","이어지게 써요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_a#25','kor',5,2,'u5','','g5_2_kor_u5_review_a','unit_review','K5-2-u5-C2',4,'essay','teacher','이 단원에서 배운 추론, 함축된 표현, 글쓴이의 의도의 뜻을 각각 쓰고, 셋이 어떻게 이어지는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u5-C2","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 추론, 함축된 표현, 글쓴이의 의도의 뜻을 각각 쓰고, 셋이 어떻게 이어지는지 쓰세요.","answer_guide":{"answer":"예: 추론은 글에 드러나지 않은 내용을 단서와 경험·지식으로 짐작하는 것이다. 함축된 표현은 뜻이 숨겨져 있거나 여러 뜻이 담긴 표현이다. 글쓴이의 의도는 글쓴이가 독자에게 전하고 싶은 생각이다. 추론하며 함축된 표현의 숨은 뜻을 찾으면 글쓴이의 의도까지 깊이 알 수 있다.","scoring_points":["세 낱말의 뜻을 썼는가","셋의 이어짐을 썼는가","뜻이 바른가"]},"explanation":["뜻을 써요.","이어짐을 써요.","바르게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#1','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C2',1,'ox','auto','추론은 글에 쓰인 문장을 그대로 찾아 옮겨 적는 일이에요.',ARRAY['K5-2-u5-X02']::text[],false,'{"seq":1,"concept":"K5-2-u5-C2","difficulty":1,"kind":"ox","stem":"추론은 글에 쓰인 문장을 그대로 찾아 옮겨 적는 일이에요.","answer":"X","reason_options":[{"t":"쓰여 있지 않은 내용을 단서와 경험·지식으로 짐작하는 일이기 때문에","correct":true},{"t":"글에 쓰인 것만 읽어야 하기 때문에","mis":"K5-2-u5-X02"}],"mis":"K5-2-u5-X02","explanation":["옮겨 적기가 아니에요.","쓰여 있지 않은 것을 짐작해요.","추론의 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#2','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C36',1,'mc','auto','「암」과 「닭」이 어울린 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K5-2-u5-X36']::text[],false,'{"seq":2,"concept":"K5-2-u5-C36","difficulty":1,"kind":"mc","stem":"「암」과 「닭」이 어울린 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"암탉","correct":true},{"t":"암닭","mis":"K5-2-u5-X36"},{"t":"암달","mis":"K5-2-u5-X36"},{"t":"앙닭","mis":"K5-2-u5-X36"}],"explanation":["ㅎ 소리를 살리지 않았어요.","받침이 빠졌어요.","ㅎ 소리가 덧나 암탉이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#3','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C18',1,'ox','auto','함축된 표현은 사전에서의 뜻에서 출발해 글에서의 뜻을 찾아요.',ARRAY['K5-2-u5-X18']::text[],false,'{"seq":3,"concept":"K5-2-u5-C18","difficulty":1,"kind":"ox","stem":"함축된 표현은 사전에서의 뜻에서 출발해 글에서의 뜻을 찾아요.","answer":"O","reason_options":[{"t":"사전 뜻으로 읽어 어색한 곳에서 글의 흐름에 맞는 숨은 뜻을 찾기 때문에","correct":true},{"t":"사전 뜻과 글에서의 뜻은 언제나 같기 때문에","mis":"K5-2-u5-X18"}],"mis":"K5-2-u5-X18","explanation":["출발점은 사전 뜻이에요.","글의 흐름에 맞춰요.","글에서의 뜻으로 넓혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#4','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C13',1,'ox','auto','글쓴이의 생각은 글에 직접 쓰여 있지 않을 때가 많아요.',ARRAY['K5-2-u5-X13']::text[],false,'{"seq":4,"concept":"K5-2-u5-C13","difficulty":1,"kind":"ox","stem":"글쓴이의 생각은 글에 직접 쓰여 있지 않을 때가 많아요.","answer":"O","reason_options":[{"t":"인물의 말과 행동, 변화, 제목 같은 단서를 모아 짐작하기 때문에","correct":true},{"t":"늘 마지막 문장에 그대로 쓰여 있기 때문에","mis":"K5-2-u5-X13"}],"mis":"K5-2-u5-X13","explanation":["직접 쓰여 있지 않을 때가 많아요.","단서를 모아요.","짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#5','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C15',1,'mc','auto','이야기 처음에 골목은 어떤 모습이었나요?',ARRAY['K5-2-u5-X15']::text[],false,'{"seq":5,"concept":"K5-2-u5-C15","difficulty":1,"kind":"mc","stem":"이야기 처음에 골목은 어떤 모습이었나요?","options":[{"t":"늘 회색빛이고 사람들이 고개를 숙인 채 빠르게 지나갔다","correct":true},{"t":"꽃 화분이 줄지어 서 있었다","mis":"K5-2-u5-X15"},{"t":"사람들이 꽃 이름을 물었다","mis":"K5-2-u5-X15"},{"t":"계절마다 옷을 갈아입었다","mis":"K5-2-u5-X15"}],"explanation":["나중 모습이에요.","나중 모습이에요.","처음엔 회색빛이었어요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#6','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C31',1,'mc','auto','감정 카드 뒷면에 쓰기에 알맞은 문장은 어느 것인가요?',ARRAY['K5-2-u5-X31']::text[],false,'{"seq":6,"concept":"K5-2-u5-C31","difficulty":1,"kind":"mc","stem":"감정 카드 뒷면에 쓰기에 알맞은 문장은 어느 것인가요?","options":[{"t":"「마음에 먹구름이 몰려왔어.」","correct":true},{"t":"「나는 슬퍼.」","mis":"K5-2-u5-X31"},{"t":"「나는 화가 나.」","mis":"K5-2-u5-X31"},{"t":"「기분이 좋아.」","mis":"K5-2-u5-X31"}],"explanation":["감정 낱말이에요.","감정 낱말이에요.","빗대어 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#7','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C34',1,'ox','auto','추론하며 읽는 힘은 뉴스나 광고를 볼 때에도 필요해요.',ARRAY['K5-2-u5-X34']::text[],false,'{"seq":7,"concept":"K5-2-u5-C34","difficulty":1,"kind":"ox","stem":"추론하며 읽는 힘은 뉴스나 광고를 볼 때에도 필요해요.","answer":"O","reason_options":[{"t":"뉴스·광고·영상에도 드러나지 않은 뜻과 만든 사람의 의도가 있기 때문에","correct":true},{"t":"추론하며 읽기는 국어 교과서 글에만 쓰이기 때문에","mis":"K5-2-u5-X34"}],"mis":"K5-2-u5-X34","explanation":["어디에서나 필요해요.","만든 사람의 의도도 있어요.","쓰인 것 너머까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#8','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C6',1,'mc','auto','할아버지에게 무슨 일이 생겼다고 짐작하게 하는 단서는 어느 것인가요?',ARRAY['K5-2-u5-X06']::text[],false,'{"seq":8,"concept":"K5-2-u5-C6","difficulty":1,"kind":"mc","stem":"할아버지에게 무슨 일이 생겼다고 짐작하게 하는 단서는 어느 것인가요?","options":[{"t":"의자가 비어 있고 모자도 보이지 않았다","correct":true},{"t":"텃밭에 상추가 있었다","mis":"K5-2-u5-X06"},{"t":"의자가 낡았다","mis":"K5-2-u5-X06"},{"t":"아이들이 물을 주었다","mis":"K5-2-u5-X06"}],"explanation":["변함없는 사실이에요.","처음부터 그랬어요.","빈 의자와 모자가 단서예요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#9','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C19',2,'mc','auto','「골목이 옷을 갈아입어요.」를 사전 뜻대로 읽으면 어색한 까닭은 무엇인가요?',ARRAY['K5-2-u5-X19']::text[],false,'{"seq":9,"concept":"K5-2-u5-C19","difficulty":2,"kind":"mc","stem":"「골목이 옷을 갈아입어요.」를 사전 뜻대로 읽으면 어색한 까닭은 무엇인가요?","options":[{"t":"골목은 옷을 입을 수 없기 때문에","correct":true},{"t":"옷이라는 낱말이 너무 짧기 때문에","mis":"K5-2-u5-X19"},{"t":"골목은 회색이기 때문에","mis":"K5-2-u5-X19"},{"t":"어색한 곳이 없기 때문에","mis":"K5-2-u5-X19"}],"explanation":["길이와 관계없어요.","까닭이 아니에요.","어색한 곳이 숨은 뜻의 신호예요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#10','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C14',2,'mc','auto','「골목의 화분」에서 글쓴이의 생각을 짐작하게 하는 단서로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X14']::text[],false,'{"seq":10,"concept":"K5-2-u5-C14","difficulty":2,"kind":"mc","stem":"「골목의 화분」에서 글쓴이의 생각을 짐작하게 하는 단서로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"세 해 뒤 이웃들도 화분을 내놓고 사람들이 걸음을 늦추었다는 변화","correct":true},{"t":"할머니 집이 맨 끝에 있다는 것","mis":"K5-2-u5-X14"},{"t":"대문이 있다는 것","mis":"K5-2-u5-X14"},{"t":"봄날이었다는 것","mis":"K5-2-u5-X14"}],"explanation":["작은 사실이에요.","작은 사실이에요.","이야기 끝의 변화가 단서예요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#11','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C36',2,'mc','auto','두 낱말이 어울릴 때 ㅎ 소리가 덧나는 낱말로만 묶은 것은 어느 것인가요?',ARRAY['K5-2-u5-X35','K5-2-u5-X36']::text[],false,'{"seq":11,"concept":"K5-2-u5-C36","difficulty":2,"kind":"mc","stem":"두 낱말이 어울릴 때 ㅎ 소리가 덧나는 낱말로만 묶은 것은 어느 것인가요?","options":[{"t":"수탉, 안팎, 살코기","correct":true},{"t":"볍씨, 햅쌀, 멥쌀","mis":"K5-2-u5-X35"},{"t":"암탉, 좁쌀, 머리카락","mis":"K5-2-u5-X36"},{"t":"멥쌀, 수탉, 안팎","mis":"K5-2-u5-X36"}],"explanation":["ㅂ 소리가 덧나요.","ㅂ 소리가 섞였어요.","ㅎ 소리가 덧나는 낱말이에요."],"asset":{"type":"passage","lines":["벼 + 씨 → 볍씨 · 해 + 쌀 → 햅쌀 · 메 + 쌀 → 멥쌀 · 조 + 쌀 → 좁쌀","수 + 닭 → 수탉 · 암 + 닭 → 암탉","머리 + 가락 → 머리카락 · 안 + 밖 → 안팎 · 살 + 고기 → 살코기"],"title":"두 낱말이 어울릴 때 소리가 덧나는 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#12','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C6',2,'mc','auto','할아버지가 아파서 한동안 나오지 못했다고 짐작할 때 함께 놓고 볼 단서로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X06']::text[],false,'{"seq":12,"concept":"K5-2-u5-C6","difficulty":2,"kind":"mc","stem":"할아버지가 아파서 한동안 나오지 못했다고 짐작할 때 함께 놓고 볼 단서로 알맞은 것은 어느 것인가요?","options":[{"t":"의자가 비어 있다가 며칠 뒤 할아버지가 다시 돌아왔다","correct":true},{"t":"의자가 나무로 되어 있다","mis":"K5-2-u5-X06"},{"t":"아이들이 상추를 심었다","mis":"K5-2-u5-X06"},{"t":"비가 그쳤다","mis":"K5-2-u5-X06"}],"explanation":["짐작과 관계없어요.","짐작과 관계없어요.","비었다가 돌아온 흐름이 단서예요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#13','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C17',2,'mc','auto','「그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요.」에 담긴 숨은 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X18','K5-2-u5-X09']::text[],false,'{"seq":13,"concept":"K5-2-u5-C17","difficulty":2,"kind":"mc","stem":"「그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요.」에 담긴 숨은 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"걱정과 쓸쓸함이 걷히고 모두의 마음이 밝아졌다","correct":true},{"t":"그날 날씨만 알려 준다","mis":"K5-2-u5-X18"},{"t":"상추가 비에 젖었다","mis":"K5-2-u5-X18"},{"t":"할아버지가 해를 싫어한다","mis":"K5-2-u5-X09"}],"explanation":["겉뜻으로만 읽었어요.","겉뜻으로만 읽었어요.","마음의 날씨를 빗댔어요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#14','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C26',2,'mc','auto','반대되는 말을 맞세워 뜻을 전한 문장은 어느 것인가요?',ARRAY['K5-2-u5-X26']::text[],false,'{"seq":14,"concept":"K5-2-u5-C26","difficulty":2,"kind":"mc","stem":"반대되는 말을 맞세워 뜻을 전한 문장은 어느 것인가요?","options":[{"t":"「동생은 키는 작아도 마음은 누구보다 컸다.」","correct":true},{"t":"「동생은 키가 작다.」","mis":"K5-2-u5-X26"},{"t":"「동생은 밥을 많이 먹었다.」","mis":"K5-2-u5-X26"},{"t":"「동생은 마음이 착하다.」","mis":"K5-2-u5-X26"}],"explanation":["맞세우지 않았어요.","맞세우지 않았어요.","작다와 크다를 맞세웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#15','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C16',2,'mc','auto','문단의 중심 내용을 간추리는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X16']::text[],false,'{"seq":15,"concept":"K5-2-u5-C16","difficulty":2,"kind":"mc","stem":"문단의 중심 내용을 간추리는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"문단마다 중심 문장을 찾아 간추린다","correct":true},{"t":"예를 든 문장을 모두 옮겨 쓴다","mis":"K5-2-u5-X16"},{"t":"문단의 첫 낱말만 쓴다","mis":"K5-2-u5-X16"},{"t":"가장 긴 문장을 고른다","mis":"K5-2-u5-X16"}],"explanation":["뒷받침 문장이에요.","뜻이 담기지 않아요.","중심 문장을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#16','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C30',2,'mc','auto','「눈앞이 캄캄해졌어.」라는 표현이 나타내는 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X18','K5-2-u5-X30']::text[],false,'{"seq":16,"concept":"K5-2-u5-C30","difficulty":2,"kind":"mc","stem":"「눈앞이 캄캄해졌어.」라는 표현이 나타내는 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"어찌할 바를 몰라 막막한 마음","correct":true},{"t":"불이 꺼져서 깜깜하다","mis":"K5-2-u5-X18"},{"t":"신나서 들뜬 마음","mis":"K5-2-u5-X30"},{"t":"배부른 마음","mis":"K5-2-u5-X30"}],"explanation":["겉뜻으로 읽었어요.","반대 마음이에요.","막막한 마음을 빗댔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#17','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C27',3,'mc','auto','「텃밭의 빈 의자」에서 글쓴이의 의도를 짐작하게 하는 단서로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X27']::text[],false,'{"seq":17,"concept":"K5-2-u5-C27","difficulty":3,"kind":"mc","stem":"「텃밭의 빈 의자」에서 글쓴이의 의도를 짐작하게 하는 단서로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"아이들이 쪽지를 놓고, 할아버지가 그것을 읽으며 한참 말이 없었다는 장면","correct":true},{"t":"의자가 텃밭 끝에 있었다는 것","mis":"K5-2-u5-X27"},{"t":"상추를 아이들이 심었다는 것","mis":"K5-2-u5-X27"},{"t":"의자가 나무로 만들어졌다는 것","mis":"K5-2-u5-X27"}],"explanation":["작은 사실이에요.","작은 사실이에요.","중심 장면이 단서예요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#18','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C15',3,'mc','auto','이야기 처음과 끝을 견주어 골목 사람들의 모습이 어떻게 달라졌는지 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u5-X15','K5-2-u5-X09']::text[],false,'{"seq":18,"concept":"K5-2-u5-C15","difficulty":3,"kind":"mc","stem":"이야기 처음과 끝을 견주어 골목 사람들의 모습이 어떻게 달라졌는지 바르게 말한 것은 어느 것인가요?","options":[{"t":"고개를 숙이고 빠르게 지나가던 사람들이 걸음을 늦추고 꽃 이름을 묻게 되었다","correct":true},{"t":"처음과 끝이 똑같다","mis":"K5-2-u5-X15"},{"t":"꽃 이름을 묻던 사람들이 빠르게 지나가게 되었다","mis":"K5-2-u5-X15"},{"t":"사람들이 골목을 떠났다","mis":"K5-2-u5-X09"}],"explanation":["달라졌어요.","차례가 거꾸로예요.","처음과 끝을 견줘요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#19','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C31',3,'mc','auto','감정 카드 활동에서 감정 낱말을 쓰지 않기로 약속한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X31','K5-2-u5-X22']::text[],false,'{"seq":19,"concept":"K5-2-u5-C31","difficulty":3,"kind":"mc","stem":"감정 카드 활동에서 감정 낱말을 쓰지 않기로 약속한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"친구가 단서로 마음을 짐작하며 추론하는 기회를 주기 위해서","correct":true},{"t":"감정 낱말은 나쁜 말이라서","mis":"K5-2-u5-X31"},{"t":"글자를 아끼려고","mis":"K5-2-u5-X31"},{"t":"감정을 숨겨 아무도 모르게 하려고","mis":"K5-2-u5-X22"}],"explanation":["나쁜 말이 아니에요.","까닭이 아니에요.","숨기려는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#20','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C34',3,'mc','auto','뉴스나 영상을 볼 때 추론하며 보는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X34','K5-2-u5-X09']::text[],false,'{"seq":20,"concept":"K5-2-u5-C34","difficulty":3,"kind":"mc","stem":"뉴스나 영상을 볼 때 추론하며 보는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"화면에 드러나지 않은 까닭과 만든 사람이 전하려는 뜻을 단서로 짐작한다","correct":true},{"t":"보이는 장면만 그대로 믿고 넘긴다","mis":"K5-2-u5-X34"},{"t":"추론은 글에서만 하니 영상은 그냥 본다","mis":"K5-2-u5-X34"},{"t":"떠오르는 대로 지어내 친구에게 퍼뜨린다","mis":"K5-2-u5-X09"}],"explanation":["그대로 믿지 않아요.","영상도 추론해요.","단서로 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#21','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C26',3,'mc','auto','「그 아이는 가장 작은 손으로 가장 큰 일을 해냈어요.」에 대한 설명으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X18','K5-2-u5-X26','K5-2-u5-X25']::text[],false,'{"seq":21,"concept":"K5-2-u5-C26","difficulty":3,"kind":"mc","stem":"「그 아이는 가장 작은 손으로 가장 큰 일을 해냈어요.」에 대한 설명으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작다와 크다를 맞세워 어린아이의 행동이 큰 뜻을 지녔음을 강조한다","correct":true},{"t":"손 크기를 알려 주는 문장이다","mis":"K5-2-u5-X18"},{"t":"앞뒤가 맞지 않는 틀린 문장이다","mis":"K5-2-u5-X26"},{"t":"아이가 일을 하지 않았다는 뜻이다","mis":"K5-2-u5-X25"}],"explanation":["겉뜻으로 읽었어요.","틀린 문장이 아니에요.","맞세워 강조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#22','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C12',3,'mc','auto','글에 생략된 내용을 짐작하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X12','K5-2-u5-X09']::text[],false,'{"seq":22,"concept":"K5-2-u5-C12","difficulty":3,"kind":"mc","stem":"글에 생략된 내용을 짐작하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓰인 사건 사이의 까닭과 마음을 채워 글을 더 깊이 이해하려고","correct":true},{"t":"글을 더 길게 다시 쓰려고","mis":"K5-2-u5-X12"},{"t":"생략된 내용은 몰라도 되니까","mis":"K5-2-u5-X12"},{"t":"글쓴이의 실수를 찾으려고","mis":"K5-2-u5-X09"}],"explanation":["까닭이 아니에요.","알아야 깊이 읽어요.","빈 곳을 채워 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#23','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C18',4,'essay','teacher','「골목의 화분」에서 함축된 표현 하나를 골라 사전에서의 뜻과 글에서의 뜻을 쓰고, 그 표현을 쓴 까닭을 짐작해 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u5-C18","difficulty":4,"kind":"essay","stem":"「골목의 화분」에서 함축된 표현 하나를 골라 사전에서의 뜻과 글에서의 뜻을 쓰고, 그 표현을 쓴 까닭을 짐작해 쓰세요.","answer_guide":{"answer":"예: 「옷을 갈아입어요」 — 사전에서의 뜻은 입고 있던 옷을 벗고 다른 옷을 입는 것이다. 글에서의 뜻은 계절마다 다른 꽃이 피어 골목의 모습이 달라진다는 것이다. 회색이던 골목이 살아난 모습을 생생하게 느끼게 하려고 이 표현을 썼을 것이다.","scoring_points":["표현을 골랐는가","두 뜻을 썼는가","쓴 까닭을 짐작했는가"]},"explanation":["하나를 골라요.","두 뜻을 써요.","까닭을 짐작해요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#24','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C30',4,'essay','teacher','「텃밭의 빈 의자」의 아이들이 되어 할아버지에게 보낼 쪽지를 함축된 표현을 넣어 쓰고, 그 표현에 담은 마음을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u5-C30","difficulty":4,"kind":"essay","stem":"「텃밭의 빈 의자」의 아이들이 되어 할아버지에게 보낼 쪽지를 함축된 표현을 넣어 쓰고, 그 표현에 담은 마음을 쓰세요.","answer_guide":{"answer":"예: 「할아버지, 할아버지가 안 계신 텃밭은 해가 뜨지 않은 아침 같아요.」 — 할아버지가 안 계셔서 텃밭이 쓸쓸하고 할아버지가 무척 보고 싶다는 마음을 담았다.","scoring_points":["쪽지를 썼는가","함축된 표현을 넣었는가","담은 마음을 썼는가"]},"explanation":["쪽지를 써요.","빗대어 써요.","마음을 밝혀요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_b#25','kor',5,2,'u5','','g5_2_kor_u5_review_b','unit_review','K5-2-u5-C25',4,'essay','teacher','친구나 가족이 한 말 가운데 겉뜻과 숨은 뜻이 달랐던 말을 하나 떠올려 쓰고, 상황을 단서로 숨은 뜻을 어떻게 알아챘는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u5-C25","difficulty":4,"kind":"essay","stem":"친구나 가족이 한 말 가운데 겉뜻과 숨은 뜻이 달랐던 말을 하나 떠올려 쓰고, 상황을 단서로 숨은 뜻을 어떻게 알아챘는지 쓰세요.","answer_guide":{"answer":"예: 시험 공부를 하다가 게임을 하고 있을 때 엄마가 「참 잘하는 짓이다.」라고 하셨다. 겉뜻은 칭찬이지만 공부해야 할 때 게임을 하고 있던 상황과 엄마의 굳은 표정을 보고 공부하라는 꾸중이라는 것을 알아챘다.","scoring_points":["말을 하나 떠올렸는가","겉뜻과 숨은 뜻을 썼는가","상황을 단서로 썼는가"]},"explanation":["말을 떠올려요.","두 뜻을 써요.","상황이 단서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#1','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C8',1,'mc','auto','추론한 내용을 말할 때 함께 말해야 하는 것은 무엇인가요?',ARRAY['K5-2-u5-X08']::text[],false,'{"seq":1,"concept":"K5-2-u5-C8","difficulty":1,"kind":"mc","stem":"추론한 내용을 말할 때 함께 말해야 하는 것은 무엇인가요?","options":[{"t":"근거","correct":true},{"t":"제목","mis":"K5-2-u5-X08"},{"t":"쪽수","mis":"K5-2-u5-X08"},{"t":"글쓴이의 나이","mis":"K5-2-u5-X08"}],"explanation":["짐작의 까닭이 아니에요.","짐작의 까닭이 아니에요.","왜 그렇게 생각했는지 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#2','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C36',1,'mc','auto','바르게 쓴 낱말은 어느 것인가요?',ARRAY['K5-2-u5-X36']::text[],false,'{"seq":2,"concept":"K5-2-u5-C36","difficulty":1,"kind":"mc","stem":"바르게 쓴 낱말은 어느 것인가요?","options":[{"t":"머리카락","correct":true},{"t":"머리가락","mis":"K5-2-u5-X36"},{"t":"머릿가락","mis":"K5-2-u5-X36"},{"t":"머리까락","mis":"K5-2-u5-X36"}],"explanation":["ㅎ 소리를 살리지 않았어요.","사이에 받침을 넣었어요.","소리 나는 대로 머리카락이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#3','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C17',1,'mc','auto','함축된 표현이 쓰인 문장은 어느 것인가요?',ARRAY['K5-2-u5-X18']::text[],false,'{"seq":3,"concept":"K5-2-u5-C17","difficulty":1,"kind":"mc","stem":"함축된 표현이 쓰인 문장은 어느 것인가요?","options":[{"t":"「그 친구는 우리 반의 해님이야.」","correct":true},{"t":"「해는 동쪽에서 떠.」","mis":"K5-2-u5-X18"},{"t":"「오늘은 해가 쨍쨍해.」","mis":"K5-2-u5-X18"},{"t":"「해가 지면 어두워져.」","mis":"K5-2-u5-X18"}],"explanation":["사전 뜻 그대로예요.","사전 뜻 그대로예요.","친구를 해님에 빗댔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#4','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C14',1,'mc','auto','글쓴이의 생각을 짐작할 때 살펴볼 단서는 어느 것인가요?',ARRAY['K5-2-u5-X14']::text[],false,'{"seq":4,"concept":"K5-2-u5-C14","difficulty":1,"kind":"mc","stem":"글쓴이의 생각을 짐작할 때 살펴볼 단서는 어느 것인가요?","options":[{"t":"이야기 끝에 일어난 변화","correct":true},{"t":"글쓴이의 키","mis":"K5-2-u5-X14"},{"t":"글자의 크기","mis":"K5-2-u5-X14"},{"t":"종이의 색깔","mis":"K5-2-u5-X14"}],"explanation":["글과 관계없어요.","글과 관계없어요.","이야기 끝의 변화를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#5','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C23',1,'mc','auto','「골목의 화분」에서 가장 나중에 일어난 일은 무엇인가요?',ARRAY['K5-2-u5-X23']::text[],false,'{"seq":5,"concept":"K5-2-u5-C23","difficulty":1,"kind":"mc","stem":"「골목의 화분」에서 가장 나중에 일어난 일은 무엇인가요?","options":[{"t":"사람들이 걸음을 늦추고 꽃 이름을 물었다","correct":true},{"t":"할머니가 첫 화분을 내놓았다","mis":"K5-2-u5-X23"},{"t":"이웃이 할머니에게 까닭을 물었다","mis":"K5-2-u5-X23"},{"t":"화분이 하루하루 하나씩 늘었다","mis":"K5-2-u5-X23"}],"explanation":["처음 일이에요.","가운데 일이에요.","맨 나중 모습이에요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#6','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C32',1,'ox','auto','친구의 마음을 짐작했으면 확인할 필요 없이 내 짐작대로 말하면 돼요.',ARRAY['K5-2-u5-X32']::text[],false,'{"seq":6,"concept":"K5-2-u5-C32","difficulty":1,"kind":"ox","stem":"친구의 마음을 짐작했으면 확인할 필요 없이 내 짐작대로 말하면 돼요.","answer":"X","reason_options":[{"t":"함축된 표현은 여러 뜻으로 읽힐 수 있어 친구에게 물어 확인해야 하기 때문에","correct":true},{"t":"내 짐작은 늘 맞기 때문에","mis":"K5-2-u5-X32"}],"mis":"K5-2-u5-X32","explanation":["확인이 필요해요.","물어봐요.","친구의 설명을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#7','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C34',1,'mc','auto','추론하며 읽으면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X34']::text[],false,'{"seq":7,"concept":"K5-2-u5-C34","difficulty":1,"kind":"mc","stem":"추론하며 읽으면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"글에 쓰인 것 너머까지 깊이 읽을 수 있다","correct":true},{"t":"글을 읽지 않아도 내용을 안다","mis":"K5-2-u5-X34"},{"t":"국어 시간에만 도움이 된다","mis":"K5-2-u5-X34"},{"t":"글자를 빨리 쓸 수 있다","mis":"K5-2-u5-X34"}],"explanation":["읽어야 알아요.","생활 곳곳에서 도움이 돼요.","깊이 읽을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#8','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C15',1,'mc','auto','아이들이 자꾸 의자 쪽을 돌아본 모습에서 짐작할 수 있는 마음은 무엇인가요?',ARRAY['K5-2-u5-X09','K5-2-u5-X15']::text[],false,'{"seq":8,"concept":"K5-2-u5-C15","difficulty":1,"kind":"mc","stem":"아이들이 자꾸 의자 쪽을 돌아본 모습에서 짐작할 수 있는 마음은 무엇인가요?","options":[{"t":"할아버지를 걱정하고 기다리는 마음","correct":true},{"t":"의자를 가지고 싶은 마음","mis":"K5-2-u5-X09"},{"t":"상추가 싫은 마음","mis":"K5-2-u5-X09"},{"t":"아무 마음도 없음","mis":"K5-2-u5-X15"}],"explanation":["근거가 없어요.","근거가 없어요.","돌아보는 몸짓이 단서예요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#9','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C20',2,'mc','auto','「회색」의 숨은 뜻을 짐작하게 하는 앞뒤 단서는 어느 것인가요?',ARRAY['K5-2-u5-X20']::text[],false,'{"seq":9,"concept":"K5-2-u5-C20","difficulty":2,"kind":"mc","stem":"「회색」의 숨은 뜻을 짐작하게 하는 앞뒤 단서는 어느 것인가요?","options":[{"t":"사람들은 고개를 숙인 채 빠르게 지나갔지요","correct":true},{"t":"맨 끝 집 할머니","mis":"K5-2-u5-X20"},{"t":"다음 날에도","mis":"K5-2-u5-X20"},{"t":"세 해가 지나자","mis":"K5-2-u5-X20"}],"explanation":["누구인지만 알려 줘요.","때를 알려 줘요.","쓸쓸한 분위기가 단서예요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#10','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C12',2,'mc','auto','할머니가 날마다 화분을 내놓은 까닭으로 알맞은 짐작은 어느 것인가요?',ARRAY['K5-2-u5-X09','K5-2-u5-X01']::text[],false,'{"seq":10,"concept":"K5-2-u5-C12","difficulty":2,"kind":"mc","stem":"할머니가 날마다 화분을 내놓은 까닭으로 알맞은 짐작은 어느 것인가요?","options":[{"t":"회색빛 골목을 밝고 따뜻하게 바꾸고 싶었다","correct":true},{"t":"화분을 팔아 돈을 벌고 싶었다","mis":"K5-2-u5-X09"},{"t":"집 안이 좁아 화분을 둘 곳이 없었다","mis":"K5-2-u5-X09"},{"t":"까닭이 쓰여 있지 않으니 짐작하면 안 된다","mis":"K5-2-u5-X01"}],"explanation":["근거가 없어요.","근거가 없어요.","골목의 변화가 단서예요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#11','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C36',2,'error','auto','친구가 쓴 문장이에요. 낱말을 바르게 쓰지 않은 것은 어느 것인가요?',ARRAY['K5-2-u5-X36','K5-2-u5-X35']::text[],false,'{"seq":11,"concept":"K5-2-u5-C36","difficulty":2,"kind":"error","stem":"친구가 쓴 문장이에요. 낱말을 바르게 쓰지 않은 것은 어느 것인가요?","options":[{"t":"「안밖을 깨끗이 청소했어요.」","correct":true,"mis_target":"K5-2-u5-X36"},{"t":"「살코기로 국을 끓였어요.」","mis":"K5-2-u5-X35"},{"t":"「수탉이 아침마다 울어요.」","mis":"K5-2-u5-X35"}],"explanation":["바르게 썼어요.","바르게 썼어요.","안팎이 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#12','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C8',2,'mc','auto','「텃밭의 빈 의자」를 읽고 근거와 함께 짐작한 말은 어느 것인가요?',ARRAY['K5-2-u5-X08','K5-2-u5-X01']::text[],false,'{"seq":12,"concept":"K5-2-u5-C8","difficulty":2,"kind":"mc","stem":"「텃밭의 빈 의자」를 읽고 근거와 함께 짐작한 말은 어느 것인가요?","options":[{"t":"「쪽지를 한 장씩 펴 보며 말이 없었다니, 할아버지는 마음이 뭉클했을 거야.」","correct":true},{"t":"「할아버지는 그냥 졸렸을 거야.」","mis":"K5-2-u5-X08"},{"t":"「할아버지는 쪽지가 귀찮았을 거야. 느낌이 그래.」","mis":"K5-2-u5-X08"},{"t":"「쓰여 있지 않으니 모르겠어.」","mis":"K5-2-u5-X01"}],"explanation":["근거가 없어요.","느낌은 근거가 아니에요.","장면을 근거로 들었어요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#13','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C19',2,'mc','auto','「상추가 할아버지를 기다려요.」를 사전 뜻대로 읽으면 어색한 곳은 어디인가요?',ARRAY['K5-2-u5-X19']::text[],false,'{"seq":13,"concept":"K5-2-u5-C19","difficulty":2,"kind":"mc","stem":"「상추가 할아버지를 기다려요.」를 사전 뜻대로 읽으면 어색한 곳은 어디인가요?","options":[{"t":"상추가 사람을 기다린다는 것","correct":true},{"t":"쪽지에 쓴 것","mis":"K5-2-u5-X19"},{"t":"끝이 「요」로 끝난 것","mis":"K5-2-u5-X19"},{"t":"어색한 곳이 없다","mis":"K5-2-u5-X19"}],"explanation":["어색하지 않아요.","어색하지 않아요.","상추는 기다릴 수 없어 숨은 뜻을 찾아요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#14','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C29',2,'ox','auto','해석은 사람마다 다를 수 있으니 글 속 근거와 맞지 않는 해석도 모두 알맞아요.',ARRAY['K5-2-u5-X29']::text[],false,'{"seq":14,"concept":"K5-2-u5-C29","difficulty":2,"kind":"ox","stem":"해석은 사람마다 다를 수 있으니 글 속 근거와 맞지 않는 해석도 모두 알맞아요.","answer":"X","reason_options":[{"t":"해석은 여럿일 수 있지만 글 속 근거에 맞아야 하기 때문에","correct":true},{"t":"내 해석이면 근거가 없어도 되기 때문에","mis":"K5-2-u5-X29"}],"mis":"K5-2-u5-X29","explanation":["근거와 맞아야 해요.","근거를 따져요.","맞지 않으면 다시 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#15','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C23',2,'mc','auto','「텃밭의 빈 의자」의 사건을 차례대로 늘어놓은 것은 어느 것인가요?',ARRAY['K5-2-u5-X23']::text[],false,'{"seq":15,"concept":"K5-2-u5-C23","difficulty":2,"kind":"mc","stem":"「텃밭의 빈 의자」의 사건을 차례대로 늘어놓은 것은 어느 것인가요?","options":[{"t":"할아버지가 의자에 앉음 → 의자가 빔 → 쪽지가 놓임 → 할아버지가 돌아옴","correct":true},{"t":"쪽지가 놓임 → 의자가 빔 → 할아버지가 의자에 앉음 → 할아버지가 돌아옴","mis":"K5-2-u5-X23"},{"t":"할아버지가 돌아옴 → 의자가 빔 → 쪽지가 놓임 → 할아버지가 의자에 앉음","mis":"K5-2-u5-X23"},{"t":"의자가 빔 → 할아버지가 돌아옴 → 할아버지가 의자에 앉음 → 쪽지가 놓임","mis":"K5-2-u5-X23"}],"explanation":["차례가 섞였어요.","차례가 섞였어요.","일어난 차례대로예요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#16','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C32',2,'mc','auto','친구의 감정 카드를 보고 짐작한 뒤 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X32','K5-2-u5-X31','K5-2-u5-X22']::text[],false,'{"seq":16,"concept":"K5-2-u5-C32","difficulty":2,"kind":"mc","stem":"친구의 감정 카드를 보고 짐작한 뒤 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「혹시 서운했던 거야? 내 짐작이 맞는지 알려 줘.」","correct":true},{"t":"「넌 분명 화난 거야. 아니라고 해도 소용없어.」","mis":"K5-2-u5-X32"},{"t":"「무슨 뜻인지 모르겠으니 감정 낱말로 다시 써.」","mis":"K5-2-u5-X31"},{"t":"「카드 놀이는 장난이야.」","mis":"K5-2-u5-X22"}],"explanation":["우기는 말이에요.","약속과 달라요.","짐작을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#17','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C17',3,'error','auto','「텃밭의 빈 의자」를 읽고 나눈 말이에요. 함축된 표현을 잘못 이해한 말은 어느 것인가요?',ARRAY['K5-2-u5-X18','K5-2-u5-X17']::text[],false,'{"seq":17,"concept":"K5-2-u5-C17","difficulty":3,"kind":"error","stem":"「텃밭의 빈 의자」를 읽고 나눈 말이에요. 함축된 표현을 잘못 이해한 말은 어느 것인가요?","options":[{"t":"「상추가 할아버지를 기다린다니, 상추가 정말 말을 하나 봐.」","correct":true,"mis_target":"K5-2-u5-X18"},{"t":"「비가 그치고 해가 났다는 건 모두의 마음이 밝아졌다는 뜻 같아.」","mis":"K5-2-u5-X17"},{"t":"「상추가 기다린다는 건 아이들이 기다린다는 말이야.」","mis":"K5-2-u5-X17"}],"explanation":["숨은 뜻을 읽었어요.","숨은 뜻을 읽었어요.","겉뜻으로만 읽었어요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#18','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C13',3,'error','auto','「골목의 화분」에서 글쓴이의 생각을 찾은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u5-X13','K5-2-u5-X14']::text[],false,'{"seq":18,"concept":"K5-2-u5-C13","difficulty":3,"kind":"error","stem":"「골목의 화분」에서 글쓴이의 생각을 찾은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「마지막 문장에 글쓴이의 생각이 그대로 적혀 있으니 그것만 읽으면 돼.」","correct":true,"mis_target":"K5-2-u5-X13"},{"t":"「이웃들이 따라 한 변화를 보면 글쓴이의 생각이 보여.」","mis":"K5-2-u5-X14"},{"t":"「옷을 갈아입는다는 표현에 생각이 담겨 있어.」","mis":"K5-2-u5-X14"}],"explanation":["변화가 단서예요.","함축된 표현이 단서예요.","그대로 적혀 있지 않아요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#19','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C33',3,'error','auto','친구가 「가슴에 돌덩이가 얹혔어.」라는 카드를 냈어요. 공감하는 말로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u5-X33','K5-2-u5-X32']::text[],false,'{"seq":19,"concept":"K5-2-u5-C33","difficulty":3,"kind":"error","stem":"친구가 「가슴에 돌덩이가 얹혔어.」라는 카드를 냈어요. 공감하는 말로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「돌덩이가 얹혔다고? 그럼 힘 좀 세겠네!」","correct":true,"mis_target":"K5-2-u5-X33"},{"t":"「마음이 많이 무거웠구나. 무슨 일인지 들어 줄게.」","mis":"K5-2-u5-X32"},{"t":"「걱정되는 일이 있었구나. 나도 같이 생각해 볼게.」","mis":"K5-2-u5-X32"}],"explanation":["마음을 알아줘요.","마음을 알아줘요.","놀리는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#20','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C9',3,'mc','auto','추론과 아무렇게나 상상하기를 가르는 기준으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X09','K5-2-u5-X10']::text[],false,'{"seq":20,"concept":"K5-2-u5-C9","difficulty":3,"kind":"mc","stem":"추론과 아무렇게나 상상하기를 가르는 기준으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"왜 그렇게 생각했는지 단서나 경험·지식으로 말할 수 있는가","correct":true},{"t":"짐작이 재미있는가","mis":"K5-2-u5-X09"},{"t":"짐작이 긴가","mis":"K5-2-u5-X09"},{"t":"친구들이 많이 찬성하는가","mis":"K5-2-u5-X10"}],"explanation":["재미는 기준이 아니에요.","길이는 기준이 아니에요.","근거가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#21','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C29',3,'mc','auto','같은 글을 두고 해석이 갈릴 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u5-X10','K5-2-u5-X29']::text[],false,'{"seq":21,"concept":"K5-2-u5-C29","difficulty":3,"kind":"mc","stem":"같은 글을 두고 해석이 갈릴 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"서로 근거를 말하고 글 속 단서와 더 잘 맞는 해석을 함께 찾는다","correct":true},{"t":"내 해석만 옳다고 우긴다","mis":"K5-2-u5-X10"},{"t":"근거는 따지지 않고 다 맞다고 한다","mis":"K5-2-u5-X29"},{"t":"해석이 갈리면 그 글은 나쁜 글이다","mis":"K5-2-u5-X29"}],"explanation":["우기지 않아요.","근거를 따져요.","함께 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#22','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C35',3,'error','auto','친구가 쓴 쪽지예요. 낱말을 바르게 쓰지 않은 것은 어느 것인가요?',ARRAY['K5-2-u5-X35','K5-2-u5-X36']::text[],false,'{"seq":22,"concept":"K5-2-u5-C35","difficulty":3,"kind":"error","stem":"친구가 쓴 쪽지예요. 낱말을 바르게 쓰지 않은 것은 어느 것인가요?","options":[{"t":"「해쌀로 지은 밥이 고소했어.」","correct":true,"mis_target":"K5-2-u5-X35"},{"t":"「좁쌀이 노랗고 동글동글해.」","mis":"K5-2-u5-X36"},{"t":"「암탉이 알을 낳았어.」","mis":"K5-2-u5-X36"}],"explanation":["바르게 썼어요.","바르게 썼어요.","햅쌀이 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#23','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C35',4,'essay','teacher','ㅂ 소리가 덧나는 낱말 하나와 ㅎ 소리가 덧나는 낱말 하나를 골라 각각 짧은 문장을 쓰고, 어떤 두 낱말이 어울렸는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u5-C35","difficulty":4,"kind":"essay","stem":"ㅂ 소리가 덧나는 낱말 하나와 ㅎ 소리가 덧나는 낱말 하나를 골라 각각 짧은 문장을 쓰고, 어떤 두 낱말이 어울렸는지 쓰세요.","answer_guide":{"answer":"예: 「농부가 논에 볍씨를 뿌렸다.」 — 벼와 씨가 어울렸다. 「마당에서 수탉이 힘차게 울었다.」 — 수와 닭이 어울렸다.","scoring_points":["ㅂ 소리 낱말로 문장을 썼는가","ㅎ 소리 낱말로 문장을 썼는가","어울린 두 낱말을 바르게 썼는가"]},"explanation":["ㅂ 소리 낱말이에요.","ㅎ 소리 낱말이에요.","어울린 낱말을 밝혀요."],"asset":{"type":"passage","lines":["벼 + 씨 → 볍씨 · 해 + 쌀 → 햅쌀 · 메 + 쌀 → 멥쌀 · 조 + 쌀 → 좁쌀","수 + 닭 → 수탉 · 암 + 닭 → 암탉","머리 + 가락 → 머리카락 · 안 + 밖 → 안팎 · 살 + 고기 → 살코기"],"title":"두 낱말이 어울릴 때 소리가 덧나는 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#24','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C34',4,'essay','teacher','광고나 뉴스, 영상 가운데 하나를 떠올려 드러나지 않은 뜻이나 만든 사람의 의도를 짐작해 쓰고, 그렇게 짐작한 단서를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u5-C34","difficulty":4,"kind":"essay","stem":"광고나 뉴스, 영상 가운데 하나를 떠올려 드러나지 않은 뜻이나 만든 사람의 의도를 짐작해 쓰고, 그렇게 짐작한 단서를 쓰세요.","answer_guide":{"answer":"예: 운동화 광고에서 유명한 선수가 그 신발을 신고 빠르게 달린다. 이 신발을 신으면 나도 빨리 달릴 수 있다고 느끼게 해서 신발을 사게 하려는 의도가 있다. 선수가 웃으며 신발을 크게 보여 주는 장면이 단서이다.","scoring_points":["광고·뉴스·영상 하나를 골랐는가","드러나지 않은 뜻이나 의도를 짐작했는가","단서를 썼는가"]},"explanation":["하나를 골라요.","의도를 짐작해요.","단서를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_c#25','kor',5,2,'u5','','g5_2_kor_u5_review_c','unit_review','K5-2-u5-C10',4,'essay','teacher','「골목의 화분」이나 「텃밭의 빈 의자」를 읽고 친구와 짐작이 달랐던 점을 하나 떠올려, 서로 다른 짐작을 견주는 대화를 근거와 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u5-C10","difficulty":4,"kind":"essay","stem":"「골목의 화분」이나 「텃밭의 빈 의자」를 읽고 친구와 짐작이 달랐던 점을 하나 떠올려, 서로 다른 짐작을 견주는 대화를 근거와 함께 쓰세요.","answer_guide":{"answer":"예: 나 — 「할아버지는 아파서 못 나오신 것 같아. 모자도 안 보였잖아.」 친구 — 「나는 멀리 사는 가족을 보러 가신 것 같아. 며칠 뒤 돌아오셨잖아.」 나 — 「둘 다 단서가 있네. 글에 쓰여 있지 않으니 근거를 들어 함께 짐작하면 되겠다.」","scoring_points":["서로 다른 짐작이 드러나는가","짐작마다 근거가 있는가","견주는 태도가 드러나는가"]},"explanation":["다른 짐작이에요.","근거를 들어요.","견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#1','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C9',1,'ox','auto','근거 없이 떠오르는 대로 지어낸 짐작도 추론이에요.',ARRAY['K5-2-u5-X09']::text[],false,'{"seq":1,"concept":"K5-2-u5-C9","difficulty":1,"kind":"ox","stem":"근거 없이 떠오르는 대로 지어낸 짐작도 추론이에요.","answer":"X","reason_options":[{"t":"추론은 단서나 경험·지식이라는 근거를 바탕으로 하기 때문에","correct":true},{"t":"짐작이면 무엇이든 추론이기 때문에","mis":"K5-2-u5-X09"}],"mis":"K5-2-u5-X09","explanation":["지어낸 것은 추론이 아니에요.","근거가 있어야 해요.","상상과 추론은 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#2','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C35',1,'mc','auto','「해」와 「쌀」이 어울려 그해에 새로 난 쌀을 뜻하는 낱말은 어느 것인가요?',ARRAY['K5-2-u5-X35']::text[],false,'{"seq":2,"concept":"K5-2-u5-C35","difficulty":1,"kind":"mc","stem":"「해」와 「쌀」이 어울려 그해에 새로 난 쌀을 뜻하는 낱말은 어느 것인가요?","options":[{"t":"햅쌀","correct":true},{"t":"해쌀","mis":"K5-2-u5-X35"},{"t":"햇쌀","mis":"K5-2-u5-X35"},{"t":"햅살","mis":"K5-2-u5-X35"}],"explanation":["ㅂ 소리가 빠졌어요.","받침이 달라요.","ㅂ 소리가 덧나 햅쌀이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#3','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C17',1,'ox','auto','「책은 창문이에요.」처럼 쓰는 것은 틀린 말이라 고쳐야 해요.',ARRAY['K5-2-u5-X17']::text[],false,'{"seq":3,"concept":"K5-2-u5-C17","difficulty":1,"kind":"ox","stem":"「책은 창문이에요.」처럼 쓰는 것은 틀린 말이라 고쳐야 해요.","answer":"X","reason_options":[{"t":"숨은 뜻을 담아 생각을 생생하게 전하는 함축된 표현이기 때문에","correct":true},{"t":"책은 진짜 창문이 아니기 때문에","mis":"K5-2-u5-X17"}],"mis":"K5-2-u5-X17","explanation":["틀린 말이 아니에요.","숨은 뜻이 있어요.","함축된 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#4','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C28',1,'ox','auto','이야기 속 인물이 한 말은 늘 글쓴이의 의도와 같아요.',ARRAY['K5-2-u5-X28']::text[],false,'{"seq":4,"concept":"K5-2-u5-C28","difficulty":1,"kind":"ox","stem":"이야기 속 인물이 한 말은 늘 글쓴이의 의도와 같아요.","answer":"X","reason_options":[{"t":"인물의 말과 글쓴이의 의도가 정반대일 수도 있기 때문에","correct":true},{"t":"글쓴이가 인물의 말을 썼으니 같기 때문에","mis":"K5-2-u5-X28"}],"mis":"K5-2-u5-X28","explanation":["같지 않을 수 있어요.","글 전체를 봐요.","인물의 말 ≠ 의도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#5','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C12',1,'mc','auto','할머니가 화분을 내놓는 까닭이 글에 쓰여 있나요?',ARRAY['K5-2-u5-X13','K5-2-u5-X12']::text[],false,'{"seq":5,"concept":"K5-2-u5-C12","difficulty":1,"kind":"mc","stem":"할머니가 화분을 내놓는 까닭이 글에 쓰여 있나요?","options":[{"t":"쓰여 있지 않아 단서로 짐작해야 한다","correct":true},{"t":"마지막 문장에 그대로 쓰여 있다","mis":"K5-2-u5-X13"},{"t":"제목에 그대로 쓰여 있다","mis":"K5-2-u5-X13"},{"t":"쓰여 있지 않으니 생각할 필요가 없다","mis":"K5-2-u5-X12"}],"explanation":["쓰여 있지 않아요.","쓰여 있지 않아요.","단서로 빈 곳을 채워요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#6','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C33',1,'mc','auto','「마음에 먹구름이 몰려왔어.」라는 카드를 쓴 친구에게 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X18','K5-2-u5-X33']::text[],false,'{"seq":6,"concept":"K5-2-u5-C33","difficulty":1,"kind":"mc","stem":"「마음에 먹구름이 몰려왔어.」라는 카드를 쓴 친구에게 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「무슨 일이 있었어? 이야기해 주면 들을게.」","correct":true},{"t":"「먹구름은 비를 몰고 와.」","mis":"K5-2-u5-X18"},{"t":"「별것 아니네.」","mis":"K5-2-u5-X33"},{"t":"「나랑은 상관없어.」","mis":"K5-2-u5-X33"}],"explanation":["겉뜻으로만 읽었어요.","마음을 가볍게 여겼어요.","마음을 알아주는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#7','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C3',1,'mc','auto','생활 속에서 추론한 예는 어느 것인가요?',ARRAY['K5-2-u5-X03']::text[],false,'{"seq":7,"concept":"K5-2-u5-C3","difficulty":1,"kind":"mc","stem":"생활 속에서 추론한 예는 어느 것인가요?","options":[{"t":"동생이 눈을 비비며 하품하는 것을 보고 졸리다고 짐작했다","correct":true},{"t":"시계를 보고 시각을 읽었다","mis":"K5-2-u5-X03"},{"t":"달력에 적힌 생일을 그대로 읽었다","mis":"K5-2-u5-X03"},{"t":"추론은 글을 읽을 때만 하니 예가 없다","mis":"K5-2-u5-X03"}],"explanation":["쓰인 것을 읽었어요.","쓰인 것을 읽었어요.","몸짓을 단서로 짐작했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#8','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C1',1,'ox','auto','「텃밭의 빈 의자」에는 할아버지가 왜 오지 않았는지 쓰여 있지 않지만 단서로 짐작해 볼 수 있어요.',ARRAY['K5-2-u5-X01']::text[],false,'{"seq":8,"concept":"K5-2-u5-C1","difficulty":1,"kind":"ox","stem":"「텃밭의 빈 의자」에는 할아버지가 왜 오지 않았는지 쓰여 있지 않지만 단서로 짐작해 볼 수 있어요.","answer":"O","reason_options":[{"t":"의자가 비고 모자가 보이지 않다가 다시 돌아온 단서를 함께 생각할 수 있기 때문에","correct":true},{"t":"쓰여 있지 않은 내용은 알 수 없기 때문에","mis":"K5-2-u5-X01"}],"mis":"K5-2-u5-X01","explanation":["단서가 있어요.","함께 생각해요.","짐작할 수 있어요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#9','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C22',2,'mc','auto','글쓴이가 「골목에 꽃이 많아졌어요.」라고 쓰지 않고 「골목이 계절마다 옷을 갈아입어요.」라고 쓴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X22','K5-2-u5-X18']::text[],false,'{"seq":9,"concept":"K5-2-u5-C22","difficulty":2,"kind":"mc","stem":"글쓴이가 「골목에 꽃이 많아졌어요.」라고 쓰지 않고 「골목이 계절마다 옷을 갈아입어요.」라고 쓴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"달라진 골목의 생기를 더 생생하게 느끼게 하려고","correct":true},{"t":"읽는 사람을 헷갈리게 하려고","mis":"K5-2-u5-X22"},{"t":"골목에 옷 가게가 있음을 알리려고","mis":"K5-2-u5-X18"},{"t":"문장을 길게 쓰려고","mis":"K5-2-u5-X22"}],"explanation":["헷갈리게 하려는 것이 아니에요.","사전 뜻으로 읽었어요.","생생하게 전해요."],"asset":{"type":"passage","lines":["우리 동네 낡은 골목은 늘 회색빛이었어요.","사람들은 고개를 숙인 채 빠르게 지나갔지요.","어느 봄날, 맨 끝 집 할머니가 대문 앞에 작은 화분 하나를 내놓았어요.","다음 날에도, 그다음 날에도 화분은 하나씩 늘었어요.","「왜 날마다 내놓으세요?」 이웃이 묻자 할머니는 웃기만 했어요.","세 해가 지나자 이웃들도 자기 집 앞에 화분을 내놓았어요.","사람들이 걸음을 늦추고 꽃 이름을 물어요.","회색 골목이 이제는 계절마다 옷을 갈아입어요."],"title":"골목의 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#10','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C10',2,'mc','auto','할머니의 마음을 짐작한 두 친구의 말을 바르게 견준 것은 어느 것인가요?',ARRAY['K5-2-u5-X10','K5-2-u5-X08','K5-2-u5-X01']::text[],false,'{"seq":10,"concept":"K5-2-u5-C10","difficulty":2,"kind":"mc","stem":"할머니의 마음을 짐작한 두 친구의 말을 바르게 견준 것은 어느 것인가요?","options":[{"t":"웃기만 했다는 단서는 두 짐작에 모두 열려 있어, 저마다 글 속 근거를 들어 말하면 된다","correct":true},{"t":"할머니의 마음은 꼭 하나로만 정해야 한다","mis":"K5-2-u5-X10"},{"t":"근거 없이 말해도 상관없다","mis":"K5-2-u5-X08"},{"t":"쓰여 있지 않으니 짐작을 그만둔다","mis":"K5-2-u5-X01"}],"explanation":["하나가 아닐 수 있어요.","근거가 필요해요.","두 친구 모두 근거를 들었어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"할머니는 이웃들이 화분을 따라 내놓기를 바랐을 거야. 이웃들이 따라 했잖아."},{"who":"준서","text":"할머니는 그냥 꽃을 좋아했을 뿐이야. 날마다 화분을 늘렸잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#11','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C35',2,'match','auto','어울린 두 낱말과 바르게 쓴 낱말을 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K5-2-u5-C35","difficulty":2,"kind":"match","stem":"어울린 두 낱말과 바르게 쓴 낱말을 이으세요.","pairs":[{"l":"조 + 쌀","r":"좁쌀"},{"l":"메 + 쌀","r":"멥쌀"},{"l":"살 + 고기","r":"살코기"}],"mis":"K5-2-u5-X35","explanation":["ㅂ 소리가 덧나요.","ㅂ 소리가 덧나요.","ㅎ 소리가 덧나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#12','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C5',2,'ox','auto','「텃밭의 빈 의자」로 추론하기 전에 글에 드러난 사실부터 정확히 확인하면 좋아요.',ARRAY['K5-2-u5-X05']::text[],false,'{"seq":12,"concept":"K5-2-u5-C5","difficulty":2,"kind":"ox","stem":"「텃밭의 빈 의자」로 추론하기 전에 글에 드러난 사실부터 정확히 확인하면 좋아요.","answer":"O","reason_options":[{"t":"드러난 사실을 바르게 알아야 그 위에서 짐작할 수 있기 때문에","correct":true},{"t":"짐작부터 하는 것이 더 빠르기 때문에","mis":"K5-2-u5-X05"}],"mis":"K5-2-u5-X05","explanation":["사실부터 알아요.","그 위에서 짐작해요.","차례가 중요해요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#13','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C21',2,'mc','auto','「해가 났어요」의 숨은 뜻을 짐작할 때 도움이 되는 경험은 어느 것인가요?',ARRAY['K5-2-u5-X21']::text[],false,'{"seq":13,"concept":"K5-2-u5-C21","difficulty":2,"kind":"mc","stem":"「해가 났어요」의 숨은 뜻을 짐작할 때 도움이 되는 경험은 어느 것인가요?","options":[{"t":"비 온 뒤 해가 나서 마음까지 개운해진 경험","correct":true},{"t":"해를 그림으로 그린 경험","mis":"K5-2-u5-X21"},{"t":"해가 지는 시각을 잰 경험","mis":"K5-2-u5-X21"},{"t":"우산을 잃어버린 경험","mis":"K5-2-u5-X21"}],"explanation":["뜻과 닿지 않아요.","뜻과 닿지 않아요.","마음이 밝아진 경험이 닿아요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#14','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C24',2,'mc','auto','「텃밭의 빈 의자」의 소재와 글쓴이의 의도를 바르게 구별한 것은 어느 것인가요?',ARRAY['K5-2-u5-X24']::text[],false,'{"seq":14,"concept":"K5-2-u5-C24","difficulty":2,"kind":"mc","stem":"「텃밭의 빈 의자」의 소재와 글쓴이의 의도를 바르게 구별한 것은 어느 것인가요?","options":[{"t":"소재는 텃밭 의자와 할아버지 이야기이고, 의도는 서로를 생각하는 작은 관심이 마음을 따뜻하게 한다는 생각이다","correct":true},{"t":"소재와 의도는 같은 말이다","mis":"K5-2-u5-X24"},{"t":"의도는 상추를 기르는 방법이다","mis":"K5-2-u5-X24"},{"t":"의도는 할아버지의 모자이다","mis":"K5-2-u5-X24"}],"explanation":["둘은 달라요.","소재에 머물렀어요.","소재와 의도를 갈라 봐요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#15','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C11',2,'ox','auto','이야기를 간추릴 때는 중요한 장면만 골라 인물의 행동과 변화를 써요.',ARRAY['K5-2-u5-X11']::text[],false,'{"seq":15,"concept":"K5-2-u5-C11","difficulty":2,"kind":"ox","stem":"이야기를 간추릴 때는 중요한 장면만 골라 인물의 행동과 변화를 써요.","answer":"O","reason_options":[{"t":"사건을 다 늘어놓지 않아야 이야기의 뼈대가 보이기 때문에","correct":true},{"t":"작은 일까지 모두 써야 빠짐이 없기 때문에","mis":"K5-2-u5-X11"}],"mis":"K5-2-u5-X11","explanation":["중요한 장면만이에요.","뼈대가 보여요.","간추리기의 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#16','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C30',2,'ox','auto','감정을 함축된 표현으로 말하면 듣는 사람이 단서로 마음을 짐작하며 더 깊이 공감할 수 있어요.',ARRAY['K5-2-u5-X30']::text[],false,'{"seq":16,"concept":"K5-2-u5-C30","difficulty":2,"kind":"ox","stem":"감정을 함축된 표현으로 말하면 듣는 사람이 단서로 마음을 짐작하며 더 깊이 공감할 수 있어요.","answer":"O","reason_options":[{"t":"빗댄 표현이 마음의 모습과 깊이를 그려 주기 때문에","correct":true},{"t":"감정은 감정 낱말로만 알아들을 수 있기 때문에","mis":"K5-2-u5-X30"}],"mis":"K5-2-u5-X30","explanation":["깊이 전해져요.","짐작하며 들어요.","공감이 깊어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#17','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C29',3,'mc','auto','「할아버지는 쪽지가 귀찮아서 말이 없었을 거야.」라는 해석에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X29','K5-2-u5-X05','K5-2-u5-X13']::text[],false,'{"seq":17,"concept":"K5-2-u5-C29","difficulty":3,"kind":"mc","stem":"「할아버지는 쪽지가 귀찮아서 말이 없었을 거야.」라는 해석에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쪽지를 한 장씩 펴 본 모습과 해가 났다는 마지막 문장과 맞지 않아 근거가 약하다","correct":true},{"t":"해석은 다 다르니 근거를 따질 필요가 없다","mis":"K5-2-u5-X29"},{"t":"글에 그렇게 쓰여 있으니 맞는 해석이다","mis":"K5-2-u5-X05"},{"t":"마지막 문장만 보면 맞다","mis":"K5-2-u5-X13"}],"explanation":["근거를 따져요.","글에 쓰여 있지 않아요.","글 속 근거와 맞지 않아요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#18','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C22',3,'mc','auto','함축된 표현을 쓴 이야기를 읽을 때 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X22','K5-2-u5-X17','K5-2-u5-X18']::text[],false,'{"seq":18,"concept":"K5-2-u5-C22","difficulty":3,"kind":"mc","stem":"함축된 표현을 쓴 이야기를 읽을 때 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"짧은 표현 속 숨은 뜻을 찾으며 글쓴이의 생각을 더 깊이 느낄 수 있다","correct":true},{"t":"숨은 뜻을 몰라도 되니 빨리 읽을 수 있다","mis":"K5-2-u5-X22"},{"t":"사실과 달라 믿을 수 없다","mis":"K5-2-u5-X17"},{"t":"사전 뜻만 알면 된다","mis":"K5-2-u5-X18"}],"explanation":["숨은 뜻이 중요해요.","틀린 말이 아니에요.","깊이 느낄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#19','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C30',3,'mc','auto','「긴장」을 함축된 표현으로 가장 잘 나타낸 것은 어느 것인가요?',ARRAY['K5-2-u5-X31','K5-2-u5-X30','K5-2-u5-X18']::text[],false,'{"seq":19,"concept":"K5-2-u5-C30","difficulty":3,"kind":"mc","stem":"「긴장」을 함축된 표현으로 가장 잘 나타낸 것은 어느 것인가요?","options":[{"t":"「손바닥에 땀이 송골송골, 심장이 북처럼 둥둥 울려.」","correct":true},{"t":"「나는 지금 긴장돼.」","mis":"K5-2-u5-X31"},{"t":"「오늘은 월요일이야.」","mis":"K5-2-u5-X30"},{"t":"「심장은 몸속에 있어.」","mis":"K5-2-u5-X18"}],"explanation":["감정 낱말이에요.","감정과 관계없어요.","몸의 변화를 빗댔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#20','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C10',3,'mc','auto','추론하며 읽을 때 정답 맞히기보다 중요한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X10','K5-2-u5-X05']::text[],false,'{"seq":20,"concept":"K5-2-u5-C10","difficulty":3,"kind":"mc","stem":"추론하며 읽을 때 정답 맞히기보다 중요한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 단서와 경험·지식으로 짐작했는지 생각하는 과정","correct":true},{"t":"누가 먼저 맞히는지 겨루기","mis":"K5-2-u5-X10"},{"t":"선생님 답을 외우기","mis":"K5-2-u5-X10"},{"t":"글을 빨리 넘기기","mis":"K5-2-u5-X05"}],"explanation":["겨루지 않아요.","외우기가 아니에요.","과정이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#21','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C27',3,'mc','auto','글쓴이가 비슷한 장면을 되풀이해 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X27']::text[],false,'{"seq":21,"concept":"K5-2-u5-C27","difficulty":3,"kind":"mc","stem":"글쓴이가 비슷한 장면을 되풀이해 쓴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 장면에 담긴 뜻을 독자가 놓치지 않게 강조하려고","correct":true},{"t":"글자 수를 채우려고","mis":"K5-2-u5-X27"},{"t":"실수로 두 번 썼기 때문에","mis":"K5-2-u5-X27"},{"t":"의도와 관계없이 그냥","mis":"K5-2-u5-X27"}],"explanation":["까닭이 아니에요.","실수가 아니에요.","되풀이는 강조예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#22','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C36',3,'mc','auto','「머리카락」, 「안팎」을 소리 나는 대로 적는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u5-X36','K5-2-u5-X35']::text[],false,'{"seq":22,"concept":"K5-2-u5-C36","difficulty":3,"kind":"mc","stem":"「머리카락」, 「안팎」을 소리 나는 대로 적는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 낱말이 어울릴 때 원래 없던 ㅎ 소리가 덧나기 때문에","correct":true},{"t":"원래 낱말 모양 그대로 적어야 하기 때문에","mis":"K5-2-u5-X36"},{"t":"ㅂ 소리가 덧나기 때문에","mis":"K5-2-u5-X35"},{"t":"받침을 빼고 적어야 하기 때문에","mis":"K5-2-u5-X36"}],"explanation":["소리 나는 대로 적어요.","ㅎ 소리예요.","ㅎ 소리가 덧나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#23','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C24',4,'essay','teacher','「텃밭의 빈 의자」에서 글쓴이의 의도를 한 문장으로 쓰고, 의도를 짐작하게 한 함축된 표현이나 장면을 두 가지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u5-C24","difficulty":4,"kind":"essay","stem":"「텃밭의 빈 의자」에서 글쓴이의 의도를 한 문장으로 쓰고, 의도를 짐작하게 한 함축된 표현이나 장면을 두 가지 쓰세요.","answer_guide":{"answer":"예: 서로를 생각하는 작은 관심이 사람의 마음을 따뜻하게 한다. 아이들이 「상추가 할아버지를 기다려요.」라고 쪽지를 놓은 장면과, 할아버지가 쪽지를 읽은 날 「비가 그치고 해가 났어요.」라는 마지막 문장이 단서이다.","scoring_points":["의도를 한 문장으로 썼는가","단서 두 가지를 썼는가","단서와 의도가 이어지는가"]},"explanation":["한 문장이에요.","단서 둘이에요.","이어지게 써요."],"asset":{"type":"passage","lines":["학교 텃밭 끝에는 낡은 나무 의자가 하나 있었어요.","경비 할아버지는 날마다 그 의자에 앉아 아이들이 심은 상추를 바라보았어요.","어느 날부터 의자가 비어 있었어요. 할아버지의 모자도 보이지 않았어요.","아이들은 상추에 물을 주며 자꾸 의자 쪽을 돌아보았어요.","며칠 뒤, 의자 위에 아이들이 쓴 쪽지가 하나둘 놓이기 시작했어요.","「할아버지, 상추가 할아버지를 기다려요.」","다시 돌아온 할아버지는 쪽지를 한 장씩 펴 보며 한참 말이 없었어요.","그날 텃밭에는 오래 내리던 비가 그치고 해가 났어요."],"title":"텃밭의 빈 의자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#24','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C29',4,'essay','teacher','할머니의 마음을 짐작한 두 친구의 말 가운데 더 그럴듯한 쪽을 고르거나 두 생각을 함께 담은 내 짐작을 쓰고, 글 속 근거를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u5-C29","difficulty":4,"kind":"essay","stem":"할머니의 마음을 짐작한 두 친구의 말 가운데 더 그럴듯한 쪽을 고르거나 두 생각을 함께 담은 내 짐작을 쓰고, 글 속 근거를 쓰세요.","answer_guide":{"answer":"예: 할머니는 꽃을 좋아했고, 그 마음이 이웃에게도 번지기를 바랐을 것이다. 날마다 화분을 하나씩 늘린 모습은 꽃을 좋아하는 마음을, 세 해 뒤 이웃들이 따라 화분을 내놓은 장면은 이웃에게 번지기를 바란 마음을 보여 준다.","scoring_points":["짐작을 썼는가","글 속 근거를 썼는가","근거와 짐작이 맞는가"]},"explanation":["짐작해요.","근거를 들어요.","맞는지 살펴요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"할머니는 이웃들이 화분을 따라 내놓기를 바랐을 거야. 이웃들이 따라 했잖아."},{"who":"준서","text":"할머니는 그냥 꽃을 좋아했을 뿐이야. 날마다 화분을 늘렸잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u5_review_d#25','kor',5,2,'u5','','g5_2_kor_u5_review_d','unit_review','K5-2-u5-C32',4,'essay','teacher','감정 카드 활동을 한다면 친구의 카드를 보고 마음을 짐작하고 확인하고 공감하는 차례를 쓰고, 각 차례에서 할 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u5-C32","difficulty":4,"kind":"essay","stem":"감정 카드 활동을 한다면 친구의 카드를 보고 마음을 짐작하고 확인하고 공감하는 차례를 쓰고, 각 차례에서 할 말을 쓰세요.","answer_guide":{"answer":"예: 짐작하기 — 「마음에 먹구름이 끼었다니 속상한 일이 있었나 봐.」 확인하기 — 「혹시 속상한 일이 있었어? 내 짐작이 맞아?」 공감하기 — 「그런 일이 있었구나. 많이 속상했겠다. 내가 곁에 있을게.」","scoring_points":["짐작·확인·공감의 차례를 썼는가","차례마다 할 말을 썼는가","친구를 존중하는 말인가"]},"explanation":["세 차례예요.","할 말을 써요.","존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
